  /* Current Partition */      
 /* Manali Trading Module */  
  select @row= count('x') from inserted where OdPrtKey=@wCurrPrtn and    
   ((Select PValue from Param where PTyp= 'TC' and PMCd= OdTc) <> 'QB' And  
