   OdExpDelDt < (Select OmDt from OrdMst where OmIdNo=OdOmIdNo and OmCoCd= OdCoCd     
    and OmTc= OdTc and OmYy= OdYy and OmChr= OdChr and OmNo= OdNo and OmPrtKey=OdPrtKey))     
    
/* **** Zubin 211 **** */     
  if @row> 0     
