  /****** Order Quantity should be >= Export Quantity ******/    
  /* Current Partition */    
 select @row= count('x') from inserted where @wIsJLTc = 'N' and OdPrtKey=@wCurrPrtn and    
   Round(OdOrdQty, 1) < Round(OdExpQty, 1)     
  
  if @row> 0     
