     and ins.OmCoCd= del.OmCoCd and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy   
     and ins.OmChr= del.OmChr and ins.OmNo= del.OmNo and ins.OmChgPtrOnStwYN= del.OmChgPtrOnStwYN)   
   and Exists (select 'x' from OrdDsg where OdCoCd= OmCoCd and OdTc= OmTc and OdYy= OmYy and   
     OdChr= OmChr and OdNo= OmNo and OdPrtKey= OmPrtKey )   
  If @Row > 0  
  begin   
   Select @ErrMsg= 'Cannot Change ''Change Pointer On STW (Y/N) When Designs Exist '''  
   GoTo ErrHndlr  
  end  
  
