  /* ****** Manali 3.03 02/07/08 - OmLkUpMetLs ****** */  
  Select @row= count('x') from inserted Ins where Ins.OmLkUpMetLs <> '' and   
   Ins.OmLkUpMetLs <> IsNull((Select Del.OmLkUpMetLs From Deleted Del Where   
    Ins.OmIdNo=Del.OmIdNo and Ins.OmCoCd = Del.OmCoCd And Ins.OmTc = Del.OmTc And Ins.OmYy = Del.OmYy And  
    Ins.OmChr = Del.OmChr And Ins.OmNo = Del.OmNo And Ins.OmPrtKey=Del.OmPrtKey), '') and       not exists(Select 'x' from CustMst where CmCtg='P' and CmCd=Ins.OmLkUpMetLs and CmValidYN='Y')  
  If @row > 0   
  Begin   
   Select @errmsg= 'Invalid Metal Loss Look Up Customer'  
  goto ErrHndlr  
  End  
  /* ****** Manali 3.03 02/07/08 - OmLkUpMetLs ****** */    
  
  /* *** Manali 3.03 - 02/07/08 - OmLkUpRmRt, OmLkUpLabRt, OmLkUpMetLs cannot edit when dsg rec exists **** */  
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and  
   not exists (select 'x' from deleted del where ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
    and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr and ins.OmNo= del.OmNo   
    and (ins.OmLkUpRmRt = del.OmLkUpRmRt Or ins.OmLkUpLabRt= del.OmLkUpLabRt Or ins.OmLkUpMetLs = del.OmLkUpMetLs))  
   and exists(Select 'x' from OrdDsg where OdPrtKey=OmPrtKey and OdOmIdNo=OmIdNo and OdCoCd= OmCoCd   
    and OdTc= OmTc and OdYy= OmYy and OdChr= OmChr and OdNo= OmNo)    
  if @row> 0   
