/*  ###  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ###  */  
  /******  OmHCtCd  =  Blank or CmCd from CustMst (CmCtg= 'T')  ******/  
  /* Current Partition */   
  select @row= count('x') from Inserted Ins Where OmPrtKey=@wCurrPrtn and Ins.OmHCtCd <> '' And  
   Ins.OmHCtCd <> IsNull((Select Del.OmHCtCd From Deleted Del Where Ins.OmIdNo=Del.OmIdNo and  
    Ins.OmCoCd = Del.OmCoCd And Ins.OmTc = Del.OmTc And Ins.OmYy = Del.OmYy And   
    Ins.OmChr = Del.OmChr And Ins.OmNo = Del.OmNo and Ins.OmPrtKey=Del.OmPrtKey), '')  And   
   Not Exists (select 'x' from CustMst where CmCtg= 'T' And CmCd= Ins.OmHCtCd And CmValidYN = 'Y')   
  if @row> 0  
  begin  
   select @errmsg= 'Contractor Code Not Defined / Invalid'  
   goto ErrHndlr  
  end  
  
  /******  OmLockYN =  valid  PMCd ('YN')  ******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and  
   Not Exists (select 'x' from Param where PTyp= 'YN' and PmCd= OmLockYN)   
  if @row> 0  
  begin  
   select @errmsg= 'Order/PDC/Quotation Lock (Y/N) Not Defined'  
   goto ErrHndlr  
  end  
/*  ###  Manoj  ###  */  
 /*** Geeta***Crm**2.12 ***/  
 /****** if OmChr<>'WEB' then OmSubmitYN='' and OmOmAckYN='' ***/  
  /* Current Partition */  
  select @row= count('x') from inserted   
    where OmPrtKey=@wCurrPrtn and OmChr<>'WEB' and (OmSubmitYN<>'' or OmAckYN<>'')  
  if @row> 0  
  begin  
   select @errmsg= 'Submit/Acknowledge are applicable Only for Web Orders'  
   goto ErrHndlr  
  end   
  
  /*** Geeta***OmChr='WEB' then OmSubmitYN=Valid PMCd ('YN') ***/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and OmChr='WEB' and   
  Not Exists (Select 'x' From Param where PTyp='YN' and PMCd=OmSubmitYN and PSCd='')  
  if @row> 0  
  begin  
   select @errmsg= 'Order Submitted Y/N '  
   goto ErrHndlr  
  end  
   
  /*** Geeta***OmChr='WEB' then OmSubmitYN=Valid PMCd ('YN') ***/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and OmChr='WEB' and   
  Not Exists (Select 'x' From Param where PTyp='YN' and PMCd=OmAckYN and PSCd='')  
  if @row> 0  
  begin  
   select @errmsg= 'Order Acknowledged Y/N '  
   goto ErrHndlr  
  end  
  
  /****** OmSubmitYN='Y' and   OmAckYN='Y'  is allowed Only for OmTcTyp='SO'  and OmChr='WEB'******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and (OmAckYN='Y' Or OmSubmitYN='Y') and   
   ((select PValue  from Param where PTyp='TC' and PMCd=OmTc and PSCd='') in ('MF','QB') Or   
   OmChr<>'WEB' )  
  if @row> 0  
  begin  
   select @errmsg= 'Submitted=''Y'' /Acknowledged=''Y'' is applicable only for Chr=''WEB'' '  
   goto ErrHndlr  
  end  
  
 /****** If  OmSubmitYN  = ‘Y’ then OmSubmitYN cannot  be Changed. ******/  
  /* Current Partition */  
  select @row= count('x') from deleted del where OmPrtKey=@wCurrPrtn and OmSubmitYN='Y'  and   
   Exists(select 'x' from Inserted ins where OmSubmitYN<>'Y' and ins.OmIdNo=del.OmIdNo and ins.OmCoCd=del.OmCoCd and   
   ins.OmTc=del.OmTc and ins.OmYy=del.OmYy and ins.OmChr=del.OmChr and ins.OmNo=del.OmNo )  
  if @row> 0  
  begin  
   select @errmsg= 'Submited Status cannot be changed Once Order is Submitted '  
   goto ErrHndlr  
  end  
   
  /****** If  OmSubmitYN  = ‘N’   then OmAckYN Should be ‘N’  *************/  
  /* Current Partition */  
  select @row= count('x') from Inserted where OmPrtKey=@wCurrPrtn and OmSubmitYN='N'  and  OmAckYN='Y'  
  if @row> 0  
  begin  
   select @errmsg= 'UnSubmitted Order Cannot Be acknowledged '  
   goto ErrHndlr  
  end  
 /****** If  OmAckYN  = ‘Y’ then OmAckYN cannot  be Changed. ******/  
  select @row= count('x') from deleted del where OmAckYN='Y'  and   
   Exists(select 'x' from Inserted ins where OmAckYN<>'Y' and ins.OmIdNo=del.OmIdNo and ins.OmCoCd=del.OmCoCd and   
   ins.OmTc=del.OmTc and ins.OmYy=del.OmYy and ins.OmChr=del.OmChr and ins.OmNo=del.OmNo )  
  if @row> 0  
  begin  
   select @errmsg= 'Acknowledged Status cannot be changed Once Order is Acknowledged'  
   goto ErrHndlr  
  end  
  
  
 /****** If OmChr<>’WEB’ then OmCrmYy,OmCrmChr,OmCrmNo should be blank ******/  
/*  select @row= count('x') from Inserted where OmChr<>'WEB' and   
   ( OmCrmYy <>'' Or OmCrmChr<>'' Or OmCrmNo<>0 )  
  if @row> 0  
  begin  
   select @errmsg= 'Crm Voucher No is applicable only for OmChr=''WEB'''  
   goto ErrHndlr  
  end  
*/  
 /****** If OmChr=’WEB’ then OmCrmYy= Valid (PTyp=’YY’)******/  
  /* Current Partition */  
  select @row= count('x') from Inserted where OmPrtKey=@wCurrPrtn and (OmChr='WEB' or OmCrmYy<>'') and   
   Not Exists(Select 'x' From Param where PTyp='YY' and PMCd=OmCrmYy)  
  if @row> 0  
  begin  
   select @errmsg= 'Yy Not Defined'  
   goto ErrHndlr  
  end  
  
 /****** If OmChr=’WEB’ then OmCrmChr= Valid (cPTyp=’CRMChr’)******/  
  /* Current Partition */  
  select @row= count('x') from Inserted where OmPrtKey=@wCurrPrtn and (OmChr='WEB' or OmCrmChr<>'') and    
   Not Exists(Select 'x' From cParam where cPTyp='CRMCHR' and cPMCd=OmCrmChr)  
  if @row> 0  
  begin  
   select @errmsg= 'Crm Chr Not Defined'  
   goto ErrHndlr  
  end  
   
 /****** If OmChr=’WEB’ then OmCrmChr= Valid (cPTyp=’CRMChr’)******/  
  /* Current Partition */  
  select @row= count('x') from Inserted where OmPrtKey=@wCurrPrtn and OmChr='WEB' and OmCrmNo=0  
  if @row> 0  
  begin  
   select @errmsg= 'Crm Voucher No Cannot be Zero '  
   goto ErrHndlr  
  end  
 /****** On Insert of  OmChr=’WEB’     
  If    cPMCd=OmCrmChr  where cPTyp=’WEBCHR’ and cPValue=’Y’ (Usr Running Sr =’Y’)  then   
  Check OmCrmYy+OmCrmChr+OmCrmNo is Unique  
   If   cPTyp=’CRMCHR’ and cPValue=’N’ (cParam) then   
     Check OmTc+OmCrmYy+OmCrmChr+OmCmCd+OmCrmNo is Unique  
 ******/  
  
 /* Crm Voucher No uniqueness is on complete partition */   
 select @row= count('x') from Inserted ins where OmPrtKey=@wCurrPrtn and OmChr='WEB' and   
  (Select Count('x') From OrdMst Om Join cParam on cPTyp='CRMCHR' and cPMCd=OmCrmChr   and cPSCd=''  
   where  Om.OmCmCd=(Case when cPValue='Y' Then Om.OmCmCd Else Ins.OmCmCd End)  and   
    ins.OmTc=Om.OmTc and ins.OmCrmYy=Om.OmCrmYy  
    and ins.OmCrmChr=Om.OmCrmChr and ins.OmCrmNo=Om.OmCrmNo)>1  
  if @row> 0  
  begin  
   select @errmsg= 'Crm Voucher No. already exists'  
   goto ErrHndlr  
  end  
  
 /****** if OmTcTyp='MF' then OmChr='WEB' ******/  
  /* Current Partition */  
  select @row= count('x') from inserted ins where OmPrtKey=@wCurrPrtn and OmChr<>'WEB' and    
   (select PValue  from Param where PTyp='TC' and PMCd=OmTc and PSCd='')='MF'   
  if @row> 0  
  begin  
   select @errmsg= 'My Favourite is Applicable for Crm i.e OmChr=''WEB'''  
   goto ErrHndlr  
  end  
  
 /****** One 'MF'Permitted per CrmYy/CrmChr******/  
  /* Current Partition */  
  select @row= count('x') from inserted ins where OmPrtKey=@wCurrPrtn and  
   (select PValue  from Param where PTyp='TC' and PMCd=OmTc and PSCd='')='MF' and   
   (Select count('x') From OrdMst Om where Om.OmTc=ins.OmTc and Om.OmCrmYY=ins.omCrmYy and   
     Om.OmCrmChr=ins.OmCrmChr and Om.OmCmCd=ins.OmCmCd)>1  
  if @row> 0  
  begin  
   select @errmsg= 'Only one My Favourite Permitted for Crm Chr and Yy Combination for a Customer'  
   goto ErrHndlr  
  end  
  
 /******  OmPODt, OmPONO cannot be blank for OmTcTyp='SO' and OmChr='WEB' **Crm**212**30/12/05 ******/    
  /* Current Partition */  
  Select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and (OmPONo='' or OmPoDt='01/01/80') and  
   OmChr='WEB' and (select PValue  from Param where PTyp='TC' and PMCd=OmTc and PSCd='') ='SO'  
  If @row> 0   
  Begin  
   Select @errmsg= 'PoNo,PoDt Cannot Be Blank for Web Orders'  
   Goto ErrHndlr  
  End  
  
 /* CRM Check included in EMR in 2.14.0 Next */  
 /****** Unique PO Number will go on the complete partition ******/    
  Select @row= Count('x') From Inserted Ins   
    Where OmPrtKey=@wCurrPrtn and (Select Count('x') From OrdMst Om Where Om.OmCmCd=Ins.OmCmCd and Om.OmTc=Ins.OmTc and   
     Om.OmPoNo=ins.OmPoNo)> 1   
    And Exists (Select 'x' From SysDb Where SysId='CRM')   
    If @row> 0   
    Begin  
      Select @ErrMsg= 'Po No Should Be Unique for a Customer'  
      Goto ErrHndlr  
    End  
 /* CRM Check included in EMR in 2.14.0 Next */  
/*** Jay 3.3(FG) ***/  
  If exists (Select 'x' from Inserted   
   where exists (Select 'x' from Param where PTyp= 'TC' and PValue= 'FG' and PMCd= OmTc) )  
  Begin  
   /*** Jay 3.3(FG)***/  
   /********** If Tc in 'fin', 'fot' then OmFrDmLoc, omFrRmDc, OmTODmLoc, OmToDmDc should be blank *************/  
   /* Current Partition */  
   Select @Row= Count('x') From Inserted Ins Where OmPrtKEy=@wCurrPrtn and  
    (OmFrDmLoc= '' or OmFrDmDc= '' or OmToDmLoc= '' or OmToDmDc= '')  
     If @Row> 0  
   begin  
    Select @ErrMsg= 'From/To Dm Loc, From/To Dm DC Should Not Be Blank'  
      GoTo ErrHndlr  
   end  
  
   /*** Jay 3.3(FG) -Current Partition ***/  
   select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and    
    not (select count('x') from Param where PTyp='DC' and (PMCd=OmFrDmDc or PMCd=OmToDmDc) and PSCd='') =2    
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid OmFrDmDc or OmToDmDc'  
    goto ErrHndlr    
   end     
  
   /* Current Partition */  
   select @row= count('x') from inserted Ins where OmPRtKey=@wCurrPrtn and   
     Ins.OmFrDmLoc = Ins.OmToDmLoc and (Ins.OmFrDmLoc <> '' or  
     Ins.OmToDmLoc <> '')  
     if @row>0  
     begin  
       select @errmsg= 'To Loc and From Loc cannot be same'  
       goto ErrHndlr  
     end  
  
   /*** Jay 3.3(FG) - Current Partition ***/  
   select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and    
   exists (select 'x' from Loc where LocCoCd= OmCocd and LocTyp in ('F','XS')  
      and LocCd=OmFrDmLoc and LocCd=OmToDmLoc and LocPrntYn= 'N'  And LocValidYN='Y')   
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid Sales Location Code/ Not Defined'    
    goto ErrHndlr    
   end       
   /****** OmFrDmLoc & OmToDmLoc both should not be of LocTyp= 'F'/'XS' **********/  
   /* Current Partition */  
   Select @Row=Count('x') From Inserted Ins Where OmPrtKey=@wCurrPrtn and    
     (Exists (Select 'x' From Loc where LocCoCd= Ins.OmCoCd and LocTyp= 'F' and LocCd = Ins.OmFrDmLoc)  
    and Exists (Select 'x' From Loc where LocCoCd= Ins.OmCoCd and LocTyp= 'F' and LocCd = Ins.OmToDmLoc))  
    or (Exists (Select 'x' From Loc where LocCoCd= Ins.OmCoCd and LocTyp= 'XS' and LocCd = Ins.OmFrDmLoc)  
    and Exists (Select 'x' From Loc where LocCoCd= Ins.OmCoCd and LocTyp= 'XS' and LocCd = Ins.OmToDmLoc))  
     If @Row>0  
   begin  
    Select @ErrMsg= 'Both From & To Locs Should Not Be the Same Location Type ''F'' Or ''XS'' '  
    GoTo ErrHndlr  
   end  
  
   /****** InFrRmLoc or InToRmLoc Should Have LocTyp= 'XS' ********/  
   /* Current Partition */  
   /*** Jay 3.3(FG) ***/  
   Select @Row= Count('x') From Inserted Ins where OmPrtKey=@wCurrPrtn   
    and Not Exists (Select 'x' From Loc where LocCoCd = OmCoCd   
     and LocTyp= 'XS' and (LocCd= OmFrDmLoc or LocCd = OmToDmLoc))  
     If @Row> 0  
   begin  
    Select @ErrMsg= 'Atleast One DM Loc Must Be Of Type ''XS'' '  
      GoTo ErrHndlr  
   end  
  
   /****** InFrRmLoc or IrToRmLoc Should Have LocTyp= 'F' ********/  
   /* Current Partition */  
   /*** Jay 3.3(FG) ***/  
   Select @Row= Count('x') From Inserted Ins where OmPrtKey=@wCurrPrtn   
    and Not Exists (Select 'x' From Loc where LocCoCd = OmCoCd   
     and LocTyp= 'F' and (LocCd= OmFrDmLoc or LocCd = OmToDmLoc))  
       If @Row>0  
   begin  
    Select @ErrMsg= 'Atleast One DM Loc Must Be Of Type ''F'' '  
      GoTo ErrHndlr  
   end  
  
   /****** RM Wt/ Qty Can Be Issued From Locations Of Type 'F' Only in fot********/  
   /* Current Partition */  
   /*** Jay 3.3(FG) ***/  
   Select @Row= Count('x') From Inserted Ins where OmPrtKey=@wCurrPrtn and  
    OmTc= 'FOT' and Not Exists (Select 'x' From Loc where LocCoCd = OmCoCd and   
     LocTyp= 'F' and ((LocCd= OmFrDmLoc and OmFrDmDc= 'C') or   
        (LocCd= OmToDmLoc and OmToDmDc= 'C')                ))  
       If @Row> 0  
   begin  
    Select @ErrMsg= 'Qty Can Be Issued From Locations Of Type ''F'' Only'  
      GoTo ErrHndlr  
   end  
   /****** RM Wt/ Qty Can Be Issued From Locations Of Type 'XS' Only in FIN ********/  
   /* Current Partition */  
   /*** Jay 3.3(FG) ***/  
   Select @Row= Count('x') From Inserted Ins where OmPrtKey=@wCurrPrtn and  
    OmTc= 'FIN' and Not Exists (Select 'x' From Loc where LocCoCd = OmCoCd and   
     LocTyp= 'XS' and ((LocCd= OmFrDmLoc and OmFrDmDc= 'C') or   
        (LocCd= OmToDmLoc and OmToDmDc= 'C')                ))  
       If @Row> 0  
   begin  
    Select @ErrMsg= 'Qty Can Be Issued From Locations Of Type ''XS'' Only'  
      GoTo ErrHndlr  
   end    
  End     
  /*** Jay 3.3(FG) ***/  
  
  /* Manali Trading Module */  
  If exists (Select 'x' from Inserted   
   where exists (Select 'x' from Param where PTyp= 'TC' and PValue= 'JT' and PMCd= OmTc) )  
  Begin  
   /* Current Partition */   
   Select @Row= Count('x') From Inserted Ins Where OmPrtKEy=@wCurrPrtn and (OmFrDmLoc= '' or OmToDmLoc= '')  
    and exists(Select 'x' from TcMst Where TmCoCd=OmCoCd and TmTc=OmTc and TmLocTypFr<>'' and TmLocTypTo<>'')  
     If @Row> 0  
   begin  
    Select @ErrMsg= 'From/To Dm Loc Should Not Be Blank'  
      GoTo ErrHndlr  
   end  
  
   select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and    
    not exists(Select 'x' from TcMst Where TmCoCd=OmCoCd and TmTc=OmTc   
       and TmFrDmDc=OmFrDmDc and TmToDmDc=OmToDmDc)   
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid OmFrDmDc or OmToDmDc'  
    goto ErrHndlr    
   end     
  
   /* Current Partition */  
   select @row= count('x') from inserted Ins where OmPRtKey=@wCurrPrtn and   
     Ins.OmFrDmLoc = Ins.OmToDmLoc and (Ins.OmFrDmLoc <> '' or  
     Ins.OmToDmLoc <> '')  
     if @row>0  
     begin  
       select @errmsg= 'To Loc and From Loc cannot be same'  
       goto ErrHndlr  
     end  
  
   /*** Jay 3.3(FG) - Current Partition ***/  
   select @row= count('x') from inserted Join TcMst On TmCoCd=OmCoCd and TmTc=OmTc and TmLocTypFr<>''  
    where OmPrtKey=@wCurrPrtn and  
    not exists (select 'x' from Loc where LocCoCd= OmCoCd and LocTyp =TmLocTypFr  
       and LocCd=OmFrDmLoc and LocPrntYn= 'N'  And LocValidYN='Y')   
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid From Design Location Code/ Not Defined'    
    goto ErrHndlr    
   end     
  
  
   select @row= count('x') from inserted Join TcMst On TmCoCd=OmCoCd and TmTc=OmTc and TmLocTypTo<>''  
    where OmPrtKey=@wCurrPrtn and  
    not exists (select 'x' from Loc where LocCoCd= OmCoCd and LocTyp =TmLocTypTo  
       and LocCd=OmToDmLoc and LocPrntYn= 'N'  And LocValidYN='Y')   
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid To Design Location Code/ Not Defined'    
    goto ErrHndlr    
   end  
  
   If exists (Select 'x' from Inserted Where OmTc in ('JCN','LCN' ))  
   Begin   
    Select @Row= Count('x') From Inserted Ins Where OmPrtKEy=@wCurrPrtn and  
     (OmFrRmLoc= '' or OmFrRmDc= '' or OmToRmLoc= '' or OmToRmDc= '')  
      If @Row> 0  
    begin  
     Select @ErrMsg= 'From/To Rm Loc, From/To Rm DC Should Not Be Blank'  
       GoTo ErrHndlr  
    end  
  
    select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and    
     not (select count('x') from Param where PTyp='DC' and (PMCd=OmFrRmDc or PMCd=OmToRmDc) and PSCd='') =2    
    if @row> 0    
    Begin    
     select @errmsg= 'Invalid OmFrRmDc or OmToRmDc'  
     goto ErrHndlr    
    end     
  
    select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and not(OmFrRmDc='C' and OmToRmDc='D')   
    if @row> 0    
    Begin    
     select @errmsg= 'Invalid OmFrRmDc or OmToRmDc'  
     goto ErrHndlr    
    end     
  
  
    select @row= count('x') from inserted Ins where OmPRtKey=@wCurrPrtn and   
      Ins.OmFrRmLoc = Ins.OmToRmLoc and (Ins.OmFrRmLoc <> '' or Ins.OmToRmLoc <> '')  
      if @row>0  
      begin  
        select @errmsg= 'To Rm Loc and From Rm Loc cannot be same'  
        goto ErrHndlr  
      end  
  
    select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and OmFrRmLoc<>'FG'  
    if @row> 0    
    Begin    
     select @errmsg= 'From Rm Location Should Be ''FG'''    
     goto ErrHndlr    
    end     
  
  
    select @row= count('x') from Inserted where OmPrtKey=@wCurrPrtn and OmToRmLoc<>'XD'  
    if @row> 0    
    Begin    
     select @errmsg= 'To Rm Location Should Be ''XD'''    
     goto ErrHndlr    
    end     
   End     
     
   If Not exists (Select 'x' from Inserted Where OmTc in ('JCN','LCN') )  
   Begin   
    Select @Row= Count('x') From Inserted Ins Where OmPrtKEy=@wCurrPrtn and  
     Not(OmFrRmLoc= '' And OmFrRmDc= '' And OmToRmLoc= '' And OmToRmDc= '')  
      If @Row> 0  
    begin  
     Select @ErrMsg= 'From/To Rm Loc, From/To Rm DC Should Be Blank'  
       GoTo ErrHndlr  
    end  
   End  
  End     
  /* Manali Trading Module */    
  
 /*** Geeta ***/  
 End  
 if @mode = 'D'   
 Begin  
  /****** Cannot Delete If Record Exists In OrdDsg Table ******/  
  /* Sessionproperty commented by Geeta in ver 2.14.0 */  
  /* Current Partition only */  
  select @row= count('x') from deleted, OrdDsg where OmPrtKey=@wCurrPrtn and OmIdNo=OdOmIdNo and OmCoCd= OdCoCd  
   and OmTc= OdTc and OmYy= OdYy and OmChr= OdChr and OmNo= OdNo and OmPrtKey=OdPrtKey /* and  
   (Not (OmAckYN='Y' and OmCoCd='WEB' and @wSysDb='WEB' and SessionProperty('replication_agent')= 1)  )  */  
  if @row> 0   
  begin  
   select @errmsg= 'Cannot Delete Order As Order Design Records Exist'  
   goto ErrHndlr  
  end  
  
  /*** (Jen 2.13) ***/  
  /****** Whenever the OrdMst record where OmReNo> 0 is deleted, delete records from the OrdDsg table ******/  
  /* Delete OrdDsg From deleted, OrdDsg where OmReNo> 0 and OmCoCd = OdCoCd   
   and OmTc = OdTc and OmYy = OdYy and OmChr = OdChr and OmNo = OdNo    
  */  
  /*** (Jen 2.13) ***/  
  
  /****** Whenever the OrdMst record is deleted, delete records from the OrdTgt table ******/  
  Delete OrdTgt From deleted, OrdTgt where OmCoCd = OtCoCd   
   and OmTc = OtTc and OmYy = OtYy and OmChr = OtChr and OmNo = OtNo    
  
  /****** Whenever the OrdMst record is deleted, delete records from the OrdScop table ******/  
  Delete OrdScop From deleted, OrdScop where OsCoCd= OmCoCd   
   and OsTc= OmTc and OsYy= OmYy and OsChr= OmChr and OsNo= OmNo   
  
  /****** Manali Trading Module ******/  
  Delete InvHd From Deleted, InvHd Where   
   Exists(Select 'x' from Param Where PTyp='TC' and PMCd=OmTc and PValue='JT')   
   and InCoCd=OmCoCd and InTc=OmTc and InYY=OmYY and InChr=OmChr and InNo=OmNo  
  
  /*******Geeta****Crm***2.12****15/12/06***************************************************/  
  /*****************If OmSubmitted =’Y’ then cannot Delete  ******/  
  /* Current Partition */  
  select @row= count('x') from deleted where OmPrtKey=@wCurrPrtn and (OmSubmitYN in ('Y','') and OmCrmNo<>0)  
    and not (OmCoCd='WEB' and OmAckYN ='Y')  
  if @row> 0  
  begin  
   select @errmsg= 'Cannot Delete a Submitted Order'  
   goto ErrHndlr  
  end  
  
 End  
  
return  
ErrHndlr:  
 begin  
  select @errmsg='|'+@errmsg  
  raiserror(@errmsg,16,1)  
  rollback transaction   
 end  
end  

GOGO

UPDATE TcStr
SET tslbl='Rework Code'
WHERE TsTbl='param' and TsTyp = 'RWRK' and TsIdName='PSCD'
UPDATE TcStr
SET tslbl='Process Loc'
WHERE TsTbl='param' and TsTyp = 'RWRK' and TsIdName='PMCD'

GOGO

insert into TrgDisa values ('param')

insert into Param (Ptyp,PMCd,PSCd,PDesc,PDesc225,PValue,PNum,PValue1,PNum1,PValue2,PValue3,PValidYn,ModUsr,ModDt,ModTime,PPrtKey)
select PTyp,'CDW',PSCd,'Diamond Certification Charges',PDesc225,PValue,PNum,PValue1,PNum1,PValue2,PValue3,PValidYn,ModUsr,ModDt,ModTime,PPrtKey from Param where 
PTyp='LABMCD' and PMCd='DHC'

delete from trgdisa

GOGO

ALTER TRIGGER [dbo].[Param_INUPDL] ON [dbo].[Param] 
       FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
	/****** Trigger Version - 3.11.1 ******/
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @PTyp varchar(8)
	DECLARE @wHCd VARCHAR(8)
	DECLARE @SYS VARCHAR(5)
 	DECLARE @ReplAgt BIT  

	IF @@ROWCOUNT= 0
		RETURN
	If Exists (Select 'x' From TrgDisa Where TdTblNm = 'Param')
		RETURN

	Set @wHCd = 'ZSELF'	
	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	/****** Determining whether the trigger has been called in an insert, update or delete mode ******/
	/****** If there no records in inserted the the mode is 'Delete' 			    ******/
	/****** If there no records in deleted the the mode is 'Insert' 		            ******/
	/****** If there records in both inserted and deleted the the mode is 'Update' 		    ******/
	Select @mode=case (select count('x') from inserted) when 0 then 'D'
		Else Case (select count('x') from deleted) when 0 then 'A' else 'C' end
       	End 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/*** Storing PTyp In The Variable @PTyp ***/
	select @PTyp= case  when @mode in ('C', 'A') then (Select max(PTyp) from inserted)  else (Select max(PTyp) from deleted) end  

	If  (@ReplAgt<>1)
	Begin
	 
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   Exists ( Select 'x' From SysDb where SysId='EMR' and SdMst='N' )  Or  
		     Exists ( Select 'x' From SysDb where SysId='CRM' and SysDb='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
		
		if @mode in ('A','C')
		Begin
			If @PTyp= 'SUBPRC' 
			Begin 
				/****** PMCd = valid Process Loc ******/
				select @row= count('x') from inserted where not exists (select 'x' from Loc where LocTyp= 'P' and LocCd= PMCd)
				if @row>0 
				begin
					select @errmsg= 'Process Location Not Defined'
					goto ErrHndlr
				end
			End
			
			/*********Bhavna PMCD = Valid proc loc for rework ******/
			If @PTyp= 'RWRK' 
			Begin 
				/****** PMCd = valid Process Loc ******/
				select @row= count('x') from inserted where not exists (select 'x' from Loc where LocTyp= 'P' and LocCd= PMCd)
				if @row>0 
				begin
					select @errmsg= 'Process Location Not Defined'
					goto ErrHndlr
				end
			End
			/*********Bhavna PMCD = Valid proc loc for rework ******/
		End
	End  

	Set DateFormat DMY 

	/***Geeta****From CRM 2.12 Onwards 
	NOTE::	***PTYP  Should be Unique in Param,vParam & cParam*****************/ 

 	/******** Records Of Only One PTyp Can Be Inserted At A Time ********/ 
	select @Row= Count(distinct(PTyp)) from inserted 
	If @Row > 1
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One PTyp Can Be Deleted At A Time ********/ 
	select @Row= Count(distinct(PTyp)) from deleted 
	If @Row > 1 
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** If The Parameter Is A System Parameter Then No Add, Change Or Delete Allowed For The Param Entry *********/
	/* (Bef 3.01)
	select @Row=Count('x') from Param Pm where (@PTyp= 'PTYP') or 
		(Pm.PTyp= 'PTYP' and Pm.PMCd= @PTyp and Pm.PValue= 'M')
	(Bef 3.01) */

	/*** (Jen 3.01) ***/

	select @Row= Count('x') from Param Pm where (@PTyp= 'PTYP') or 
		(Pm.PTyp= 'PTYP' and Pm.PMCd= @PTyp and Pm.PValue= 'M' and @PTyp<> 'VER')
	/*** (Jen 3.01) ***/
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Add/Change/Delete Microway Parameter - '+ @PTyp
		GoTo ErrHndlr
	end		

	/*** (Jen 3.01) ***/
	select @Row= Count('x') from Param Pm where @mode in ('A','D') and 
		Pm.PTyp= 'PTYP' and Pm.PMCd= @PTyp and Pm.PValue= 'M' and @PTyp= 'VER' 
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Add/Delete Microway Parameter - '+ @PTyp
		GoTo ErrHndlr
	end		
	/*** (Jen 3.01) ***/
	
	select @Row= Count('x') from Inserted where @mode ='A' and PTyp= 'LOCKDT' 
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Add  LOCKDT Parameter '
		GoTo ErrHndlr
	end	

	select @Row= Count('x') from Deleted where @mode ='D' and PTyp= 'LOCKDT' 
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Delete  LOCKDT Parameter '
		GoTo ErrHndlr
	end		

	select @Row= Count('x') from Inserted where @mode ='A' and PTyp= 'DMMATX' 
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Add Records to Design Matrix Parameter '
		GoTo ErrHndlr
	end	
			
		
 	/******** Key Cannot Be Changed  (i.e. PTyp, PMCd and PSCd cannot be changed) ********/ 
 	if @mode = 'C'
 	Begin
  		select @Row= Count('x') from deleted del where
    		not exists (Select 'x' from inserted ins where ins.PTyp= del.PTyp and ins.PMCd= del.PmCd and ins.PSCd= del.PSCd)
  		If @Row > 0
	  	begin 
			Select @ErrMsg='Cannot Change Param Key'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	BEGIN
		/*** Only a valid PTyp can be entered (i.e. a valid PMCd from Param where PTyp= 'PTYP') ***/
		select @row=count('x') from inserted ins where ins.PTyp<> 'PTYP' and 
		not exists (select 'x' from Param Prm where Prm.PTyp='PTYP' and Prm.PMCd= ins.PTyp)
		if @row>0 
		begin
			select @errmsg='Parameter Type Not Defined'
			goto ErrHndlr
		end
		/*** PMCd cannot be Blank ***/
		select @row= count('x') from inserted where PMCd= ''
		if @row>0 
		begin
	   		select @errmsg='Main Code Cannot Be Blank'
   			goto ErrHndlr
  		end

		/***  PDesc cannot be blank ***/
		/* *** Jay 3.2.0 [Stmp Instr] */
		/**** Manali 3.8.1 - SETCD started ****/
		select @row= count('x') from inserted where PDesc= '' and @PTyp not in ('INVDESC', 'STMPINST', 'SETCD','DMMATX')
		if @row>0 
		begin
			select @errmsg= 'Description Cannot Be Blank'
			goto ErrHndlr
  		end

		if @PTyp= 'CPYRT' 
		Begin 
			/****** PSCd= Blank ******/
			select @row=count('x') from inserted where PSCd<> ''
			if @row> 0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** PValue= Blank ******/
			select @row=count('x') from inserted where PValue<> '' 
			if @row> 0 
			begin
				select @errmsg= 'PValue Should Be Blank'
				goto ErrHndlr
			end
			/****** PNum= 0 ******/
			select @row=count('x') from inserted where PNum<> 0
			if @row> 0 
			begin
				select @errmsg= 'PNum Should Be Zero'
				goto ErrHndlr
			end

/*** ###
			select @row=count('x') from inserted where PDesc225<> '' and 
			if @row>0 
			begin
				select @errmsg= 'Raw Material Category In Sequence Not Defined'
				goto ErrHndlr
			end
***/
			select @row= count('x') from inserted where PDesc225= '' 
			if @row> 0 
			begin
				select @errmsg= 'Raw Material Category Sequence Should Be Entered'
				goto ErrHndlr
			end

			/****** PValue1= Blank ******/		
			select @row= count('x') from inserted where PValue1<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** PNum1= 0 ******/
			select @row= count('x') from inserted where PNum1<> 0
			if @row> 0 
			begin
				select @errmsg= 'PNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** PValue2= Blank ******/
			select @row= count('x') from inserted where PValue2<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** PValue3 = Blank ******/
			select @row= count('x') from inserted where PValue3<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue3 Should Be Blank'
				goto ErrHndlr
			end

/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where PValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'PValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */

			/* Bef 3.03 - Following check no more reqd for PmCd= 'GPSDCXAM' */
			/****** Cannot add or change the Record of PmCd= 'GPSDCXAM' ******/
			/*
			select @row= count('x') from inserted where PMCd= 'GPSDCXAM'
			if @row> 0 
			begin
				select @errmsg= 'Cannot Add Or Change The Record ''GPSDCXAM'' '
				goto ErrHndlr
			end
			*/

			/* Manali 3.03 - 12/07/08 */
			/****** Cannot add or change the Record of PmCd= 'GPSLDCXM' ******/
			select @row= count('x') from inserted where PMCd= 'GPSLDCXM'
			if @row> 0 
			begin
				select @errmsg= 'Cannot Add Or Change The Record ''GPSLDCXM'' '
				goto ErrHndlr
			end
			/* Manali 3.03 - 12/07/08 */
		End

		if @PTyp= 'CURNCY' 
		Begin 
			/****** PMCd= Not Blank ******/
			select @row= count('x') from inserted where PMCd= ''
			if @row> 0 
			begin
				select @errmsg= 'Main Code Cannot Be Blank'
				goto ErrHndlr
			end
			/****** PSCd= Blank ******/
			select @row= count('x') from inserted where PSCd<> ''
			if @row> 0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/* Zubin 213 (Bef 213) */ 
			/****** PValue= Blank ******/
/*			select @row= count('x') from inserted where PValue<> '' 
			if @row> 0 
			begin
				select @errmsg= 'PValue Should Be Blank'
				goto ErrHndlr
			end
*/ 
			/* Zubin 213 */ 
			select @row= count('x') from inserted where PValue= '' 
			if @row> 0 
			begin
				select @errmsg= 'Currency Unit Description Cannot Be Blank'
				goto ErrHndlr
			end

			/****** Round(PNum, 3)> 0 ******/
			select @row= count('x') from inserted where Round(PNum, 3)<= 0
			if @row> 0 
			begin
				select @errmsg= 'Currency Conversion Rate Should Be > Zero'
				goto ErrHndlr
			end
/* COMMENTED TEMPORARILY (WILL BE INCORPORATED LATER) */ 
			/* Zubin 213 */ 
/*			select @row= count('x') from inserted where PNum<> 0
			if @row> 0 
			begin
				select @errmsg= 'PNum Should Be Zero'
				goto ErrHndlr
			end
*/
			/****** PDesc225= Blank ******/
			select @row= count('x') from inserted where PDesc225<> '' 
			if @row> 0 
			begin
				select @errmsg= 'PDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/* Zubin 213 (Bef 213) */ 
			/****** PValue1= Blank ******/		
/*			select @row=count('x') from inserted where PValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'PValue1 Should Be Blank'
				goto ErrHndlr
			end
*/
			/* Zubin 213 */ 
			select @row=count('x') from inserted where PValue1= ''
			if @row>0 
			begin
				select @errmsg= 'Decimal Unit Description'
				goto ErrHndlr
			end
			/****** PNum1= 0 ******/
			select @row= count('x') from inserted where PNum1<> 0
			if @row> 0 
			begin
				select @errmsg= 'PNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** PValue2 = Blank ******/
			/**** Manali 3.9.0 - SB File Cur Cd Mapped In this field ***/
			/*
			select @row= count('x') from inserted where PValue2<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue2 Should Be Blank'
				goto ErrHndlr
			end
			*/
			/****** PValue3 = Blank ******/
			select @row= count('x') from inserted where PValue3<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue3 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */

			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where PValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'PValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
		End 

		if @PTyp= 'DAANACD' 
		Begin 
			/****** PMCd= Valid Dsg Ana Fld where PValue= 'Y' ******/ 
			select @row= count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'DAANAFLD' and Prm.PMCd= ins.PMCd and Prm.PValue= 'Y') 
			if @row> 0 
			begin
				select @errmsg= 'Design Analysis Field Not Defined'
				goto ErrHndlr
			end
			/****** PSCd<> Blank ******/ 
			select @row= count('x') from inserted where PSCd= ''
			if @row> 0 
			begin
				select @errmsg= 'Design Analysis Code Cannot Be Blank'
				goto ErrHndlr
			end
			/****** PValue= Blank ******/
			select @row= count('x') from inserted where PValue<> '' 
			if @row> 0 
			begin
				select @errmsg= 'PValue Should Be Blank'
				goto ErrHndlr
			end
			/****** PNum = 0 ******/
			select @row=count('x') from inserted where Str(PNum, 16, 0)<> Str(0, 16, 0)
			if @row>0 
			begin
				select @errmsg= 'PNum Should Be Zero'
				goto ErrHndlr
			end
			/****** PDesc225 = Blank ******/
			select @row= count('x') from inserted where PDesc225<> ''
			if @row> 0 
			begin
				select @errmsg= 'PDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/****** PValue1= Blank ******/
			select @row= count('x') from inserted where PValue1<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** PNum1 = 0 ******/
			select @row= count('x') from inserted where PNum1<> 0
			if @row> 0 
			begin
				select @errmsg= 'PNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** PValue2= Blank ******/
			select @row= count('x') from inserted where PValue2<> ''
			if @row> 0 
			begin
				select @errmsg= 'PValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** PValue3 = Blank ******/
			select @row= count('x') from inserted where PValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'PValue3 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where PValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'PValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */

		End

		if @PTyp= 'RMSCTG'		/*	--|| 4.1.4 ||-- */
		Begin 
			if @mode in ('C') 
			begin
				Select @row= count('x') from inserted ins where 
					Exists (Select 'x' from deleted del where del.PMCd= ins.PMCd and del.PSCd= ins.PSCd and del.PValue<>ins.PValue and del.PValue='BS') 
					And Exists (Select 'x' from RmRt RrT
							    Where RrT.RrCtg=ins.PMCd And RrT.RrSCtg=ins.PSCd And RrT.RrTcTyp In ('ILC','NAS','RM','RSZ','STW') 									
									And not exists (Select * from RmRt Rr where Rr.RrTcTyp= 'BS' and
				   									Rr.RrCmCtg=RrT.RrCmCtg and Rr.RrCmCd= RrT.RrCmCd and 
													Rr.RrCmCurCd='' and Rr.RrCtg= RrT.RrCtg and
   													Rr.RrSCtg= RrT.RrSCtg and Rr.RrSTWGrp= '' and 
													Rr.RrCd= '' and Rr.RrDmCtg= '' and Rr.RrDmCd=RrT.RrDmCd and 
													Rr.RrLsCtg= '' and Rr.RrLabMCd= '')
									And (Select count('x') from RmRt Rt 
											Where Rt.RrTcTyp= RrT.RrTcTyp and Rt.RrCmCtg= RrT.RrCmCtg and Rt.RrCmCd= RrT.RrCmCd and 
												  Rt.RrCmCurCd= RrT.RrCmCurCd and Rt.RrCtg= RrT.RrCtg and Rt.RrSCtg= RrT.RrSCtg and 
												  Rt.RrSTWGrp= RrT.RrSTWGrp and Rt.RrCd= RrT.RrCd and Rt.RrDmCtg= RrT.RrDmCtg and 
												  Rt.RrDmCd=RrT.RrDmCd and Rt.RrLsCtg= RrT.RrLsCtg and Rt.RrLabMCd= RrT.RrLabMCd
													and ((Rt.RrFrLn<= RrT.RrFrLn and Rt.RrToLn>= RrT.RrFrLn)
													or 	(Rt.RrFrLn<= RrT.RrToLn and Rt.RrToLn>= RrT.RrToLn)
													or  (RrT.RrFrLn<= Rt.RrFrLn and RrT.RrToLn>= Rt.RrToLn))) > 1) 
				if @row> 0 
				begin 
					select @errmsg= 'Cannot Chg ''Rate By'' as Duplicate Range Size Exists in one of the RmRt Types ''ILC'',''NAS'',''RM'',''RSZ'' or ''STW'' ' 
					goto ErrHndlr
				end 
			end			
		End

		if @PTyp= 'DAANAFLD' 
		Begin 
			if @mode in ('C') 
			begin
				/****** Cannot Change PValue when DsgAna Rec Exists *****/
				select @row= count('x') from inserted ins where 
					not exists(Select 'x' from deleted del where del.PMCd= ins.PMCd 
						and del.PSCd= ins.PSCd and del.PValue= ins.PValue) 
					and exists(Select DaAnaSr from DsgAna where DaAnaSr= ins.PMCd) 
				if @row> 0 
				begin 
					select @errmsg= 'Cannot Change Defn Of Ana Field When Rec Exists In DsgAna' 
					goto ErrHndlr
				end 
			end			

			/****** PSCd= Blank ******/
			select @row=count('x') from inserted where PSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** PValue= valid PMCd('YN') ******/
			select @row=count('x') from inserted ins where 
			not exists (select 'x' from Param Prm where Prm.PTyp= 'YN' and Prm.PMCd= ins.PValue)
			if @row> 0 
			begin
				select @errmsg= 'Specify Whether This Is An Ana Cd Fld Or Not (''Y'' For Cd/ ''N'' For Desc)'
				goto ErrHndlr
			end
			/****** PNum = 0 ******/
			select @row= count('x') from inserted where Str(PNum, 16, 0)<> Str(0, 16, 0)
			if @row> 0 
			begin
				select @errmsg= 'PNum Should Be Zero'
				goto ErrHndlr
			end
			/****** PDesc225 <> Blank ******/
			select @row= count('x') from inserted where PDesc225= ''
			if @row> 0 
			begin
				select @errmsg= 'Short Description Cannot Be Blank'
				goto ErrHndlr
			end
			/****** PValue1= valid PMCd('YN') ******/
			select @row= count('x') from inserted ins where 
			not exists (select 'x' from Param Prm where Prm.PTyp= 'YN' and Prm.PMCd= ins.PValue1) 
			if @row> 0 
			begin
				select @errmsg= 'Specify Whether This Field Is Compulsory Or Not'
				goto ErrHndlr
			end
			/****** If PValue= 'Y' then PValue1= 'Y' ******/
			select @row= count('x') from inserted ins where PValue= 'Y' and PValue1<> 'Y' 
			if @row> 0 
			begin
				select @errmsg= 'Design Analysis Codes Have To Be Compulsory'
				goto ErrHndlr
			end
			/****** PNum1 = 0 ******/
			select @row=count('x') from inserted where PNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'PNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** PValue2= Blank ******/
			select @row= count('x') from inserted where PValue2<> ''
			if @row> 0 
			begin
				select @errmsg='PValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** PValue3 = Blank ******/
			select @row= count('x') from inserted where PValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'PValue3 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where PValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'PValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
		End

		/* Jenny Color (02/04/05) */
		if @PTyp= 'DEFCLR' 
		Begin 
			/****** Only One Record Of 'DEFCLR' Is Allowed
				 is allowed ******/
			select @row= count('x') from Param where PTyp= 'DEFCLR' 
			if @row> 1
			begin
				select @errmsg= 'Only One Record Allowed For This Param Type'
				goto ErrHndlr
			end
			/****** PMCd= 'DEFCLR' ******/
			select @row= count('x') from inserted where PMCd<> 'DEFCLR'
