select Hcocd,PTyp,PMCd,PSCd,PDesc,PDesc225,PValue,PNum,PValue1,PNum1,PValue2,PValue3,PValidYn,Pa.ModUsr,Pa.ModDt,PA.ModTime,PPrtKey,'' from head ,Param Pa where 
PTyp='LOCKDT' and HCd='ZSELF'

