Alter TRIGGER [dbo].[Txnd_INUPDL] ON [dbo].[Txnd]              
       FOR INSERT,UPDATE,DELETE              NOT FOR REPLICATION
AS              
BEGIN              
 /* Trigger Version 3.10.0 */              
 Declare @Row Int              
 Declare @Mode Char(1)              
 Declare @ErrMsg Varchar(255)              
 Declare @wTcTyp Char(3)               
 Declare @wTc Char(3)               
 Declare @wEntTyp Char(8)              
 Declare @wHCd Varchar(8)              
 DECLARE @ReplAgt BIT                
 DECLARE @wCurrPrtn VarChar(1)              
      
 If @@RowCount=0              
  Return              
 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Txnd' )              
  RETURN              
              
 Select @Mode=Case (Select Count('x') From Inserted)              
    When 0 Then 'D'              
   Else Case (Select Count('x') From Deleted)              
    When 0 Then 'A'              
    Else 'C'              
        End              
   End              
              
 Select @wHCd= 'ZSELF'              
 Select @wCurrPrtn='C'              
      
              
 /* **** Checking Whether a Normal Transaction or Replicated One **** */              
 Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))              
               
 /******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */              
 if @mode='C'              
 begin              
  Select @row=count('x') From Inserted Where TdPrtKey<>@wCurrPrtn              
  if @row> 0               
  begin              
   select @errmsg= 'Cannot Edit Records of Previous Partition'              
   goto ErrHndlr              
  end              
              
  Select @row=count('x') From Deleted del              
      Where Exists(Select 'x' From Inserted ins               
         Where ins.TdIdNo=del.TdIdNo and ins.TdCoCd=del.TdCoCd and ins.TdTc=del.TdTc and              
            ins.TdYy=del.TdYy and ins.TdChr=del.TdChr and ins.TdNo=del.TdNo and               
            ins.TdSr=del.TdSr and ins.TdSrNo=del.TdSrNo and ins.TdPrtKey<>del.TdPrtKey)               
  if @row> 0               
  begin              
   select @errmsg= 'Cannot Edit Partition Key Field'              
   goto ErrHndlr              
  end              
              
 End              
              
 if @mode='A'              
 Begin              
  Select @row=count('x') From Inserted Where TdPrtKey <> @wCurrPrtn               
  if @row> 0               
  begin              
   select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''              
   goto ErrHndlr              
  end              
 end               
              
 If @Mode='D'               
 Begin               
  select @row= count('x') from deleted del where del.TdPrtKey<>@wCurrPrtn              
  if @row> 0               
  begin              
   select @errmsg= 'Cannot Delete Records From Previous Partition'              
   goto ErrHndlr              
  end              
 End              
 /******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */              
      
              
 If  (@ReplAgt<>1)              
 Begin              
              
  /******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/              
  /***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/              
  if @mode in ('A','C')              
  Begin              
  /* Current Partition */              
  select @ROW =Count('x')  From inserted where TdPrtKey=@wCurrPrtn and              
  Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TdCoCd +',%'))              
   or (SysId='CRM' and SysDb='WEB'))              
  If @Row > 0              
   Begin              
    select @errmsg= 'Cannot Insert /Update '              
    goto ErrHndlr              
   end              
  End             
              
  If @mode in ('D')              
  Begin              
  /* Current Partition */              
  select @ROW =Count('x')  From Deleted where TdPRtKey=@wCurrPRtn and              
  Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TdCoCd +',%'))              
   or (SysId='CRM' and SysDb='WEB'))              
  If @Row > 0              
   Begin              
    select @errmsg= 'Cannot Delete '              
    goto ErrHndlr              
   end              
  End              
              
  If @Mode in ('A','C')              
  Begin              
              
   Select @wTcTyp= Max(PValue) From Inserted Join Param On PTyp='TC'              
     And PMcd= TdTc And PScd=''              
              
  /* Zubin 212 */              
   Select @wTc= TdTc From Inserted Join Param On PTyp='TC'              
     And PMcd= TdTc And PSCd=''              
  /* Zubin 212 */              
  End              
               
  /********** Select @wTcTyp from Deleted **********/              
  If @Mode in ('D')              
  Begin              
   Select @wTcTyp= Max(PValue) From Deleted Join Param On PTyp='TC'              
     And PMcd=TdTc And PScd=''              
  End              
               
  /********** Select @wTcEntTyp from Param ********/              
  select @wEntTyp = PValue1 from Param where PTyp='TCTYP'              
     and PMcd=@wTcTyp and PSCd=''              
                
  If @wEntTyp= 'TxnBag'              
  BEGIN               
   /****** Bag in Control of other User, Check either              
    PrevYy+Key Or TdYy+Key = LstYy+Key, for TdSrNo=0,<>0 ********/              
              
   /* Current Partition */              
   select @Row= Count('x') from inserted              
    join Bag on TdBIdNo=BIdNo and TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo               
      and TdPrtKey=BPrtKey              
    where TdPrtKey=@wCurrPrtn and Not ((TdCoCd= BCoCd and TdPrevYy= BLstYy and TdPrevKey= BLstKey)              
    Or (TdCoCd= BCoCd and TdYy= BLstYy and TdKey= BLstKey))              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Bag in Control of other user'              
    GoTo ErrHndlr              
   end              
               
   /****** Cannot Add Or Change As Bag Is In Finished Goods Location ********/              
   /* Current Partition */              
   select @Row= Count('x') from inserted              
    join Bag on TdBIdNo=BIdNo and TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo               
      and TdPrtKey=BPrtKey              
    where BPrtKey=@wCurrPrtn and BLoc= 'PFG'              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Cannot Add/ Change As Bag In Finished Goods Location'              
    GoTo ErrHndlr              
   end              
               
   /****** Cannot Change Or Delete As Bag Is In Finished Goods Location ********/              
   /* Current Partition */              
        select @Row= Count('x') from deleted              
    join Bag on TdBIdNo=BIdNo and TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo               
     and TdPRtKey=BPrtKEy              
    where BPrtKey=@wCurrPrtn and BLoc= 'PFG'              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Cannot Change/ Delete As Bag In Finished Goods Location'              
    GoTo ErrHndlr              
   end              
               
   /****** If TcType= 'BV' then TdFrBLoc & TdToBLoc cannot be 'PFG' ********/              
   /* Current Partition */              
   select @Row= Count('x') from inserted where @wTcTyp= 'BV' and TdPRtKey=@wCurrPrtn and              
    (TdFrBLoc= 'PFG' or TdToBLoc= 'PFG')              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'From/ To Bag Location Cannot Be ''PFG'' In Bag Movement'              
    GoTo ErrHndlr              
   end              
               
/**** Cannot Update or Delete if Not the last Txn of the Bag              
         Checking for TdSrNo=0, <>0 records *******/              
   /* Current Partition */              
   select @Row=Count('x') from deleted where TdPrtKey=@wCurrPrtn and              
    Not Exists (Select 'x' from Bag where TdBIdNo=BIdNo and TdCoCd= BCoCd and              
         TdByy= BYy and TdBChr= BChr and TdBNo= BNo and TdPrtKey=BPRtKey and              
         ((TdYy>= BLstYy and TdKey>= BLstKey)              
           or IsNull(BLstKey, 0)= 0))              
   If @Row > 0              
   Begin              
    Select @ErrMsg= 'Cannot Update Or Delete, Not The Last Txn Of The Bag'              
    GoTo ErrHndlr              
   end              
              
  If @Mode in ('A')              
  Begin              
   /* Sachin 3.2.2 - Bag Opn Dt should be Less than Min Transaction Date */              
   select @Row= Count('x') from inserted              
    join Bag on TdBIdNo=BIdNo and TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo               
      and TdPrtKey=BPrtKey              
    where TdPrtKey=@wCurrPrtn and TdDt<BOpnDt              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Transaction Date Cannot Be Less Than Bag Opening Date'              
    GoTo ErrHndlr              
   end              
              
   /**** Sachin 3.02.0 - Bag Transaction Should be at a later than that of the earlier Max Tran Date */              
   /* Current Partition */              
   Select @Row=Count('x') from Inserted               
       Join Bag on TdPrtKey=BPrtKey and TdBIdNo=BIdNo and TdCoCd= BCoCd and              
        TdByy= BYy and TdBChr= BChr and TdBNo= BNo              
   Where Tddt<BMaxTxnDt              
   If @Row > 0              
   Begin              
    Select @ErrMsg= 'A Transaction of Later Date Exists For this Bag'              
    GoTo ErrHndlr              
   end              
   /**** Sachin 3.02.0 - Bag Transaction Should be at a later than that of the earlier Max Tran Date */              
              
  End              
   End                
 End              
 /******* If Mode = 'C' then Cannot change Key Values,              
  Cannot Change VchNo, BagNo **********/              
 If @Mode = 'C'              
 Begin              
  /* Current Partition */                
  select @Row=Count('x') from Deleted Del where TdPrtKey=@wCurrPrtn and              
    Not Exists (Select 'x' from Inserted Ins where Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd=Del.TdCoCd              
     and Ins.TdTc=Del.TdTc and Ins.Tdyy=Del.TdYy and Ins.TdChr= Del.TdChr and Ins.TdNo=Del.TdNo              
     and Ins.TdSr=Del.TdSr and Ins.TdSrNo=Del.TdSrNo and Ins.TdPrtKey=Del.TdPrtKey              
     and Ins.TdByy=Del.TdByy and Ins.TdBChr=Del.TdBChr              
     and Ins.TdBNo=Del.TdBNo and Ins.TdKey= Del.TdKey)              
  If @Row > 0              
  Begin              
   Select @ErrMsg='Cannot Change Company Code/ Voucher No./Bag No/ Key'              
   GoTo ErrHndlr              
  End              
 End              
              
 /******** Records Of Only One TcTyp can be Inserted at a time.********/              
 /* Partition KEy Not required */               
 select @Row= Count(distinct(PValue)) from inserted Join param On              
    PTyp= 'TC' and PMCd= TdTc and PScd= ''              
 If @Row > 1              
 BEGIN              
  Select @ErrMsg= 'Transactions of only One TcType can be Acted On'              
  GoTo ErrHndlr              
 END              
              
 /******** Records Of Only One TcTyp can be Deleted at a time.*********/              
 /* Partition KEy Not required */              
 select @Row= Count(distinct(PValue)) from deleted Join param on              
    PTyp='TC' and PMcd=TdTc and PSCd=''              
 If @Row > 1              
 BEGIN              
  Select @ErrMsg='Transactions of only One TcType can be Acted on'              
  GoTo ErrHndlr              
 END              
            
 /********** Select @wTcEntTyp from Param ********/              
 /* Partition Key Not required */              
 select @wEntTyp = PValue1 from Param where PTyp='TCTYP'              
    and PMcd=@wTcTyp and PSCd=''              
 If @wEntTyp <> 'TxnBag' and @wEntTyp <> 'TxnRm'              
 Begin              
  Select @ErrMsg='Transactions of only ''Txn'' Type permitted'              
  GoTo ErrHndlr              
 end              
              
 /********* field level Validation Checks ********/              
 /****************   ****************/      
              
 /******* Valid TdCoCd,TdTc,TdYy,TdChr, TdNo ********/              
 /* Current Partition */               
 Select @Row= Count('x') From Inserted Ins Where Ins.TdPrtKey=@wCurrPrtn and              
  Not Exists (Select 'x' From Txn Where Txn.TIdNo=Ins.TdTIdNo and Txn.TCoCd=Ins.TdCoCd And Txn.TTc=Ins.TdTc              
   And Txn.TYy=Ins.TdYy And  Txn.TChr=Ins.TdChr And Txn.TNo=Ins.TdNo And Txn.TPrtKey=Ins.TdPrtKey)              
   If @Row> 0              
  begin              
  Select @ErrMsg= 'Voucher No. Does Not Exist'              
  GoTo ErrHndlr              
   end              
              
 /***** TdSr <> 0 *****/              
 /* Current Partition */               
 Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdSr=0              
 If @Row> 0              
 Begin              
    Select @ErrMsg= 'Sr. Cannot be 0'              
    GoTo ErrHndlr              
 End              
              
 /******* TdKey <> 0 ***********/              
 /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdKey<= 0              
 If @Row> 0              
 Begin              
  Select @ErrMsg= 'Key Cannot Be Zero'              
  GoTo ErrHndlr              
 End              
              
 /******* TdToRmDc should be Opp of  TdFrRmDc ( '' if TdFrRmDc= '' ) *******/              
 /* Current Partition */           
   Select @Row=Count('x') From Inserted Ins              
  Where Ins.TdPrtKey=@wCurrPrtn and (TdToRmDc=TdFrRmDc And TdFrRmDc<>'')  Or              
   (TdFrRmDc<>'' and TdToRmDc='')              
   If @Row>0              
 Begin              
  Select @ErrMsg='Invalid To Rm Dc'              
  GoTo ErrHndlr              
 End              
              
              
 /* *** Jay 2.13(CT) *** */               
 /* (Bef 27/11/06)              
 If @Mode in ('A', 'C') and @wTcTyp in ('BS', 'BM', 'REJ', 'MLT')              
 Begin              
    Select @Row= Count('x') From Inserted Ins where (TdPtQty<> 0 or TdRjPtQty<> 0 )and               
   not Exists (Select 'x' From Param where PTyp= 'BCHR' and PMCd= ins.TdBChr and               
        PSCd= '' and PValue= 'C')              
    If @Row> 0              
  Begin              
   Select @ErrMsg= 'Part Quantity Can Be Enter For Only Component Bags'              
   GoTo ErrHndlr              
  End              
 end              
 (Bef 27/11/06) */              
 /* *** Jay 2.13(CT) *** */               
              
 /* *** Jay 2.14Next *** [Avoid Discrepancy] */               
 If @Mode in ('A','C')               
  /* Current Partition */              
  Select @Row= count('x') from inserted where TdPrtKey=@wCurrPrtn and (TdFrRmLoc= 'FG' or TdToRmLoc= 'FG')              
  if @Row>0               
  Begin               
   Select @ErrMsg= 'Cannot Make Any Transaction For ''FG'' Location Type'              
   GoTo ErrHndlr              
  End              
              
 /* Manali Trading Module */      
  Select @Row= count('x') from inserted where TdPrtKey=@wCurrPrtn       
   and (TdFrRmLoc= 'XD' or TdToRmLoc= 'XD'       
      Or TdFrRmLocTyp In ('XD', 'MG', 'Y') or TdToRmLocTyp In ('XD', 'MG', 'Y'))      
  if @Row>0               
  Begin               
   Select @ErrMsg= 'Cannot Make Any Transaction For ''XD'',''MG'',''Y'' Location Type'              
   GoTo ErrHndlr              
  End              
 /* Manali Trading Module */      
      
 /***** Manali 3.8.0 - TdRtByQW *****/      
   select @Row= Count('x') from Inserted Ins where Ins.TdPrtKey=@wCurrPRtn and Ins.TdRtByQW <>'' and @wTc<>'PR'      
   If @Row> 0              
   begin              
    Select @ErrMsg= 'Rm Qw Option Should be Blank'              
    GoTo ErrHndlr              
   end              
       
      
/* *** Jay 2.14Next *** [Avoid Discrepancy] */               
              
 /************ Geeta 2.06 **********************************/              
 /*** There is a problem if Tolerance check is kept for Bag Split and Bag Merge       
 (eg: consider a bag with 2 pcs and RM has been issued into the bag for the 2 pcs for full tolerance.       
 Now in 'BS' or 'BM' issue 1 piece from the bag. There will now be a problem in Copy Rm for this bag) ***/              
 /*** (Bef 2.13) If @Mode in ('A','C') and @wTcTyp in ('DT','BS','BM') ***/              
/* If @Mode in ('A','C')             
 Begin              
  /*** Geeta 3.2.1 [10-06-2008] - Changed Tolerance for speed issues at Shrenuj and Other places ****/              
  /*** Only Maximum Tolerance has been checked - Based on RM Sub-Category [ONLY FOR DIAMONDS] ****/               
  If (Select Count('x') From Inserted TRm Where               
     (IsNull((Select HChkDCWtAtIssYN From Head Where TdCoCd= HCoCd and HCd= @wHCd), '') = 'Y')              
    And Not Exists (select 'x' from Param               
         Join UsrAccess on UaUsrCd = PMCd where PTyp= 'USR' and PMCd= TRm.ModUsr and UaMnuCd = TRm.TdTc               
           and UaSeoYn= 'Y' and PValue= (Select TSeoPwd from Txn               
             where TIdNo=TdTIdNo and TCocd= TdCoCd and TTc= TdTc and TYy= TdYy and TChr= TdChr and TNo= TdNo and TPRtKey=TdPRtKEy))               
              And Not Exists (Select 'x' from Param where PTyp= 'SEOPWD' and PMCD= 'SEOPWD' and               
                   PValue1=(Select TSeoPwd from Txn where TIdNo=TdTIdNo and TCocd= TdCoCd and TTc= TdTc and TYy= TdYy               
                 and TChr= TdChr and TNo= TdNo and TPrtKey=TdPrtKey)))=1              
                
   Begin             
 Declare  @qOrPrdWt Decimal(10,3), @RrMinTol decimal(10,3),@RrMaxTol Decimal(10,3)              
    Select Top 1 @qOrPrdWt=qOrPrdWt,              
      @RrMinTol=(Case when (OdIWtEqOrd='Y' or OdFixPrc='Y' Or (OdIWtEqOrd='N' and ','+PDesc225+',' Like '%,D,%'))              
         then RrFixMinTol Else RrOpnMinTol End),              
      @RrMaxTol=(Case when (OdIWtEqOrd='Y' or OdFixPrc='Y' Or (OdIWtEqOrd='N' and ','+PDesc225+',' Like '%,D,%'))              
         then RrFixMaxTol Else RrOpnMaxTol End)               
    From Inserted ins               
     Join Bag on BPrtKey=TdPrtKey and BIdNo=TdBIdNo and BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr  and BNo= TdBNo               
     Join OrdDsg On OdPrtKey=BPrtKey and OdIdNo=BOdIdNo and OdCoCd =BCoCd and OdTc=BOdTc and OdYy=BOdYy and               
        OdChr=BOdChr and OdNo=BOdNo and OdSr=BOdSr              
     Join (Select  OrCoCd,OrTc,OrYy,OrChr,OrNo,OrSr,OrRmCtg,OrRmSCtg,sum(OrPrdWt) qOrPrdWt  From OrdRm              
        where OrRmCtg='D'              
        Group By OrCoCd,OrTc,OrYy,OrChr,OrNo,OrSr,OrRmCtg,OrRmSCtg) OrRm            
      On OrCoCd=OdCoCd and OrTc=OdTc and OrYy=OdYy and OrChr=OdChr and OrNo=OdNo and               
        OrSr=OdSr and OrRmCtg=TdRmCtg and OrRmSCtg=TdRmSCtg              
     Join RmRt On RrTcTyp='WTT'  and RrCmCtg='C' and RrCtg=OrRmCtg and RrSCtg=OrRmSCtg               
         and round(qOrPrdWt,3) between round(RrFrLn,3) and round(RrToLn,3)              
         And RrCmCd In (OdOmCmCd,'ZSELF') And RrDmCd In (OdDmCd,'')              
     Left Outer Join Param On  PTyp='IWTFRORD' and PMCd=OdIWtFrOrd              
    where (select vPValue3 from vParam where vPTyp='CHR' and vPCoCd=OdCoCd and vPMCd=OdTc and vPSCd=OdChr)= 'N'              
    Order By (Case when RrCmCd=OdOmCmCd Then 1 Else 2 End),              
       (Case when RrDmCd=OdDmCd Then 1 Else 2 End)              
         
    Select @Row=count('x')              
    From Inserted ins              
     Join Bag On TdCoCd=BCoCd and TdBYy=BYy and TdBChr=BChr and TdBNo=BNo              
     Join (Select  TdCoCd as qTdCoCd,TdBYy as qTdBYy,TdBChr as qTdBChr,TdBNo as qTdBNo,              
       TdRmCtg as qTdRmCtg,TdRmSCtg as qTdRmSCtg,              
       sum(TdRmWt* (case when TdFrRmLoc= 'W' and TdFrRmDC= 'C' then -1               
              when TdFrRmLoc= 'W' and TdFrRmDC= 'D' then 1               
               when TdToRmLoc= 'W' and TdToRmDC= 'C' then -1               
            when  TdToRmLoc='W' and TdToRmDC= 'D' then 1 else 0 end))              
             qTdRmWt  From Txnd where TdRmCtg='D'              
       Group By TdCoCd,TdBYy,TdBChr,TdBNo,TdRmCtg,TdRmSCtg) TdRm              
      On TdCoCd=qTdCoCd and TdBYy=qTdBYy and TdBChr=qTdBChr and TdBNo=qTdBNo and TdRmCtg=qTdRmCtg and TdRmSCtg=qTdRmSCtg               
    where  TdSrNo<>0 and Cast(BQty as Decimal(8,2))>0 and TdRmCtg='D' and IsNull(@RrMaxTol,-1)>-1               
     and convert(decimal(10,3),(qTdRmWt/BQty))> convert(decimal(10,3),(@qOrPrdWt+@RrMaxTol)) and @wTcTyp in ('DT')              
    If @Row > 0              
   begin              
    Select @ErrMsg= 'Diamond Wt Exceeds the Tolerance Wt, Only Authorised Users Can Enter More Then Tolerance Values'              
    GoTo ErrHndlr              
   end              
            
    Select Top 1 @qOrPrdWt=qOrPrdWt,              
      @RrMinTol=(Case when OdMinDiaTolWt<>0 Then OdMinDiaTolWt Else            
      (qOrPrdWt-(Case when (OdIWtEqOrd='Y' or OdFixPrc='Y' Or (OdIWtEqOrd='N' and ','+PDesc225+',' Like '%,D,%'))              
         then RrFixMinTol Else RrOpnMinTol End)) End),              
      @RrMaxTol=(Case when OdMaxDiaTolWt<>0 Then OdMaxDiaTolWt Else             
       (qOrPrdWt+(Case when (OdIWtEqOrd='Y' or OdFixPrc='Y' Or (OdIWtEqOrd='N' and ','+PDesc225+',' Like '%,D,%'))              
        then RrFixMaxTol Else RrOpnMaxTol End))  End)             
    From Inserted ins               
     Join Bag on BPrtKey=TdPrtKey and BIdNo=TdBIdNo and BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr  and BNo= TdBNo               
     Join OrdDsg On OdPrtKey=BPrtKey and OdIdNo=BOdIdNo and OdCoCd =BCoCd and OdTc=BOdTc and OdYy=BOdYy and               
        OdChr=BOdChr and OdNo=BOdNo and OdSr=BOdSr              
     Join (Select  OrCoCd,OrTc,OrYy,OrChr,OrNo,OrSr,sum(OrPrdWt) qOrPrdWt  From OrdRm              
    where OrRmCtg='D'  Group By OrCoCd,OrTc,OrYy,OrChr,OrNo,OrSr) OrRm              
      On OrCoCd=OdCoCd and OrTc=OdTc and OrYy=OdYy and OrChr=OdChr and OrNo=OdNo and OrSr=OdSr             
     Left Outer Join RmRt On RrTcTyp='WTT'  and RrCmCtg='C' and RrCtg='D' and RrSCtg=''            
         and round(qOrPrdWt,3) between round(RrFrLn,3) and round(RrToLn,3)              
         And RrCmCd In (OdOmCmCd,'ZSELF') And RrDmCd In (OdDmCd,'')              
     Left Outer Join Param On  PTyp='IWTFRORD' and PMCd=OdIWtFrOrd              
    where (select vPValue3 from vParam where vPTyp='CHR' and vPCoCd=OdCoCd and vPMCd=OdTc and vPSCd=OdChr)= 'N'              
    Order By (Case when RrCmCd=OdOmCmCd Then 1 Else 2 End),              
       (Case when RrDmCd=OdDmCd Then 1 Else 2 End)              
              
    Select @Row=count('x')              
    From Inserted ins              
     Join Bag On TdCoCd=BCoCd and TdBYy=BYy and TdBChr=BChr and TdBNo=BNo              
     Join (Select  TdCoCd as qTdCoCd,TdBYy as qTdBYy,TdBChr as qTdBChr,TdBNo as qTdBNo,              
      sum(TdRmWt* (case when TdFrRmLoc= 'W' and TdFrRmDC= 'C' then -1               
              when TdFrRmLoc= 'W' and TdFrRmDC= 'D' then 1               
               when TdToRmLoc= 'W' and TdToRmDC= 'C' then -1               
            when  TdToRmLoc='W' and TdToRmDC= 'D' then 1 else 0 end))              
             qTdRmWt  From Txnd where TdRmCtg='D'              
       Group By TdCoCd,TdBYy,TdBChr,TdBNo) TdRm              
      On TdCoCd=qTdCoCd and TdBYy=qTdBYy and TdBChr=qTdBChr and TdBNo=qTdBNo             
    where  TdSrNo<>0 and Cast(BQty as Decimal(8,2))>0 and TdRmCtg='D' and IsNull(@RrMaxTol,-1)>-1               
     and convert(decimal(10,3),(qTdRmWt/BQty))> convert(decimal(10,3),@RrMaxTol)  and @wTcTyp in ('DT')              
    If @Row > 0              
   begin              
    Select @ErrMsg= 'Diamond Wt Exceeds the Tolerance Wt, Only Authorised Users Can Enter More Then Tolerance Values'              
    GoTo ErrHndlr              
   end             
             
 Select @Row=count('x')              
    From Inserted ins              
     Join Bag On TdCoCd=BCoCd and TdBYy=BYy and TdBChr=BChr and TdBNo=BNo              
     Left Outer Join (Select  TdCoCd as qTdCoCd,TdBYy as qTdBYy,TdBChr as qTdBChr,TdBNo as qTdBNo,              
       sum(TdRmWt* (case when TdFrRmLoc= 'W' and TdFrRmDC= 'C' then -1               
              when TdFrRmLoc= 'W' and TdFrRmDC= 'D' then 1          
               when TdToRmLoc= 'W' and TdToRmDC= 'C' then -1               
            when  TdToRmLoc='W' and TdToRmDC= 'D' then 1 else 0 end))              
             qTdRmWt  From Txnd where TdRmCtg='D'              
       Group By TdCoCd,TdBYy,TdBChr,TdBNo) TdRm              
      On TdCoCd=qTdCoCd and TdBYy=qTdBYy and TdBChr=qTdBChr and TdBNo=qTdBNo             
 Join Head On HCd='ZSELF' and HCoCd=TdCoCd            
    where  TdSrNo=0 and HMinDiaProcess<>'' and /*TdFrBLoc= HMinDiaProcess*/           
    ','+HMinDiaProcess+',' like '%,'+TdFrBLoc+',%'  and            
  Cast(BQty as Decimal(8,2))>0 and IsNull(@RrMinTol,-1)>-1               
  and convert(decimal(10,3),(IsNull(qTdRmWt,0)/BQty))< convert(decimal(10,3),@RrMinTol)  and @wTcTyp in ('BV')              
    If @Row > 0              
   begin              
    Select @ErrMsg= 'Diamond Wt is Less than the Min Tolerance Wt, Only Authorised Users Can Enter'              
    GoTo ErrHndlr              
   end              
            
  End               
 /******** Geeta 3.2.1 [10-06-2008] - Changed Tolerance for speed issues at Shrenuj and Other places *******/              
    End        */      
              
 /**************************Geeta 2.06 *****************************************/              
 If @Mode= 'A'              
 Begin              
  /********* Check whether record with same Key exists ********/              
  /* Complete Database */              
  select @Row= Count('x') from inserted ins where ins.TdPrtKey=@wCurrPrtn and ins.TdSrNo= 0              
   and exists(Select 'x' from Txnd Td1 where Td1.TdSrNo= 0              
    and Td1.TdCoCd= ins.TdCoCd and Td1.TdYy= ins.TdYy              
    and Td1.TdKey= ins.TdKey and              
    (Td1.TdCoCd<> ins.TdCoCd or Td1.TdTc<> ins.TdTc or              
     Td1.TdYy<> ins.TdYy or Td1.TdChr<> ins.TdChr or              
     Td1.TdNo<> ins.TdNo or Td1.TdSr<> ins.TdSr))              
    If @Row> 0              
  begin              
   Select @ErrMsg= 'Yy-Key Combination Already Exists For Another Voucher Sr.'              
   GoTo ErrHndlr              
  end              
              
  /*** Jenny ***/              
  If @wEntTyp= 'TxnBag'              
  Begin              
   /********* Child Recs Should Have The Same Yy-Key & YyKey combination as parent ********/              
   /* Current Partition */              
   select @Row= Count('x') from inserted ins where ins.TdPrtKey=@wCurrPrtn and ins.TdSrNo<> 0              
    and exists(Select 'x' from Txnd Td1 where Td1.TdSrNo= 0              
     and (Td1.TdPrtKey=ins.TdPrtKey and Td1.TdTIdNo=ins.TdTIdNo and Td1.TdCoCd= ins.TdCoCd and Td1.TdTc= ins.TdTc              
      and Td1.TdYy= ins.TdYy and Td1.TdChr= ins.TdChr              
      and Td1.TdNo= ins.TdNo and Td1.TdSr= ins.TdSr)              
     and (Td1.TdYy<> ins.TdYy or Td1.TdKey<> ins.TdKey              
      or Td1.TdYyKey<> ins.TdYyKey))              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Yy-Key Combination Of Child Should Be Same As Parent'              
    GoTo ErrHndlr              
   end              
              
   /********* Any new Rec of the bag should have the max Yy-Key Combination ********/              
   /* Complete Database */              
   select @Row= Count('x') from inserted ins where ins.TdPrtKey=@wCurrPrtn and ins.TdSrNo= 0              
    and exists(Select 'x' from Txnd Td1 where Td1.TdSrNo= 0              
     and Td1.TdBIdNo=ins.TdBIdNo and Td1.TdCoCd= ins.TdCoCd and Td1.TdBYy= ins.TdBYy              
     and Td1.TdBChr= ins.TdBChr  and Td1.TdBNo= ins.TdBNo              
     and (Td1.TdYy> ins.TdYy              
       Or              
      (Td1.TdYy= ins.TdYy and Td1.TdKey> ins.TdKey)))              
     If @Row> 0              
   Begin              
    Select @ErrMsg= 'A Later Txn Of The Bag Exists, Try Entering This Rec Again'              
    GoTo ErrHndlr              
   End              
  End              
  /*** Jenny ***/              
 End              
              
 /********* Cannot Delete SrNo=0 records if SrNo<>0 records exist or TxndPrd record exists ********/              
 If @Mode ='D'              
 Begin              
  /*** Jenny ***/              
  If @wEntTyp= 'TxnBag'              
  Begin              
   /* Current Partition */              
   Select @Row=Count('x') from Deleted Del where TdPrtKey=@wCurrPrtn and TdSrNo=0 and              
      Exists (Select 'x' from Txnd Td Where Td.TdPrtKey=Del.TdPrtKey and Td.TdTIdNo=Del.TdTIdNo               
    And Td.TdCoCd= Del.TdCoCd And Td.TdTc= Del.TdTc and Td.Tdyy= Del.Tdyy              
    And Td.TdChr= Del.TdChr and Td.TdNo= Del.TdNo              
    And Td.TdSr= Del.TdSr and Td.TdSrNo<> 0)              
   If @Row > 0              
   Begin              
    Select @ErrMsg='Cannot Delete SrNo=0 Record, As Childs Exist'              
    GoTo ErrHndlr              
   End              
              
   /* Current Partition */              
   Select @Row=Count('x') from Deleted Del where TdPrtKey=@wCurrPrtn and TdSrNo=0 and              
      Exists (Select 'x' from TxndPrd where TpPrtKey=TdPrtKey and TpTdIdNo=TdIdNo and TpCoCd= TdCoCd and TpTc= TdTc              
     and TpYy= TdYy and TpChr= TdChr and TpNo= TdNo and TpSr= TdSr)              
   If @Row > 0              
   Begin              
    Select @ErrMsg='Cannot Delete SrNo=0 Record, As Prd Points Record Exists'              
    GoTo ErrHndlr              
   End           
  End              
  /*** Jenny ***/              
 End              
              
 /* Zubin 212 */              
 If @wEntTyp in ('TxnRm', 'TxnBag')              
 Begin              
  /* Zubin 212 (Lot No. For 'D' and 'C' only) */              
  /* Current Partition */              
  /* *** Manali 3.03 - 30/06/08 - Lot No Open for Acc 'X' */                
  select @Row= Count('x') from inserted ins where TdPRtKey=@wCurrPrtn and TdLotNo <> '' and              
   Not Exists (select 'x' from RmMst where RmZ= 'N' and RmPrtKey=TdPrtKey and RmCd= TdRmCd and RmCtg IN ('D', 'C', 'X'))              
    If @Row> 0              
  begin              
   Select @ErrMsg= 'Lot No. Should Be Entered For Diamonds ,Color Stones And Accessories Only'              
   GoTo ErrHndlr              
  end              
              
  /* Lot No. Shld be blank when HLotNoYN= 'N' in head */              
  /* Current Partition */              
  /* *** Manali 3.03 - 03/07/08 - Lot No Open for Acc 'X' */                
  Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPRtn and TdLotNo<> '' and              
   Not Exists (Select 'x' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and HLotNoYN= 'Y')              
    If @Row> 0              
  begin              
   Select @ErrMsg= 'Lot No. Should Be Blank As ''Implement Lot No. For Dia/Cs/Acc'' Option Is ''N'' In Head Master (Tab 5)'              
     GoTo ErrHndlr              
  end              
 End              
 /* Zubin 212 */              
      
              
 /******* These Checks For @wEntTyp='TxnBag' has to be done ***********/              
 /******* before Bag Table can be updated      ***********/              
 If @wEntTyp= 'TxnBag'              
 Begin              
      
      
  /****** Bag in Control of other User, Check either              
   PrevYy+Key Or TdYy+Key = LstYy+Key, for TdSrNo=0,<>0 ********/              
/*  select @Row= Count('x') from inserted              
   join Bag on TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo              
   where Not ((TdCoCd= BCoCd and TdPrevYy= BLstYy and TdPrevKey= BLstKey)              
   Or (TdCoCd= BCoCd and TdYy= BLstYy and TdKey= BLstKey))              
  If @Row > 0              
  begin              
   Select @ErrMsg= 'Bag in Control of other user'              
   GoTo ErrHndlr              
  end              
*/              
  /****** Cannot Add Or Change As Bag Is In Finished Goods Location ********/              
/*  select @Row= Count('x') from inserted              
   join Bag on TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo              
   where BLoc= 'PFG'              
  If @Row > 0              
  begin              
   Select @ErrMsg= 'Cannot Add/ Change As Bag In Finished Goods Location'              
   GoTo ErrHndlr              
  end              
*/              
  /****** Cannot Change Or Delete As Bag Is In Finished Goods Location ********/              
/*       select @Row= Count('x') from deleted              
   join Bag on TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo              
   where BLoc= 'PFG'              
  If @Row > 0              
  begin              
   Select @ErrMsg= 'Cannot Change/ Delete As Bag In Finished Goods Location'              
   GoTo ErrHndlr              
  end              
*/              
  /****** If TcType= 'BV' then TdFrBLoc & TdToBLoc cannot be 'PFG' ********/              
/*  select @Row= Count('x') from inserted where @wTcTyp= 'BV' and              
   (TdFrBLoc= 'PFG' or TdToBLoc= 'PFG')              
  If @Row > 0              
  begin              
   Select @ErrMsg= 'From/ To Bag Location Cannot Be ''PFG'' In Bag Movement'              
   GoTo ErrHndlr              
  end              
*/              
  /**** Cannot Update or Delete if Not the last Txn of the Bag              
        Checking for TdSrNo=0, <>0 records *******/              
/*  select @Row=Count('x') from deleted where              
   Not Exists (Select 'x' from Bag where TdCoCd= BCoCd and              
        TdByy= BYy and TdBChr= BChr and TdBNo= BNo and              
        ((TdYy>= BLstYy and TdKey>= BLstKey)              
          or IsNull(BLstKey, 0)= 0))              
  If @Row > 0              
  Begin              
   Select @ErrMsg= 'Cannot Update Or Delete, Not The Last Txn Of The Bag'              
   GoTo ErrHndlr              
  end              
*/              
/* **** Zubin 211 **** */              
  /* if flute bag, then the RmCtg-SCtg shld be as in PValue1-PValue2 of Param for Ptyp= 'BCHR' */              
  If @wTcTyp In('DT', 'BS')              
  Begin              
   /****** (Jen 2.13 CT) changed the join condition for Param for Flute Bags ******/              
   /* (Bef 22/06/05) select @Row= Count('x') from Inserted Ins              
   Join Txnd TdA On TdA.TdCoCd= Ins.TdCoCd and TdA.TdTc= Ins.TdTc and              
    TdA.TdYy = Ins.TdYy and TdA.TdChr = Ins.TdChr and TdA.TdNo = Ins.TdNo and              
    TdA.TdSr= Ins.TdSr and TdA.TdSrNo= 0              
   Join RmMst On RmCd= Ins.TdRmCd              
   Join Param ON PTyp= 'BCHR' and PMCd= TdA.TdBChr and PSCd= '' and PValue= 'Y'              
   where Ins.TdSrNo> 0 and              
    NOT (              
     PValue1= (Case when PValue1= '' then '' else RmCtg end ) and              
     PValue2= (Case when PValue2= '' then '' else RmSCtg end )              
         ) */              
   /* Current Partition */              
   select @Row= Count('x') from Inserted Ins              
   Join RmMst On RmCd= Ins.TdRmCd and RmPrtKey=Ins.TdPrtKey              
   Join Param ON PTyp= 'BCHR' and PMCd= Ins.TdBChr and PSCd= '' and PValue in ('F')               
   where Ins.TdPrtKey=@wCurrPRtn and Ins.TdSrNo> 0 and              
    NOT (              
     PValue1= (Case when PValue1= '' then '' else RmCtg end) and              
     (',' + PVALUE2 + ',') LIKE (CASE WHEN PVALUE2='' THEN '%' ELSE '%,'+RmSCtg+',%' END)              
         )              
   If @Row> 0              
   begin              
    Select @ErrMsg= 'Cannot Issue Raw Material Of This Ctg/Sub-Category To This Flute Bag'              
    GoTo ErrHndlr              
   end              
  End              
              
  If @wTcTyp In('DT')              
  Begin              
   /* (Bef 22/06/05) select @Row= Count('x') from Inserted Ins              
    Join Txnd TdA On TdA.TdCoCd= Ins.TdCoCd and TdA.TdTc= Ins.TdTc and              
     TdA.TdYy = Ins.TdYy and TdA.TdChr = Ins.TdChr and TdA.TdNo = Ins.TdNo and              
     TdA.TdSr= Ins.TdSr and TdA.TdSrNo= 0              
    where (Ins.TdFBRmQty<> '' or Ins.TdFBRmWt<> '' ) and            
     Exists (Select 'x' from Param where PTyp= 'BCHR' and PMCd= TdA.TdBChr and              
      PSCd= '' and PValue= 'N') */              
              
   /****** (Jen 2.13 CT changed the where condition) ******/              
   /* Current Partition */              
   select @Row= Count('x') from Inserted Ins              
    where Ins.TdPrtKey=@wCurrPrtn and (Ins.TdFBRmQty<> '' or Ins.TdFBRmWt<> '' ) and              
     Exists (Select 'x' from Param where PTyp= 'BCHR' and PMCd= Ins.TdBChr and              
      PSCd= '' and PValue in ('C', 'P'))              
   If @Row> 0              
   begin              
    Select @ErrMsg= 'Cannot Enter RM Quantity/Weight Reference For Primary/ Component Bags'              
    GoTo ErrHndlr              
   end              
              
   /* Zubin 212 */              
   /* Current Partition */              
     select @row= count('x') from inserted where TdPrtKey=@wCurrPRtn and TdSrNo <> 0 and              
     TdFrRmLoc<> (select LocCd from Loc where LocCoCd= TdCoCd and LocTyp= 'W') AND              
     TdToRmLoc<> (select LocCd from Loc where LocCoCd= TdCoCd and LocTyp= 'W')              
     if @row> 0              
   begin              
       select @errmsg= 'Either RmLocFr Or RmLocTo Should Belong To ''W'' Loc Type'              
    goto ErrHndlr              
     end              
   /* Zubin 212 */              
  End              
              
  If @wTcTyp Not In('DT')              
  Begin              
   /* Current Partition */               
   select @Row= Count('x') from Inserted where TdPrtKey=@wCurrPrtn and TdFBRmQty<> '' or TdFBRmWt<> ''              
   If @Row> 0              
   begin              
    Select @ErrMsg= 'Cannot Enter RM Quantity/Weight Reference For This TcTyp'              
    GoTo ErrHndlr              
   end              
  End              
/* **** Zubin 211 **** */              
              
  -- urmi ***              
  /*** Cannot Change any Other field except TdAck if the Bag is acknowledged */              
  if @mode = 'C'              
  Begin              
          
  /*** Jenny ***/              
  /****** Cannot Change as rec exists in TxndPrd ******/              
/*  If @wEntTyp= 'TxnBag'              
  begin              
              
   select @Row=Count('x') from Inserted Ins where TdPrdYN= 'N' and              
     Exists (Select 'x' from TxndPrd where TpCoCd= TdCoCd and TpTc= TdTc              
     and TpYy= TdYy and TpChr= TdChr and TpNo= TdNo and TpSr= TdSr)              
   If @Row > 0              
   begin              
    Select @ErrMsg='Cannot Change Prd as Production Points Exist'              
    GoTo ErrHndlr              
   end              
  end              
*/              
              
   /**** urmi ***/              
   If @wTcTyp= 'DT'              
   begin              
    /* Current Partition */              
    select @Row= Count('x') from Inserted Ins where TdPRtKey=@wCurrPrtn and   
     Exists (Select 'x' from deleted del where ins.TdPrtKey=del.TdPrtKey and ins.TdIdNo=del.TdIdNo               
     and ins.TdCoCd= del.TdCoCd and ins.TdTc= del.TdTc and ins.TdYy= del.TdYy              
     and ins.TdChr= del.TdChr and ins.TdNo= del.TdNo              
     and ins.TdSr = del.TdSr and ins.TdSrNo = del.TdSrNo and              
      (ins.TdByWrk<> del.TdByWrk or ins.TdByLoc<> del.TdByLoc))              
     and              
     Exists (Select 'x' from TxndPrd where TpPrtKey=ins.TdPrtKey               
      and TpTdIdNo=ins.TdIdNo and TpCoCd= ins.TdCoCd              
      and TpTc= ins.TdTc and TpYy= ins.TdYy and TpChr= ins.TdChr              
      and TpNo= ins.TdNo and TpSr= ins.TdSr)              
    If @Row > 0              
    begin              
     Select @ErrMsg= 'Cannot Change Prd as Production Points Exist'              
     GoTo ErrHndlr              
    end              
   end              
               
   /* Zubin 212 TdLotNo added */              
   /* Current Partition */                
   select @Row= Count('x') from inserted ins where ins.TdPrtKey=@wCurrPrtn and ins.TdTc = 'BV' and              
   not exists(Select 'X' from deleted del where del.TdPrtKey=ins.TdPrtKey and del.TdIdNo=ins.TdIdNo               
   and del.Tdcocd= ins.TdCoCd and del.TdTc= ins.TdTc and del.TdYy= ins.TdYy and del.TdChr= ins.TdChr              
   and del.TdNo= ins.TdNo and del.TdSr= ins.TdSr and del.TdBYy= ins.TdBYy              
   and del.TdBChr= ins.TdBChr and del.TdBNo= ins.TdBNo and del.TdBQty= ins.tdBQty              
   and del.TdBDc= ins.TdBDc and del.TdBGrWt= ins.TdBGrWt and del.TdFrBLoc= ins.TdFrBLoc              
   and del.TdToBLoc= ins.TdToBLoc and del.TdFrRmLoc= ins.TdFrRmLoc and del.TdFrRmDc= ins.TdFrRmDc              
   and del.TdRmCd= ins.TdRmCd and del.TdLotNo= ins.TdLotNo and del.TdRmSz= ins.TdRmSz              and
   del.TdRmSz2= ins.TdRmSz2  and del.TdRmSz3= ins.TdRmSz3                          
   and del.TdRmStkRt= ins.TdRmStkRt              
   and del.TdRmQty= ins.TdRmQty and del.TdRmWt= ins.TdRmWt and del.TdToRmLoc= ins.TdToRmLoc              
   and del.TdToRmDc= ins.TdToRmDc and del.TdWrk= ins.TdWrk and del.TdPrdYN= ins.TdPrdYN              
   and del.TdByLoc= ins.TdByLoc and del.TdByWrk= ins.TdByWrk and del.TdDustWt= ins.TdDustWt and              
   del.TdKey= ins.TdKey and del.TdRefYy= ins.TdRefYy and del.TdRefKey= ins.TdRefKey and              
   del.TdRjCd= ins.TdRjCd and del.TdRjQty= ins.TdRjQty and del.TdRjDc= ins.TdRjDc and              
   del.TdPtQty= ins.TdPtQty and del.TdRjPtQty= ins.TdRjPtQty and del.TdDesc= ins.TdDesc              
   and del.TdPurRt= ins.TdPurRt and del.TdPurAmt= ins.TdPurAmt and del.TdPrevYy= ins.TdPrevYy              
   and del.TdPrevKey= ins.TdPrevKey and del.TdYyKey= ins.TdYyKey and del.TdPcPerCt= ins.TdPcPerCt )              
   If @Row > 0              
   Begin              
    Select @ErrMsg= 'Cannot Update any as Bag is Acknowledged'              
    GoTo ErrHndlr              
   end              
  End              
              
  /**** Cannot Update or Delete if Fg Txn later to the Txn Entry of the Bag exists *******/              
  /* Current Partition */               
  select @Row=Count('x') from deleted where TdPRtKey=@wCurrPrtn and              
   Exists (Select 'x' from Fgd where FdPrtKey=TdPrtKey and FdBIdNo=TdBIdNo and FdCoCd= TdCoCd and FdBYy= TdBYy              and FdBChr= TdBChr and FdBNo= TdBNo and FdBYyKey>= TdYyKey)              
  If @Row > 0              
  begin              
   Select @ErrMsg= 'Cannot Update Or Delete, A Later Fg Txn Exists For The Bag'              
   GoTo ErrHndlr              
  end              
              
  /**** Cannot Add Or Update if Fg Txn later to the Txn Entry of the Bag exists              
   (Check for TdSrNo<> 0 records) *******/              
  /* Current Partition */              
  select @Row=Count('x') from inserted where TdPrtKey=@wCurrPrtn and TdSrNo<> 0 and              
   Exists (Select 'x' from Fgd where FdPrtKey=TDPrtKey and FdBIdNo=TdBIdNo and FdCoCd= TdCoCd and FdBYy= TdBYy              
   and FdBChr= TdBChr and FdBNo= TdBNo and FdBYyKey>= TdYyKey)              
  If @Row > 0              
  begin              
   Select @ErrMsg= 'Cannot Add Or Update, A Later Fg Txn Exists For The Bag'              
   GoTo ErrHndlr              
  end              
              
              
/* After 15/05/02 */              
  if @mode = 'A'              
  Begin              
   /**** Melting Can Be Done Only For Bags With BQty= 0 and BPtQty= 0 *******/              
   /* Current Partition */              
   select @Row=Count('x') from inserted where @wTcTyp= 'MLT' and TdPrtKey=@wCurrPrtn and               
    (IsNull((Select Cast(BQty As Decimal(8,2)) from Bag where TdBIdNo=BIdNo and TdCoCd= BCoCd and              
         TdBYy= BYy and TdBChr= BChr and TdBNo= BNo and TdPrtKey=BPrtKEy), 0)> 0              
    or IsNull((Select BPtQty from Bag where TdBIdNo=BIdNo and TdCoCd= BCoCd and              
         TdBYy= BYy and TdBChr= BChr and TdBNo= BNo and TdPrtKey=BPrtKey), 0)<> 0)              
   If @Row > 0              
   begin              
    Select @ErrMsg='Cannot Melt Bag As Bag Qty/Part Qty <> 0'              
    GoTo ErrHndlr              
   end              
              
/* Bef Rel 1.11              
   ****** Cannot Make Any Transaction Other Than Melting For A Rejected Bag ******              
   select @Row=Count('x') from inserted ins where @wTcTyp<> 'MLT' and              
    exists (Select 'x' from Txnd Td where Td.TdYy= ins.TdPrevYy and              
     Td.TdKey= ins.TdPrevKey and (Select PValue from Param              
     where PTyp= 'TC' and PMCd= Td.TdTc)= 'REJ')              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Cannot Make Any Transaction For A Rejected Bag'              
    GoTo ErrHndlr              
   end              
*/              
              
   /****** Cannot Make Any Transaction Other Than Melting Or Derejection For A Rejected Bag (Rejected Bag is a Bag with BRjQty> 0 or BRjPtQty<> 0) ******/              
   /* Current Partition */              
   select @Row=Count('x') from inserted ins join Bag on BIdNo=TdBIdNo and BCoCd= TdCoCd              
    and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo and BPrtKey=TdPrtKey              
    where @wTcTyp not in('MLT', 'REJ') and TdPrtKey=@wCurrPrtn and (Round(BRjQty, 1)> 0 or BRjPtQty<> 0)              
    /* exists (Select 'x' from Txnd Td where Td.TdYy= ins.TdPrevYy and              
     Td.TdKey= ins.TdPrevKey and (Select PValue from Param              
     where PTyp= 'TC' and PMCd= Td.TdTc)= 'REJ') */              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Cannot Make Any Transaction For A Rejected Bag'              
    GoTo ErrHndlr              
   end              
              
   /****** Cannot Make Any Transaction For A Melted Bag ******/              
   /* Current Partition */              
   select @Row=Count('x') from inserted ins where TdPrtKey=@wCurrPrtn and              
    exists (Select 'x' from Txnd Td where Td.TdPrtKey=ins.TdPrtKey and               
     Td.TdCoCd= ins.TdCoCd and Td.TdYy= ins.TdPrevYy and Td.TdKey= ins.TdPrevKey and              
     (Select PValue from Param              
      where PTyp= 'TC' and PMCd= Td.TdTc)= 'MLT')              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Cannot Make Any Transaction For A Melted Bag'              
    GoTo ErrHndlr              
   end              
  End              
              
/* Zubin 212 */              
  /* Lot No. Shld be blank for @wTcTyp in ('BV','REJ') */              
  if @wTcTyp in ('BV', 'REJ')              
  begin             /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdLotNo<> ''              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Lot No. Should Be Blank'              
      GoTo ErrHndlr              
   end              
  end              
              
  /* Lot No = '' for TdSrNo= 0 ('TXNBAG') */              
  /* Current Partition */              
  select @Row=Count('x') from inserted ins where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and TdLotNo<> ''              
  If @Row > 0              
  begin              
   Select @ErrMsg= 'Lot No Should Be Blank For TdSrNo= 0'              
   GoTo ErrHndlr              
  end              
/* Zubin 212 */              
 END              
              
              
 /****** Bag Updates *******/              
              
 /*** Update Bag from TdToBLoc ***/              
 if @mode in ('D', 'C') and @wEntTyp= 'TxnBag'              
 begin              
  /*** Set the Bag Loc as TdToBLoc of the Transaction of the Bag which has the maximum value for TdYyKey ***/              
  /*** If there is no tarnsaction then Bag Loc = Opn Loc ***/              
  /* Current Partition */              
  update Bag set              
  /*** (Jen 2.12) 28/12/05 ***/              
  BLoc= Isnull((select F.FgToBLoc from Fgd Fd              
    join Fg F on F.FgIdNo=Fd.FdFgIdNo and F.FgCoCd= Fd.FdCoCd              
     and F.FgTc= Fd.FdTc and F.FgYy= Fd.FdYy              
     and F.FgChr= Fd.FdChr and F.FgNo= Fd.FdNo and F.FgPrtKey=Fd.FdPrtKey              
    where Fd.FdPrtKey=del.TdPrtKey and Fd.FdBIdNo=del.TdBIdNo and Fd.FdCoCd= del.TdCoCd and Fd.FdBYy= del.TdBYy              
     and Fd.FdBChr= del.TdBChr and Fd.FdBNo= del.TdBNo              
     and Fd.FdBYyKey=              
     (select max(td.TDYyKey) from Txnd td where              
      Td.TdSrNo= 0 and Td.TdPrtKey=del.TdPrtKey and td.TdBIdNo=del.TdBIdNo and td.TdCoCd= del.TdCoCd and td.TdBYy= del.TdBYy              
      and td.TdBChr= del.TdBChr and td.TdBNo= del.TdBNo)              
     and Fd.FdYy+ Str(Fd.FdKey)=              
     (Select max(Fd1.FdYy+ Str(Fd1.FdKey))              
     From Fgd Fd1 where Fd1.FdTc in (Select PMCd from Param where PTyp= 'TC' and PValue= 'FWB')           
      and Fd1.FdPrtKey=del.TdPrtKey and Fd1.FdBIdNo=del.TdBIdNo and Fd1.FdCoCd= del.TdCoCd and Fd1.FdBYy= del.TdBYy              
      and Fd1.FdBChr= del.TdBChr and Fd1.FdBNo= del.TdBNo)              
    ),              
    Isnull((select /* (Bef 2.13) TdLoc.TdToBLoc */ (case when (TdLoc.TdToBLoc<> '' and TdLoc.TdAck = 'Y') then TdLoc.TdToBLoc else TdLoc.TdFrBLoc end)               
    from Txnd TdLoc where del.TdPrtKey=TdLoc.TdPrtKey and del.TdBIdNo=TdLoc.TdBIdNo and              
    del.TdCoCd= TdLoc.TdCoCd and del.TdBYy= TdLoc.TdBYy and              
    del.TdBChr= TdLoc.TdBChr and del.TdBNo= TdLoc.TdBNo and              
    TdLoc.TdSrNo= 0 and /* (Bef 2.13) TdLoc.TdAck = 'Y' and */              
    TdLoc.TdYyKey= IsNull((select max(td.TdYyKey) from Txnd td              
     where /* (Bef 2.13) td.TdToBLoc<> '' and */ del.TdPrtKey=td.TdPrtKey and del.TdBIdNo=td.TdBIdNo               
     and del.TdCoCd= td.TdCoCd and del.TdBYy= td.TdBYy and del.TdBChr= td.TdBChr and del.TdBNo= td.TdBNo               
     and td.TdSrNo= 0 and ((td.TdToBLoc<> '' and td.TdAck = 'Y') Or td.TdFrBLoc<> '')               
     /* (Bef 2.13) and td.TdAck = 'Y' */ ), '')              
    ), BOpnLoc)              
   ),              
  /*** (Jen 2.12) 28/12/05 ***/              
              
  /*** (Bef 2.12) ***              
  BLoc= Isnull((select TdLoc.TdToBLoc from Txnd TdLoc where              
   del.TdCoCd= TdLoc.TdCoCd and del.TdBYy= TdLoc.TdBYy and              
   del.TdBChr= TdLoc.TdBChr and del.TdBNo= TdLoc.TdBNo and              
   TdLoc.TdSrNo= 0 and TdLoc.TdAck = 'Y' and              
   TdLoc.TdYyKey= IsNull((select max(td.TdYyKey) from Txnd td              
    where td.TdToBLoc<> '' and td.TdSrNo= 0 and del.TdCoCd= td.TdCoCd              
    and del.TdBYy= td.TdBYy and del.TdBChr= td.TdBChr and del.TdBNo= td.TdBNo              
    and td.TdAck = 'Y'), '')              
   ), BOpnLoc),              
  *** (Bef 2.12) ***/              
              
/**urmi Bag Recv Dt 4 BDlDays 2,06 */              
  /* Current Partition */              
  BRecvDt= Isnull((select T.TDt from Txn T join Txnd TdDt on T.TPrtKey=TdDt.TdPrtKey and T.TCoCd= TdDt.TdCoCd              
    and T.TIdNo=TdDt.TdTIdNo and T.TTc= TdDt.TdTc and T.TYy= TdDt.TdYy and T.TChr= TdDt.TdChr and              
    T.TNo= TdDt.TdNo where del.TdPrtkey=TdDt.TdPrtKey and              
    del.TdCoCd= TdDt.TdCoCd and del.TdBYy= TdDt.TdBYy and              
    del.TdBChr= TdDt.TdBChr and del.TdBNo= TdDt.TdBNo and              
    TdDt.TdSrNo= 0 and TdDt.TdAck = 'Y' and TdDt.TdYyKey=              
    IsNull((select max(td.TdYyKey) from Txnd td where              
     td.TdToBLoc<> '' and td.TdSrNo= 0 and del.TdPrtKey=td.TdPrtKey and               
     del.TdBIdNo=td.TdBIdNo and del.TdCoCd= td.TdCoCd and del.TdBYy= td.TdBYy and              
     del.TdBChr= td.TdBChr and del.TdBNo= td.TdBNo and              
     td.TdAck = 'Y'), '')              
    ), BOpnDt)              
  from deleted del where BPrtKey=del.TdPrtKey and BIdNo=del.TdBIdNo and BCoCd= del.TdCoCd and BYy= del.TdBYy              
   and BChr= del.TdBChr and BNo= del.TdBNo              
   and del.TdSrNo= 0 and del.TdToBLoc<> ''              
              
  /*** update Bag set BPrdStg= IsNull((Select PMCd from Param P1 where PTyp= 'PRDSTG'              
   and PNum= IsNull((Select max(P2.PNum) from Txnd TdLoc              
      join Loc on LocCoCd= TdLoc.TdCoCd and LocTyp= 'P' and LocCd= TdLoc.TdToBLoc              
      join Param P2 on P2.PTyp= 'PRDSTG' and P2.PMCd= LocPrdStg              
      where del.TdCoCd= TdLoc.TdCoCd and del.TdBYy= TdLoc.TdBYy              
      and del.TdBChr= TdLoc.TdBChr and del.TdBNo= TdLoc.TdBNo              
      and TdLoc.TdSrNo= 0 and TdLoc.TdToBLoc<> '' and TdLoc.TdAck= 'Y'              
     ), 0)              
   ), '')              
  from deleted del where BCoCd= del.TdCoCd and BYy= del.TdBYy              
   and BChr= del.TdBChr and BNo= del.TdBNo              
   and del.TdSrNo= 0 and del.TdToBLoc<> '' ***/              
              
  if IsNull((Select max(hPpcYN) from Head join deleted on TdCoCd= HCoCd where HCd= @wHCd), '') = 'Y'              
  Begin              
   /*** Updation of the BPrdStg field ***/              
   /* Current Partition */              
   update Bag set BPrdStg= IsNull((Select PMCd from Param P1 where PTyp= 'PRDSTG'              
    and PNum= IsNull((Select max(P2.PNum) from Txnd TdLoc              
       join Loc on LocCoCd= TdLoc.TdCoCd and LocTyp= 'P' and LocCd= TdLoc.TdByLoc              
       join Param P2 on P2.PTyp= 'PRDSTG' and P2.PMCd= LocPrdStg              
       where del.TdPrtKey=TdLoc.TdPrtKey and del.TdBIdNo=TdLoc.TdBIdNo and del.TdCoCd= TdLoc.TdCoCd               
       and del.TdBYy= TdLoc.TdBYy              
       and del.TdBChr= TdLoc.TdBChr and del.TdBNo= TdLoc.TdBNo              
       and TdLoc.TdSrNo= 0 and TdLoc.TdByLoc<> '' and TdLoc.TdPrdYN= 'Y'              
      ), 0)              
    ), '')              
   from deleted del where BPrtKey=del.TdPrtKey and BIdNo=del.TdBIdNo and BCoCd= del.TdCoCd and BYy= del.TdBYy              
    and BChr= del.TdBChr and BNo= del.TdBNo              
    and del.TdSrNo= 0 and del.TdByLoc<> ''              
  End              
              
  /*** Manali 3.10.0 - amore problem  ***/            
  if @mode in ('D') and @wTcTyp= 'BM'      
  begin          
    update Bag set              
    BCls= 'N',               
    BClsDt= '01/01/80'                
    from deleted del where BPrtKey=del.TdPrtKey and BIdNo=del.TdBIdNo and BCoCd= del.TdCoCd and BYy= del.TdBYy and BChr= del.TdBChr              
     and BNo= del.TdBNo and del.TdSrNo= 0       
     and BLstYyKey=del.TdYyKey and BCls='Y' and convert (decimal (16, 1), BQty)=convert (decimal (16, 1), 0)      
     and (Select PValue From Param Where PTyp= 'BCHR' And PMCd= del.TdBChr And PSCd= '') in ('C', 'F')      
  End      
        
  /*** Set the Bag Loc as TdWrk of the Transaction of the Bag which has the maximum value for TdYyKey. ***/              
  /*** If there is no tarnsaction then Bag Loc = 'ZSELF' ***/              
  /*** Set the LstYy as TdYy of the Transaction of the Bag which has the maximum value for TdYyKey. ***/              
  /*** If there is no tarnsaction then LstYy = '' ***/              
  /*** Set the LstKey as TdKey of the Transaction of the Bag which has the maximum value for TdYyKey. ***/              
  /*** If there is no tarnsaction then LstKey = 0 ***/              
  /*** Set the LstYyKey as TdYyKey of the Transaction of the Bag which has the maximum value for TdYyKey. ***/              
  /*** If there is no tarnsaction then LstYyKey = '' ***/              
  /* Current Partition */              
  update Bag set              
  BWrk= Isnull((select Wrk.TdWrk from Txnd Wrk where              
   Wrk.TdPrtKey=del.TdPrtKey and Wrk.TdBIdNo=del.TdBIdNo and Wrk.TdCoCd= del.TdCoCd and Wrk.TdBYy= del.TdBYy and Wrk.TdBChr= del.TdBChr and              
   Wrk.TdBNo= del.TdBNo and Wrk.TdSrNo= 0              
 and Wrk.TdYyKey= IsNull((select max(td.TDYyKey) from Txnd td where              
    Td.TdSrNo= 0 and del.TdPrtKey=td.TdPrtKey and del.TdBIdNo=Td.TdBIdNo and del.TdCoCd= td.TdCoCd               
    and del.TdBYy= td.TdBYy and del.TdBChr= td.TdBChr and del.TdBNo= td.TdBNo), '')              
   ), 'ZSELF'),              
  BLstYy= IsNull((select max(td.TdYy) from Txnd td where              
   Td.TdSrNo= 0 and del.TdPrtKey=td.TdPrtKey and del.TdBIdNo=td.TdBIdNo and del.TdCoCd= td.TdCoCd and del.TdBYy= td.TdBYy              
   and del.TdBChr= td.TdBChr and del.TdBNo= td.TdBNo), ''),              
  BLstKey= IsNull((select convert(int, substring(max(td.TDYyKey), 3, 7)) from Txnd td where              
   Td.TdSrNo= 0 and del.TdPrtKey=td.TdPrtKey and del.TdBIdNo=td.TdBIdNo and del.TdCoCd= td.TdCoCd and del.TdBYy= td.TdBYy and              
   del.TdBChr= td.TdBChr and del.TdBNo= td.TdBNo), 0),              
  BLstYyKey= IsNull((select max(td.TdYyKey) from Txnd td where              
   Td.TdSrNo= 0 and del.TdPrtKey=td.TdPrtKey and del.TdBIdNo=td.TdBIdNo and del.TdCoCd= td.TdCoCd and del.TdBYy= td.TdBYy              
   and del.TdBChr= td.TdBChr and del.TdBNo= td.TdBNo), ''),               
              
  /****** Jen 2.13 CT (considered component Bags) ******/              
  /*** 2.13 Jen, sachin ***/               
  BCls= (case when @mode in ('C', 'D') and @wTcTyp= 'BM'               
    and (Select PValue From Param Where PTyp= 'BCHR' And PMCd= del.TdBChr And PSCd= '') in ('C', 'F')               
    and  (convert (decimal (16, 1),               
      BQty+ IsNull((Select sum(D.TdBQty* (case D.TdBDc when 'C' then 1 when 'D'               
      then -1 else 0 end)) from deleted D where D.TdPrtKey=BPrtKey and D.TdBIdNo=BIdNo and D.TdCoCd = BCoCd and               
      D.TdBYy = BYy and D.TdBChr= BChr and D.TdBNo= BNo and D.TdSrNo= 0), 0)               
          + IsNull((Select sum(I.TdBQty* (case I.TdBDc when 'C' then -1 when 'D'               
      then 1 else 0 end)) from inserted I where I.TdPrtKey=BPrtKey and I.TdBIdNo=BIdNo and I.TdCoCd = BCoCd and               
      I.TdBYy = BYy and I.TdBChr= BChr and I.TdBNo= BNo and I.TdSrNo= 0), 0))               
     > convert (decimal (16, 1), 0)               
     OR BPtQty+ IsNull((Select sum(D.TdPtQty* (case D.TdBDc when 'C' then 1 when 'D'               
      then -1 else 0 end)) from deleted D where D.TdPrtKey=BPrtKey and D.TdBIdNo=BIdNo and D.TdCoCd = BCoCd and               
      D.TdBYy = BYy and D.TdBChr= BChr and D.TdBNo= BNo and D.TdSrNo= 0), 0)               
          + IsNull((Select sum(I.TdPtQty* (case I.TdBDc when 'C' then 1 when 'D'               
      then -1 else 0 end)) from deleted I where I.TdPrtKey=BPrtKey and I.TdBIdNo=BIdNo and I.TdCoCd = BCoCd and               
      I.TdBYy = BYy and I.TdBChr= BChr and I.TdBNo= BNo and I.TdSrNo= 0), 0)               
     > 0               
     )               
    then 'N'               
   else BCls end),              
  BClsDt= (case when @mode in ('C', 'D') and @wTcTyp= 'BM'               
    and (Select PValue From Param Where PTyp= 'BCHR' And PMCd= del.TdBChr And PSCd= '') in ('C', 'F')               
    and  (convert (decimal (16, 1),               
      BQty+ IsNull((Select sum(D.TdBQty* (case D.TdBDc when 'C' then 1 when 'D'               
      then -1 else 0 end)) from deleted D where D.TdPrtKey=BPrtKey and D.TdBIdNO=BIdNo and D.TdCoCd = BCoCd and               
      D.TdBYy = BYy and D.TdBChr= BChr and D.TdBNo= BNo and D.TdSrNo= 0), 0)               
          + IsNull((Select sum(I.TdBQty* (case I.TdBDc when 'C' then -1 when 'D'               
      then 1 else 0 end)) from inserted I where I.TdPrtKey=BPrtKey and I.TdBIdNo=BIdNo and I.TdCoCd = BCoCd and               
      I.TdBYy = BYy and I.TdBChr= BChr and I.TdBNo= BNo and I.TdSrNo= 0), 0))               
     > convert (decimal (16, 1), 0)               
     OR BPtQty+ IsNull((Select sum(D.TdPtQty* (case D.TdBDc when 'C' then 1 when 'D'               
      then -1 else 0 end)) from deleted D where D.TdPrtKey=BPrtKey and D.TdBIdNo=BIdNo and D.TdCoCd = BCoCd and               
      D.TdBYy = BYy and D.TdBChr= BChr and D.TdBNo= BNo and D.TdSrNo= 0), 0)               
        + IsNull((Select sum(I.TdPtQty* (case I.TdBDc when 'C' then 1 when 'D'               
      then -1 else 0 end)) from deleted I where I.TdPrtKey=BPrtKey and I.TdBIdNo=BIdNo and I.TdCoCd = BCoCd and               
      I.TdBYy = BYy and I.TdBChr= BChr and I.TdBNo= BNo and I.TdSrNo= 0), 0)               
     > 0               
     )               
    then '01/01/80'               
   else BClsDt end)                 
  /*** 2.13 Jen, sachin ***/               
  from deleted del where BPrtKey=del.TdPrtKey and BIdNo=del.TdBIdNo and BCoCd= del.TdCoCd and BYy= del.TdBYy and BChr= del.TdBChr              
   and BNo= del.TdBNo and del.TdSrNo= 0              
              
/* **** Zubin 211  **** */              
/* ****** Emr 2.12.0 Patch 02 - [06-07-2006] ****** */              
  If @wTcTyp<> 'BM' and (@mode= 'D' or (@mode= 'C' and (Update (TdBQty) or update (TdPtQty) or update (TdRjQty) or update (TdRjPtQty) ) ) )              
/* ****** Emr 2.12.0 Patch 02 - [06-07-2006] ****** */              
  Begin              
/* **** Zubin 211 **** */              
   update Bag set              
   BQty= BQty+ IsNull((Select sum(del.TdBQty* (case del.TdBDc when 'C' then 1 when 'D'              
    then -1 else 0 end)) from deleted del where del.TdPrtKey=BPrtKEy and del.TdBIdNo=BIdNo and del.TdCoCd = BCoCd and              
    del.TdBYy = BYy and del.TdBChr= BChr and del.TdBNo= BNo and del.TdSrNo= 0), 0),              
   BPtQty= BPtQty+ IsNull((Select sum(del.TdPtQty* (case del.TdBDc when 'C' then 1 when 'D'              
    then -1 else 0 end)) from deleted del where del.TdPrtKey=BPrtKEy and del.TdBIdNo=BIdNo and del.TdCoCd = BCoCd and              
    del.TdBYy = BYy and del.TdBChr= BChr and del.TdBNo= BNo and del.TdSrNo= 0), 0),              
   BRjQty= BRjQty+ IsNull((Select sum(del.TdRjQty* (case del.TdRjDc when 'C' then 1 when 'D'              
    then -1 else 0 end)) from deleted del where del.TdPrtKey=BPrtKEy and del.TdBIdNo=BIdNo and del.TdCoCd = BCoCd and              
    del.TdBYy = BYy and del.TdBChr= BChr and del.TdBNo= BNo and del.TdSrNo= 0), 0),              
   BRjPtQty= BRjPtQty+ IsNull((Select sum(del.TdRjPtQty* (case del.TdRjDc when 'C' then 1 when 'D'              
    then -1 else 0 end)) from deleted del where del.TdPrtKey=BPrtKEy and del.TdBIdNo=BIdNo and del.TdCoCd = BCoCd and              
    del.TdBYy = BYy and del.TdBChr= BChr and del.TdBNo= BNo and del.TdSrNo= 0), 0)              
   from deleted where BPrtKey=deleted.TdPrtKey and BIdNo=deleted.TdBIdNo and BCoCd= deleted.TdCoCd and BYy= deleted.TdBYy              
    and BChr= deleted.TdBChr and BNo= deleted.TdBNo              
    and deleted.TdSrNo=0              
/* **** Zubin 211 **** */              
  End              
              
  /* Sachin 3.02.0 - Updating BMaxTxnDt with Last Max Txn Date when current record is deleted */                
  If (@mode='D')              
  Begin    
   Update Bag               
   Set BMaxTxnDt = IsNull((Select Max(qDt)               
         From (Select IsNull(Max(Tddt),'01/01/80') qDt               
           From Txnd               
           where TdPrtKey=Del.TdPrtKey and TdBIdNo=Del.TdBIdNo and Tdcocd=Del.TdCoCd and TdByy=Del.TdBYy and Tdbchr=Del.TdBChr and Tdbno=del.TdBNo and TdIdNo<>del.TdIdNo                
           Union All              
            Select IsNull(Max(Fddt),'01/01/80') qDt               
           From fgd               
           where FdPrtKey=Del.TdPrtKey and FdBIdNo=Del.TdBIdNo and Fdcocd=Del.TdCoCd and Fdbyy=Del.TdBYy and fdbchr=Del.TdBChr and Fdbno=del.TdBNo              
              Union All              
            Select BOpnDt qDt From Bag               
           Where BPrtKey=Del.TdPrtKey and BIdNo=Del.TdBIdNo and BCoCd=Del.TdCoCd and BYy=Del.TdBYy and BChr=Del.TdBChr and BNo=del.TdBNo) B),BOpnDt)              
   From Deleted del              
   Where del.TdPrtKey=@wCurrPrtn and Bprtkey=del.TdPrtKey and BIdNo=Del.TdBIdNo and BCocd=Del.TdCoCd and Byy=Del.TdBYy and bchr=Del.TdBChr and bno=del.TdBNo                
  End                
  /* Sachin 3.02.0 - Updating BMaxTxnDt with Last Max Txn Date when current record is deleted */               
              
/* ****** Emr 2.12.0 Patch 02 - [06-07-2006] ****** */              
  If @wTcTyp= 'BM' and (@mode= 'D' or (@mode= 'C' and (Update (TdBQty) or update (TdPtQty) or update (TdRjQty) or update (TdRjPtQty) ) ) )              
/* ****** Emr 2.12.0 Patch 02 - [06-07-2006] ****** */              
  Begin              
   /****** (Jen 2.13 CT) changed the query to consider component bags ******/              
   /* Current Partition */              
   update Bag set                 
   BQty= BQty+ IsNull((Select sum(del.TdBQty* (case del.TdBDc when 'C' then 1 when 'D'              
    then -1 else 0 end)) from deleted del where del.TdPrtKey=BPrtKey and del.TdBIdNo=BIdNo and del.TdCoCd = BCoCd and              
    del.TdBYy = BYy and del.TdBChr= BChr and del.TdBNo= BNo and del.TdSrNo= 0 and              
     (Select PValue from Param where PTyp= 'BCHR' and PMCd= del.TdBChr and              
      PSCd= '' ) in ('C', 'F') ), 0),              
   BPtQty= BPtQty+ IsNull((Select sum(del.TdPtQty* (case del.TdBDc when 'C' then 1 when 'D'              
    then -1 else 0 end)) from deleted del where del.TdPrtKey=BPrtKey and del.TdBIdNo=BIdNo and del.TdCoCd = BCoCd and              
    del.TdBYy = BYy and del.TdBChr= BChr and del.TdBNo= BNo and del.TdSrNo= 0 and              
     (Select PValue from Param where PTyp= 'BCHR' and PMCd= del.TdBChr and              
      PSCd= '' ) in ('C', 'F') ), 0),              
   BRjQty= BRjQty+ IsNull((Select sum(del.TdRjQty* (case del.TdRjDc when 'C' then 1 when 'D'              
    then -1 else 0 end)) from deleted del where del.TdPrtKey=BPrtKey and del.TdBIdNo=BIdNo and del.TdCoCd = BCoCd and              
    del.TdBYy = BYy and del.TdBChr= BChr and del.TdBNo= BNo and del.TdSrNo= 0 and              
     (Select PValue from Param where PTyp= 'BCHR' and PMCd= del.TdBChr and              
      PSCd= '' ) in ('C', 'F') ), 0),              
   BRjPtQty= BRjPtQty+ IsNull((Select sum(del.TdRjPtQty* (case del.TdRjDc when 'C' then 1 when 'D'              
    then -1 else 0 end)) from deleted del where del.TdPrtKey=BPrtKey and del.TdBIdNo=BIdNo and del.TdCoCd = BCoCd and              
    del.TdBYy = BYy and del.TdBChr= BChr and del.TdBNo= BNo and del.TdSrNo= 0 and              
     (Select PValue from Param where PTyp= 'BCHR' and PMCd= del.TdBChr and              
      PSCd= '' ) in ('C', 'F') ), 0)              
   from deleted where BPrtKey=deleted.TdPrtKey and BIdNo=deleted.TdBIdNo and BCoCd= deleted.TdCoCd and BYy= deleted.TdBYy              
    and BChr= deleted.TdBChr and BNo= deleted.TdBNo              
    and deleted.TdSrNo=0 and (Select PValue from Param where PTyp= 'BCHR' and              
     PMCd= deleted.TdBChr and PSCd= '' ) in ('C', 'F')               
  End          
/* **** Zubin 211 **** */              
              
  /* Current Partition */              
  update Bag set              
  BGrWt= BGrWt+ IsNull((Select sum((case (case when del.TdFrRmLoc='W' then del.TdFrRmDc              
            when del.TdToRmLoc='W' then del.TdToRmDc end)              
                     when 'C' then 1 when 'D' then -1 else 0 end)* del.TdRmWt/              
   (case when RmCtg in ('D','C') then 5 else 1 end))              
   from deleted del Join RmMst on RmCd= del.TdRmCd and RmPrtKey=del.TdPrtKey              
   where del.TdBIdNo=BIdNo and del.TdCoCd= BCoCd and del.TdBYy= BYy and del.TdBChr= BChr              
   and del.TdBNo= BNo and del.TdPrtKey=BPrtKey and del.TdRmCd<> ''), 0)              
  from deleted where BPrtKey=deleted.TdPrtKey and BIdNo=deleted.TdBIdNo and BCoCd= deleted.TdCoCd and BYy= deleted.TdBYy              
   and BChr= deleted.TdBChr and BNo= deleted.TdBNo              
   and deleted.TdByy<> '' and deleted.TdBChr<> ''              
   and deleted.TdBNo<> 0 and deleted.TdRmCd<> ''              
              
  If @wEntTyp= 'TxnBag' and @wTcTyp= 'BM'              
  Begin              
   If @Mode= 'D'              
   Begin              
    /****** (Jen 2.13 CT changed the query where clause for Component Bags) ******/              
    /* ****** Sachin 2.13.0 - [28-06-2006] - Flute Bag Close On Merge ****** */              
    /* Current Partition */              
    Update Bag               
     Set BCls = 'N',              
         BClsDt = '01/01/80'              
    From Deleted Del              
    Where BPrtKey=Del.TdPrtKey and BIdNo=Del.TdBIdNo and BCoCd= Del.TdCoCd And BYy= Del.TdBYy And BChr= Del.TdBChr And BNo= Del.TdBNo               
     And Convert(Decimal(16, 3), BGrWt) <> Convert(Decimal(16, 3), 0)               
     And (Select PValue From Param Where PTyp= 'BCHR' And PMCd= Del.TdBChr And PSCd= '') in ('C', 'F')               
    /* (Bef 2.13 CT)              
    And (Select PValue From Param Where PTyp= 'BCHR' And PMCd= Del.TdBChr And PSCd= '' )= 'Y'              
    (Bef 2.13 CT) */              
    /* ****** Sachin 2.13.0 - [28-06-2006] - Flute Bag Close On Merge ****** */               
   End              
  End              
 End              
      
 -- 4.1.2.0      
 if @mode in ('A','C') and @wEntTyp= 'TxnRm'              
 Begin              
   If @wTcTyp= 'PR'               
   Begin                
  /***** Either All Best Use Order Fields are filled up or all are blank *****/      
  /* Current Partition */      
  Select @Row= Count('x') From Inserted Ins       
  Where Ins.TdPrtKey=@wCurrPrtn and (TdBstOdTc<> '' or TdBstOdYy<> '' or TdBstOdChr<> '' or TdBstOdNo<> 0)      
   and (TdBstOdTc= '' or TdBstOdYy= '' or TdBstOdChr= '' or TdBstOdNo= 0)       
  If @Row> 0      
  begin      
     Select @ErrMsg= 'Either All Order Fields Should Be Filled Or All Should Be Blank'      
     GoTo ErrHndlr       
  end       
      
  /***** TdBstOdNo = Valid Order Number *****/       
  /* Current Partition */      
  Select @Row= Count('x') From Inserted Ins Where Ins.TdPrtKey=@wCurrPRtn and TdBstOdNo<> 0       
   and not exists(Select 'x' From OrdMst where OmPrtKey=TdPrtkey and OmCoCd= TdCoCd and OmTc= TdBstOdTc and OmYy= TdBstOdYy       
    and OmChr= TdBstOdChr and OmNo= TdBstOdNo)       
  If @Row> 0       
  begin      
     Select @ErrMsg= 'Order Number Not Defined'      
     GoTo ErrHndlr      
  end      
      
  /***** TzDmCd = Valid Design Code *****/       
  /* Current Partition */      
  Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdBstDmCd<> ''       
   and not exists(Select 'x' From DsgMst where DmPrtKey=TdPrtKey and DmTcTyp= 'DM' and DmCd= TdBstDmCd and DmSz= '')       
  If @Row> 0       
  begin      
     Select @ErrMsg= 'Design Code Not Defined'      
     GoTo ErrHndlr      
  end      
   End      
 End       
              
 if @mode in ('A','C') and @wEntTyp= 'TxnBag'              
 begin              
  /* Sachin 3.02 - Updating the Max Transaction Date */              
  If (@mode = 'A')              
  Begin              
   Update Bag               
   Set BMaxTxnDt = TdDt              
   From Inserted                  
    Join Bag On BPrtKey=TdPrtKey and BIdNo=TdBIdNo and BCoCd=TdCoCd and BYy=TdBYy and BChr=TdBChr and BNo=TdBNo              
   Where TdPrtKey=@wCurrPrtn and TdDt>BMaxTxnDt                 
  End              
  /* Sachin 3.02 - Updating the Max Transaction Date */               
              
  update Bag set BWrk= inserted.TdWrk              
  from inserted where BPrtKey=inserted.TdPRtKey and BIdNo=inserted.TdBIdNo and BCoCd= inserted.TdCoCd and BYy= inserted.TdBYy              
   and BChr= inserted.TdBChr and BNo= inserted.TdBNo              
   and inserted.TdSrNo= 0 and              
   inserted.TdYyKey= IsNull((Select max(ins.TdYyKey) from inserted ins where              
    ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and ins.TdBYy = BYy and ins.TdBChr= BChr              
    and ins.TdBNo= BNo and ins.TdPRtKey=BPrtKey and ins.TdWrk<> '' and ins.TdSrNo= 0), '')              
 /* **** Zubin 211  **** */              
 /* ****** Emr 2.12.0 Patch 02 - [06-07-2006] ****** */              
  If @wTcTyp<> 'BM' and (@mode= 'A' or (@mode= 'C' and (Update (TdBQty) or update (TdPtQty) or update (TdRjQty) or update (TdRjPtQty) or update(TdYy) or update (TdKey) or update (TdYyKey) ) ) )              
 /* ****** Emr 2.12.0 Patch 02 - [06-07-2006] ****** */              
  Begin              
 /* **** Zubin 211  **** */              
   /* Current Partition */              
   update Bag set              
   BQty= BQty+ IsNull((Select sum(ins.TdBQty* (case ins.TdBDc when 'C' then -1 when 'D'              
    then 1 else 0 end)) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
    ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0), 0),              
   BPtQty= BPtQty+ IsNull((Select sum(ins.TdPtQty* (case ins.TdBDc when 'C' then -1 when 'D'              
    then 1 else 0 end)) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
    ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0), 0),              
   BRjQty= BRjQty+ IsNull((Select sum(ins.TdRjQty* (case ins.TdRjDc when 'C' then -1 when 'D'              
    then 1 else 0 end)) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
    ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0), 0),              
   BRjPtQty= BRjPtQty+ IsNull((Select sum(ins.TdRjPtQty* (case ins.TdRjDc when 'C' then -1 when 'D'              
    then 1 else 0 end)) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
    ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0), 0),              
   BLstYy= IsNull((Select max(ins.TdYy) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
    ins.TdBYy = BYy and ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and              
    ins.TdSrNo= 0), ''),              
   BLstKey= IsNull((Select convert(int, substring(max(ins.TdYyKey),3, 7))              
    from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and ins.TdBYy = BYy and              
    ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0), 0),              
   BLstYyKey= IsNull((Select max(ins.TdYyKey) from inserted ins              
    where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and ins.TdBYy = BYy and ins.TdBChr= BChr              
    and ins.TdBNo= BNo and ins.TdSrNo= 0), '')              
   from inserted where BPrtKey=inserted.TdPrtKey and BIdNo=inserted.TdBIdNo and BCoCd= inserted.TdCoCd and BYy= inserted.TdBYy              
    and BChr= inserted.TdBChr and BNo= inserted.TdBNo              
    and inserted.TdSrNo=0         
/* **** Zubin 211  **** */              
  End              
              
  If @wTcTyp= 'BM'               
  Begin              
   /*** 2.12 P2 [06-07-2006] - Update Clause added below ***/              
   If (@mode= 'A' or (@mode= 'C' and (Update (TdBQty) or update (TdPtQty) or update (TdRjQty) or update (TdRjPtQty)  ) ) )              
   /*** 2.12 P2 [06-07-2006] - Update Clause added above ***/              
   Begin              
    /****** (Jen 2.13 CT) changed the query to consider component bags ******/              
    /* Current Partition */              
    update Bag set              
    BQty= BQty+ IsNull((Select sum(ins.TdBQty* (case ins.TdBDc when 'C' then -1 when 'D'              
     then 1 else 0 end)) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
     ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0 and              
      (Select PValue from Param where PTyp= 'BCHR' and PMCd= ins.TdBChr and              
       PSCd= '' ) in ('C', 'F') ), 0),              
    BPtQty= BPtQty+ IsNull((Select sum(ins.TdPtQty* (case ins.TdBDc when 'C' then -1 when 'D'              
     then 1 else 0 end)) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
     ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0 and              
      (Select PValue from Param where PTyp= 'BCHR' and PMCd= ins.TdBChr and              
       PSCd= '' ) in ('C', 'F') ), 0),              
    BRjQty= BRjQty+ IsNull((Select sum(ins.TdRjQty* (case ins.TdRjDc when 'C' then -1 when 'D'              
     then 1 else 0 end)) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
     ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0 and              
      (Select PValue from Param where PTyp= 'BCHR' and PMCd= ins.TdBChr and              
       PSCd= '' ) in ('C', 'F') ), 0),              
    BRjPtQty= BRjPtQty+ IsNull((Select sum(ins.TdRjPtQty* (case ins.TdRjDc when 'C' then -1 when 'D'              
     then 1 else 0 end)) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
     ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0 and              
      (Select PValue from Param where PTyp= 'BCHR' and PMCd= ins.TdBChr and              
       PSCd= '' ) in ('C', 'F') ), 0)              
    from inserted where BPrtKey=inserted.TdPrtKey and BIdNo=inserted.TdBIdNo and BCoCd= inserted.TdCoCd and BYy= inserted.TdBYy              
     and BChr= inserted.TdBChr and BNo= inserted.TdBNo              
     and inserted.TdSrNo= 0 and (Select PValue from Param where PTyp= 'BCHR' and              
      PMCd= inserted.TdBChr and PSCd= '' ) in ('C', 'F')               
   End               
                 
   /* Current Partition */              
   update Bag set              
   BLstYy= IsNull((Select max(ins.TdYy) from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and              
    ins.TdBYy = BYy and ins.TdBYy = BYy and ins.TdBChr= BChr and ins.TdBNo= BNo and              
    ins.TdSrNo= 0), ''),              
   BLstKey= IsNull((Select convert(int, substring(max(ins.TdYyKey),3, 7))              
    from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and ins.TdBYy = BYy and              
    ins.TdBChr= BChr and ins.TdBNo= BNo and ins.TdSrNo= 0), 0),              
   BLstYyKey= IsNull((Select max(ins.TdYyKey) from inserted ins              
    where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and ins.TdBYy = BYy and ins.TdBChr= BChr              
    and ins.TdBNo= BNo and ins.TdSrNo= 0), '')              
   from inserted where BPrtKey=inserted.TdPrtKey and BIdNo=inserted.TdBIdNo and BCoCd= inserted.TdCoCd and BYy= inserted.TdBYy              
    and BChr= inserted.TdBChr and BNo= inserted.TdBNo              
    and inserted.TdSrNo=0              
  End              
              
/* **** Zubin 211 **** */              
  /* Current Partition */               
  Update Bag Set              
   BLoc= inserted.TdToBLoc,              
/**urmi Bag RecvDt 4 BDlDays 2.06 */              
   BRecvDt= (Select T.Tdt from Txn T where T.TPrtKey=inserted.TdPrtKey and T.TIdNo=inserted.TDTIdNo and T.TCoCd= inserted.TdCoCd              
    and T.TTc= inserted.TdTc and T.TYy= inserted.TdYy and T.TChr= inserted.TdChr and              
    T.TNo= inserted.TdNo)              
/**********************************/              
  from inserted where BPrtKey=inserted.TdPrtKey and BIdNo=inserted.TdBIdNo and BCoCd= inserted.TdCoCd and BYy= inserted.TdBYy              
   and BChr= inserted.TdBChr and BNo= inserted.TdBNo              
   and inserted.TdToBLoc<> '' and inserted.TdSrNo= 0 and inserted.TdAck= 'Y' and              
   inserted.TdYyKey= IsNull((Select max(ins.TdYyKey)              
    from inserted ins where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd = BCoCd and ins.TdBYy = BYy              
    and ins.TdBChr= BChr and ins.TdBNo= BNo              
    and ins.TdToBLoc<> '' and ins.TdSrNo= 0 and ins.TdAck= 'Y'), '')              
              
  /*** update Bag set BPrdStg= IsNull((Select PMCd from Param P1 where PTyp= 'PRDSTG'              
   and PNum= IsNull((Select max(P2.PNum) from Txnd TdLoc              
      join Loc on LocCoCd= TdLoc.TdCoCd and LocTyp= 'P' and LocCd= TdLoc.TdToBLoc              
      join Param P2 on P2.PTyp= 'PRDSTG' and P2.PMCd= LocPrdStg              
      where ins.TdCoCd= TdLoc.TdCoCd and ins.TdBYy= TdLoc.TdBYy              
      and ins.TdBChr= TdLoc.TdBChr and ins.TdBNo= TdLoc.TdBNo              
      and TdLoc.TdSrNo= 0 and TdLoc.TdToBLoc<> '' and TdLoc.TdAck= 'Y'              
     ), 0)              
   ), '')              
  from inserted ins where BCoCd= ins.TdCoCd and BYy= ins.TdBYy              
   and BChr= ins.TdBChr and BNo= ins.TdBNo              
   and ins.TdSrNo= 0 and ins.TdToBLoc<> '' ***/              
              
                
  if IsNull((Select max(hPpcYN) from Head join inserted on TdCoCd= HCoCd where HCd= @wHCd), '') = 'Y'              
  Begin              
   /*** Updation of the BPrdStg field ***/              
   /* Current Partition */              
   update Bag set BPrdStg= IsNull((Select PMCd from Param P1 where PTyp= 'PRDSTG'              
    and PNum= IsNull((Select max(P2.PNum) from Txnd TdLoc              
       join Loc on LocCoCd= TdLoc.TdCoCd and LocTyp= 'P' and LocCd= TdLoc.TdByLoc              
       join Param P2 on P2.PTyp= 'PRDSTG' and P2.PMCd= LocPrdStg              
       where ins.TdPrtKey=TdLoc.TdPrtKey and ins.TdBIdNo=TdLoc.TdBIdNo and ins.TdCoCd= TdLoc.TdCoCd and ins.TdBYy= TdLoc.TdBYy              
       and ins.TdBChr= TdLoc.TdBChr and ins.TdBNo= TdLoc.TdBNo              
       and TdLoc.TdSrNo= 0 and TdLoc.TdByLoc<> '' and TdLoc.TdPrdYN= 'Y'              
      ), 0)              
    ), '')              
   from inserted ins where BPrtKey=ins.TdPrtKey and BIdNo=ins.TdBIdNo and BCoCd= ins.TdCoCd and BYy= ins.TdBYy              
    and BChr= ins.TdBChr and BNo= ins.TdBNo              
    and ins.TdSrNo= 0 and ins.TdByLoc<> ''              
  End              
              
  update Bag set              
  BGrWt= BGrWt+ IsNull((Select sum((case (case when ins.TdFrRmLoc='W' then ins.TdFrRmDc              
          when ins.TdToRmLoc='W' then ins.TdToRmDc end)              
          when 'C' then -1 when 'D' then +1 else 0 end)              
   * ins.TdRmWt/ (case when RmCtg in ('D','C') then 5 else 1 end))              
   from inserted ins Join RmMst on RmCd= ins.TdRmCd and RmPrtKey=ins.TdPrtKey              
   where ins.TdPrtKey=BPrtKey and ins.TdBIdNo=BIdNo and ins.TdCoCd= BCoCd and ins.TdBYy= BYy and ins.TdBChr= BChr              
   and ins.TdBNo= BNo and ins.TdRmCd<> ''), 0)              
  from inserted where BPrtKey=inserted.TdPrtKey and BIdNo=inserted.TdBIdNo and BCoCd= inserted.TdCoCd and BYy= inserted.TdBYy              
   and BChr= inserted.TdBChr and BNo= inserted.TdBNo              
   and inserted.TdByy<> '' and inserted.TdBChr<> ''              
   and inserted.TdBNo<> 0 and inserted.TdRmCd<> ''              
 end              
 /****** End OF Bag Updates *******/              
              
 /***** performing fields Valids for wEntTyp= 'TxnBag' ********/              
 /********************************************************/              
 IF @wEntTyp='TxnBag'              
 Begin              
  /*********  Valid Bag,BCls='N' *********/              
  /* Current Partition */              
  Select @Row= Count('x') From Inserted Ins Where Ins.TdPrtKey=@wCurrPrtn and               
   Not Exists (Select 'x' From Bag Where BPrtKey=Ins.TdPrtKey and BIdNo=Ins.TdBIdNo and BCoCd= Ins.TdCoCd and BYy= Ins.TdByy              
     and BChr= Ins.TdBChr and BNo= Ins.TdBNo and BCls= 'N')              
     If @Row>0              
  begin              
   Select @ErrMsg='Invalid Bag No/Bag Is Closed'              
     GoTo ErrHndlr              
  end              
              
  /*******  TdBDc '' or PMcd('DC') *********/              
  /* Current Partition */              
  Select @Row= Count('x') From Inserted Ins Where Ins.TdPrtKey=@wCurrPrtn and              
   Not Exists (Select 'x' From Param where PTyp='DC'              
        and PMCd = Ins.TdBDc and PScd='')              
   and TdBDc<>''              
    If @Row>0              
  Begin              
   Select @ErrMsg='Invalid Bag Dc'              
   GoTo ErrHndlr              
  End              
              
  /*********** TdBGrWt >=0 **********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdBGrWt< 0              
  If @Row>0              
    Begin              
   Select @ErrMsg='Gross Wt cannot be -ve'              
     GoTo ErrHndlr              
    End              
              
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */              
  /********** TdFrBLoc Valid Loc, LocTyp='P' *********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and              
   Not Exists (Select 'x' From Loc where LocCoCd= TdCoCd and              
   LocTyp= 'P' and LocCd = Ins.TdFrBLoc)              
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid Bag Fr Loc'              
     GoTo ErrHndlr              
  END              
              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and              
   (Ins.TdFrBLoc <> ISNULL((SELECT Del.TdFrBLoc FROM Deleted Del WHERE Ins.TdPrtKey=Del.TdPrtKey               
    and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   AND NOT EXISTS (Select 'x' From Loc where LocCoCd= TdCoCd and              
    LocTyp= 'P' and LocCd = Ins.TdFrBLoc AND LocValidYN = 'Y')              
   OR Ins.TdFrBLoc = '')              
   AND @wTcTyp = 'REJ' And TdBDc = 'D'              
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid Bag Fr Loc'              
     GoTo ErrHndlr              
  END              
 /* (Bef 2.06)              
  Select @Row=Count('x') From Inserted Ins Where TdSrNo= 0 and              
   Not Exists (Select 'x' From Loc where LocCoCd= TdCoCd and              
        LocTyp= 'P' and LocCd = Ins.TdFrBLoc)              
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid Bag Fr Loc'              
     GoTo ErrHndlr              
  END              
 */              
/*  #########################################  Manoj  #########################################  */              
              
  /****** From Bag Loc should be equal to the Default Bag Loc of Txn when hOthLocBag = 'N'  ******/              
  /* Current Partition */              
    select @row= count('x') from inserted where @wEntTyp= 'TxnBag' and @wTcTyp              
   in('DT', 'BV', 'MLT') and TdPrtKey=@wCurrPrtn and TdSrNo= 0 and not exists(Select 'x' from Txn where              
    TPrtKey=TdPrtKey and TIdNo=TdTIdNo and TCoCd= TdCoCd and TTc= TdTc and TYy= TdYy and TChr= TdChr and TNo= TdNo and              
   TFrBLoc= (case when TdBDc= 'C' then TdFrBLoc when TdBDc= 'D' then TdToBLoc else TdFrBLoc end))              
   and IsNull((Select hOthLocBag from Head where HCoCd= TdCoCd and HCd= @wHCd), '') = 'N'              
    if @row> 0              
  begin              
      select @errmsg= 'From Bag Loc Should Be Equal To The Default Bag Location'              
   goto ErrHndlr              
    end              
              
  /****** From Bag Loc should be equal to the Default Bag Loc of Txn when hOthLocBag = 'N'  ******/              
  /* **** Zubin 211 **** */              
  /* Current Partition */              
    select @row= count('x') from inserted where @wEntTyp= 'TxnBag' and @wTcTyp               
   in('BS', 'BM') and TdPrtKey=@wCurrPrtn and TdSrNo= 0 and not exists(Select 'x' from Txn where               
    TPrtKey=TdPrtKey and TIdNo=TdTIdNo and TCoCd= TdCoCd and TTc= TdTc and TYy= TdYy and TChr= TdChr               
    and TNo= TdNo and TFrBLoc= TdFrBLoc)               
   and IsNull((Select hOthLocBag from Head where HCoCd= TdCoCd and HCd= @wHCd), '') = 'N'               
    if @row> 0               
  begin               
      select @errmsg= 'From Bag Loc Should Be Equal To The Default Bag Location'               
   goto ErrHndlr               
    end              
  /* **** Zubin 211 **** */              
              
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */              
  /****** TdToBLoc If 'Bv' AND Srno= 0 Then Valid Loc, LocTyp= 'P' Else ''    *********/              
  IF @WTcTyp= 'Bv'              
  BEGIN              
   /* Current Partition */              
   SELECT @Row= COUNT('x') FROM Inserted Ins WHERE TdPrtKey=@wCurrPrtn And (TdSrNo=0 AND              
    ((Ins.TdToBLoc <> ISNULL((SELECT Del.TdToBLoc FROM Deleted Del WHERE Ins.TdPrtKey=Del.TdPrtKey               
     and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
     Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
     Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
    AND              
    NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
      LocTyp= 'P' AND LocCd= Ins.TdToBLoc AND LocValidYN = 'Y'))              
    OR              
    (TdToBLoc = '')))              
   OR              
    (TdSrNo<>0 AND TdToBLoc<> '')              
     IF @Row>0              
   BEGIN              
    SELECT @ErrMsg='Invalid Bag To Loc'              
    GOTO ErrHndlr            
   END              
              
   /* Current Partition */               
   SELECT @row= count('x') FROM inserted Ins WHERE Ins.TdPrtKey=@wCurrPrtn and Ins.TdFrBLoc = Ins.TdToBLoc              
   IF @row>0              
   BEGIN              
    SELECT @errmsg= 'To Bag Loc and From Bag Loc cannot be same'              
    GOTO ErrHndlr              
   END              
  END              
  ELSE              
  BEGIN              
   /* Current Partition */              
   SELECT @Row= COUNT('x') FROM Inserted Ins              
    WHERE TdPrtKey=@wCurrPrtn and TdToBLoc<>''              
     IF @Row>0              
   BEGIN              
    SELECT @ErrMsg='Bag To Loc should be Blank'              
      GOTO ErrHndlr              
   END              
  END              
              
  /******* TdFrRmLoc SrNo<>0 Then Valid Loc, LocTyp<>'P' Else '' ********/              
 /* Current Partition */               
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE TdPrtKey=@wCurrPrtn and (TdSrNo<>0              
   AND NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
    LocTyp<> 'P' AND LocCd= Ins.TdFrRmLoc AND LocValidYN = 'Y'))              
   OR (TdSrNo=0 AND TdFrRmLoc<>'')              
      IF @Row>0              
  BEGIN              
     SELECT @ErrMsg='Invalid From Rm Loc/Rm Loc Should Not Be Entered'              
   GOTO ErrHndlr              
  END             
 /* **** Zubin 211 (Or Condition for 'TdFrRmDc' was missing) **** */              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE Ins.TdPrtKey=@wCurrPrtn and (TdSrNo<>0 AND              
   ((              
   (Ins.TdFrRmLoc <> ISNULL((SELECT Del.TdFrRmLoc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND              
     Ins.TdChr = Del.TdChr AND Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND              
     Ins.TdSrNo = Del.TdSrNo), '')              
   Or              
   Ins.TdFrRmDc <> ISNULL((SELECT Del.TdFrRmDc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND              
     Ins.TdChr = Del.TdChr AND Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND              
     Ins.TdSrNo = Del.TdSrNo), '')              
   )              
   AND TdFrRmDc = 'D'              
   AND NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
    LocTyp<> 'P' AND LocCd= Ins.TdFrRmLoc AND LocValidYN = 'Y')) OR (TdFrRmLoc = '')))              
   OR              
    (TdSrNo=0 AND TdFrRmLoc<>'')              
 /* **** Zubin 211 (Or Condition for 'TdFrRmDc' was missing) **** */              
      IF @Row>0              
  BEGIN              
     SELECT @ErrMsg='Invalid From Rm Loc/Rm Loc Should Not Be Entered'              
   GOTO ErrHndlr              
  END              
/*  #########################################  Manoj  #########################################  */              
              
  /****** TdToBLoc if 'Bv' and Srno= 0 then Valid Loc, LocTyp= 'P' Else ''    *********/              
  /* bef(2.06)              
  if @WTcTyp= 'Bv'              
  Begin              
   Select @Row=Count('x') From Inserted Ins              
   Where (Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
      LocTyp= 'P' and LocCd= Ins.TdToBLoc) and TdSrNo=0)              
    OR              
     (TdSrNo<>0 and TdToBLoc<> '')              
     If @Row>0              
   BEGIN              
    Select @ErrMsg='Invalid Bag To Loc'              
    GoTo ErrHndlr              
   END              
   select @row= count('x') from inserted Ins where Ins.TdFrBLoc = Ins.TdToBLoc              
     if @row>0              
     begin              
       select @errmsg= 'To Bag Loc and From Bag Loc cannot be same'              
       goto ErrHndlr              
     end              
  End              
  Else              
  Begin              
   Select @Row=Count('x') From Inserted Ins              
    Where TdToBLoc<>''              
  If @Row>0              
   BEGIN              
    Select @ErrMsg='Bag To Loc should be Blank'              
      GoTo ErrHndlr              
   END              
  End              
  bef(2.06) */              
              
  /******* TdFrRmLoc SrNo<>0 then Valid Loc, LocTyp<>'P' else '' ********/              
  /* bef(2.06)              
  Select @Row=Count('x') From Inserted Ins              
   Where (Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
    LocTyp<> 'P' and LocCd= Ins.TdFrRmLoc) and TdSrNo<>0)              
   OR              
    (TdSrNo=0 and TdFrRmLoc<>'')              
      If @Row>0              
  BEGIN              
     Select @ErrMsg='Invalid From Rm Loc/Rm Loc Should Not Be Entered'              
   GoTo ErrHndlr              
  END              
  bef(2.06)*/              
               
  /*********TdFrRmDc if 'TxnBag' and SrNo<>0  then Valid 'Dc'  else '' *****/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
     Where TdPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Param where PTyp='DC'              
    and PMCd = Ins.TdFrRmDc and PScd='')              
    and TdSrNo<>0)              
   OR              
    (TdSrNo=0 and TdFrRmDc<>'')              
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid From Rm Ir/Rm Ir Should Not Be Entered'              
     GoTo ErrHndlr              
  END              
              
  /********* TdRmCd if 'TxnBag' and SrNo<>0 then TdRmCd should exist in Od *********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
   Join Bag  On BIdNo=TdBIdNo and BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo and BPrtKey=TdPrtKey              
  Where TdPrtKEy=@wCurrPRtn and (TdSrNo<> 0 and Not Exists (Select 'x' from OrdRm where              
   OrPRtKey=BPrtKey and OrOdIdNo=BOdIdNo and OrCoCd= BCoCd and OrTc=BOdTc and OrYy=BOdYy and OrChr=BOdChr              
   and OrNo=BOdNo and OrSr=BOdSr and OrRmCd= TdRmCd))              
   OR              
   (TdSrNo=0 and TdRmCd<> '')              
    If @Row> 0              
  BEGIN              
   Select @ErrMsg='Rm Code does not exist in Order/Rm Code Should Be Blank'              
   GoTo ErrHndlr              
  END              
              
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */              
  /* **** Zubin 211 **** */ /* ****** Sachin 2.13.0 ValidYN added ****** */              
  /****** TdToRmLoc If 'TxnBag' AND SrNo<> 0 Then Valid Loc, LocTyp<>'P' Else ''              
   If 'Rec', 'Cnv', 'Bs', 'BM' Then LocTyp='Xc' **********/              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE TdPrtKey=@wCurrPrtn and (TdSrNo<>0 AND              
   NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
      LocTyp<> 'P' AND LocCd = Ins.TdToRmLoc AND LocValidYN='Y' And              
       (@wTcTyp NOT IN('Rec','Cnv','Bs', 'BM') OR LocTyp= 'Xc')))              
   OR              
    (TdSrNo=0 AND TdToRmLoc<>'')              
    IF @Row> 0              
  BEGIN              
   SELECT @ErrMsg= 'Invalid To Rm Loc/ To Rm Loc Should Be Blank'              
   GOTO ErrHndlr              
  END              
              
               
  /* **** Zubin 211 (Or Condition for 'TdToRmLoc' was missing) **** */              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE TdPrtKey=@wCurrPrtn and (TdSrNo<>0 AND              
   ((              
   (Ins.TdToRmLoc <> ISNULL((SELECT Del.TdToRmLoc FROM Deleted Del WHERE Ins.TdPrtKey=Del.TdPrtKey               
    and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   Or              
   Ins.TdToRmDc <> ISNULL((SELECT Del.TdToRmDc FROM Deleted Del WHERE Ins.TdPrtKey=Del.TdPrtKey               
    and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   )              
   AND TdToRmDc = 'D'              
   AND NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
      LocTyp<> 'P' AND LocCd = Ins.TdToRmLoc AND LocValidYN = 'Y' AND              
       (@wTcTyp NOT IN('Rec','Cnv','Bs','BM') OR LocTyp= 'Xc'))) OR (TdToRmLoc = '')))              
   OR              
    (TdSrNo=0 AND TdToRmLoc<>'')              
  /* **** Zubin 211 (Or Condition for 'TdToRmLoc' was missing) **** */              
    IF @Row> 0              
  BEGIN              
   SELECT @ErrMsg= 'Invalid To Rm Loc/ To Rm Loc Should Be Blank'              
   GOTO ErrHndlr              
  END              
  /* (bef 2.06)              
  Select @Row=Count('x') From Inserted Ins              
  Where (Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
      LocTyp<> 'P' and LocCd = Ins.TdToRmLoc and              
       (@wTcTyp Not In('Rec','Cnv','Bs') Or LocTyp= 'Xc'))              
   and TdSrNo<>0)              
   OR              
    (TdSrNo=0 and TdToRmLoc<>'')              
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid To Rm Loc/To Rm Loc Should Be Blank'              
   GoTo ErrHndlr              
  END              
  */              
/*  #########################################  Manoj  #########################################  */              
              
  /* Current Partition */              
  select @row= count('x') from inserted Ins where TdPRtKey=@wCurrPrtn and TdSrNo<>0 and              
    Ins.TdFrRmLoc = Ins.TdToRmLoc and (Ins.TdFrRmLoc <> '' or              
    Ins.TdToRmLoc <> '')              
    if @row>0            
    begin              
      select @errmsg= 'To Rm Loc and From Rm Loc cannot be same'              
      goto ErrHndlr              
    end              
              
  /****** if 'TxnBag' and SrNo<> 0 then TdFrRmLoc & TdToRmLoc both should not be of LocTyp= 'W' **********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and  TdSrNo<>0 and Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and LocTyp= 'W' and LocCd = Ins.TdFrRmLoc)              
     and Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and LocTyp= 'W' and LocCd = Ins.TdToRmLoc)              
    If @Row>0              
  begin              
   Select @ErrMsg= 'Both From & To Rm Locs Should Not Be ''W'' '              
   GoTo ErrHndlr              
  end              
              
  /* Bef Rel 1.11              
  **** Rejection entry should  reject all the pieces in the bag *******              
  select @Row=Count('x') from inserted where @wTcTyp= 'REJ' and              
   ( IsNull((Select BQty from Bag where TdBYy= BYy and              
         TdBChr= BChr and TdBNo= BNo), 0)<> 0 or              
    IsNull((Select BPtQty from Bag where TdBYy= BYy and              
         TdBChr= BChr and TdBNo= BNo), 0)<> 0              
   )              
  If @Row > 0              
  begin              
   Select @ErrMsg= 'All the Pieces/ Part Pieces In The Bag Have To Be Rejected'              
   GoTo ErrHndlr              
  end              
  */              
              
  /**** Rejection entry should  reject all the pieces in the bag or dereject all the Pcs In the Bag *******/              
  /* Current Partition */               
  select @Row=Count('x') from inserted where TdPrtKey=@wCurrPrtn and @wTcTyp= 'REJ' and              
   ( IsNull((Select Cast(BQty As Decimal(8,2)) from Bag where TdPrtKey=BPrtKey and TdBIdNo=BIdNo and TdCoCd= BCoCd and              
     TdBYy= BYy and TdBChr= BChr and TdBNo= BNo), 0)<> 0 or              
    IsNull((Select BPtQty from Bag where TdPrtKey=BPrtKey and TdBIdNo=BIdNo and TdCoCd= BCoCd and              
     TdBYy= BYy and TdBChr= BChr and TdBNo= BNo), 0)<> 0              
   ) and              
   ( IsNull((Select Cast(BRjQty As Decimal(8,2)) from Bag where TdPrtKey=BPrtKey and TdBIdNo=BIdNo and TdCoCd= BCoCd and              
     TdBYy= BYy and TdBChr= BChr and TdBNo= BNo), 0)<> 0 or              
    IsNull((Select BRjPtQty from Bag where TdPrtKey=BPrtKey and TdBIdNo=BIdNo and TdCoCd= BCoCd and              
     TdBYy= BYy and TdBChr= BChr and TdBNo= BNo), 0)<> 0              
   )              
  If @Row > 0              
  begin              
   Select @ErrMsg= 'All the Pieces/ Part Pieces In The Bag Have To Be Rejected/ Derejected'              
   GoTo ErrHndlr              
  end              
              
  /****** TdRjDc if 'MLT' and SrNo=0 then 'C'              
   If 'REJ' and SrNo=0 then Opp of TdBDc              
   else ''    *********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and (@wTcTyp='MLT' and TdSrNo=0 and TdRjDc<>'C') Or              
    (@wTcTyp='REJ' and TdSrNo=0 and TdRjDc=TdBDc)              
   Or              
    ((TdSrNo<>0 or @wTctyp Not In('MLT','REJ')) and TdRjDc<>'')              
    If @Row>0             
  BEGIN              
   Select @ErrMsg='Invalid Rej Ir/Rej Ir Should Not Be Entered'              
   GoTo ErrHndlr              
  END              
              
  /******* TdRjCd if 'Rej' and SrNo=0 then Valid('RejCd') else '' *********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Param where PTyp='REJCD'              
    and PMCd = Ins.TdRjCd and PScd='')              
    and @wTcTyp='Rej' and TdSrNo=0)              
   OR              
    ((@wTcTyp<>'REJ' or TdSrNo<>0) and TdRjCd<>'')              
    If @Row> 0              
  BEGIN              
   Select @ErrMsg='Invalid Rej Cd/Rej Cd Should Not Be Entered'              
   GoTo ErrHndlr              
  END              
              
  /******* TdWrk If 'TxnBag' AND SrNo=0 Then PMcd('Work') Else '' **********/              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE TdPrtKey=@wCurrPrtn and (TdSrNo=0 AND              
   ((Ins.TdWrk <> ISNULL((SELECT Del.TdWrk FROM Deleted Del WHERE Ins.TdPrtKey=Del.TdPrtKey               
    and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   AND              
   NOT EXISTS (SELECT 'x' FROM vParam WHERE vPCoCd = TdCoCd              
    AND vPTyp='WORK' AND vPMCd = Ins.TdWrk AND vPValidYN = 'Y') OR TdWrk = '')))              
   OR              
   (TdSrNo<>0 AND TdWrk<>'')              
      IF @Row>0              
  BEGIN              
   SELECT @ErrMsg='Invalid Wrk/Worker Should Not Be Entered'              
   GOTO ErrHndlr              
  END              
              
  /******* TdAck if 'Bv' then 'YN' else '' **********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
     Where TdPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Param where PTyp='YN'              
    and PMCd = Ins.TdAck and PScd='')              
   and  @wTcTyp='Bv')              
   OR              
   (@wTcTyp<>'Bv' and TdAck<>'')              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid Bag Movement Ack/Ack Should Not Be Entered'              
     GoTo ErrHndlr              
  END              
              
  /******* TdPrdYN if 'Dt', 'SP' and SrNo=0 then 'YN' else '' *******/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
  Where TdPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Param where PTyp='YN'              
       and PMCd = Ins.TdPrdYN and PScd='')              
   and  @wTcTyp In('Dt') and TdSrNo=0)              
   OR              
 (@wTcTyp Not In('Dt') and TdPrdYN<> '')              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid Prd YN/Prd YN Should Not Be Entered'              
     GoTo ErrHndlr              
  END              
              
  /******** TdByLoc '' Or Valid Loc, LocTyp='P'  (filled for Brk, Msg, Loss, Prd) *********/              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE TdPrtKey=@wCurrPrtn and              
   Ins.TdByLoc <> ISNULL((SELECT Del.TdByLoc FROM Deleted Del WHERE Ins.TdPrtKey=Del.TdPrtKey               
     and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   AND              
   NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
     LocTyp= 'P' AND LocCd = Ins.TdByLoc AND LocValidYN = 'Y')              
   AND TdByLoc <> ''              
    IF @Row> 0              
  BEGIN              
   SELECT @ErrMsg= 'Invalid By Loc'              
     GOTO ErrHndlr              
  END              
              
  /******** TdByWrk '' Or Valid 'Work'  (filled for Brk, Msg, Loss, Prd) **********/              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE TdPrtKey=@wCurrPrtn and               
   Ins.TdByWrk <> ISNULL((SELECT Del.TdByWrk FROM Deleted Del WHERE Ins.TdPrtKey=Del.TdPrtKey               
    and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   AND              
     NOT EXISTS (SELECT 'x' FROM vParam WHERE vPCoCd = TdCoCd              
     AND vPTyp='WORK' AND vPMCd = Ins.TdByWrk AND vPValidYN = 'Y')              
   AND TdByWrk<>''              
      IF @Row>0              
  BEGIN              
   SELECT @ErrMsg='Invalid By Work'              
     GOTO ErrHndlr              
  END              
              
  /******** TdByLoc Valid Loc, LocTyp= 'P'  and TdByWrk Valid Wrk (for Brk, Msg, Loss, Prd) *********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
     Where TdPrtKey=@wCurrPrtn and (TdPrdYN= 'Y' and (TdByLoc= '' or TdByWrk= '')) or              
               (IsNull( (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
     LocTyp in ('L', 'B', 'M')  and LocCd = TdToRmLoc), '')<> '' and (TdByLoc= '' or TdByWrk= '')              
    )              
    If @Row>0              
  BEGIN              
   Select @ErrMsg='By Loc/ Wrk Should Be Entered'              
     GoTo ErrHndlr              
  END              
              
  /******* TdRefYy if 'Bs' and SrNo=0 and TdBDc='C' then              
    Valid TdYy in Vchr,SrNo=0,TdBdc= 'D'              
    Else ''              
  TdRefKey  -- do -- **********/              
              
  /******* check of parent bag for child bag is done prev *******/              
  /*** (Bef 2.13)              
  Select @Row=Count('x') from inserted Ins where              
   (@wTcTyp<>'Bs' or TdSrNo<> 0 or TdBDc<> 'D') and              
   (TdRefYy<> '' or TdRefKey<> 0)              
  (Bef 2.13) ***/              
  /*** (Jen 2.13) ***/              
              
  /* Current Partition */              
  Select @Row= Count('x') from inserted Ins       
  Join Txn On TPrtKey=Ins.TdPRtKey and TIdNo=Ins.TdTIdNo and TCoCd=Ins.TdCoCd and TTc=Ins.TdTc and TYy=Ins.TdYy and              
     TChr=Ins.TdChr and TNo=Ins.TdNo      
  where TdPrtKey=@wCurrPrtn and              
   (@wTcTyp not in ('BS', 'BM') or TdSrNo<> 0 or (((TMultIIr<>'I' and TdBDc<> 'D') or (TMultIIr='I' and TdBDc<> 'C')) and @wTcTyp<> 'BM') ) and               
   (TdRefYy<> '' or TdRefKey<> 0)               
  /*** (Jen 2.13) ***/              
      If @Row > 0               
       Begin              
   Select @ErrMsg='Ref Yy && Ref Key should be blank'              
     GoTo ErrHndlr              
    end              
      
/***** Bef 3.8.0 *****/      
/*  Select @Row= Count('x') from inserted Ins where TdPrtKey=@wCurrPrtn and              
   (@wTcTyp not in ('BS', 'BM') or TdSrNo<> 0 or (TdBDc<> 'D' and @wTcTyp<> 'BM') ) and               
   (TdRefYy<> '' or TdRefKey<> 0)               
  /*** (Jen 2.13) ***/              
      If @Row > 0               
       Begin              
   Select @ErrMsg='Ref Yy && Ref Key should be blank'              
     GoTo ErrHndlr              
    end      */        
              
  /******* TdPrevYy              
  TdPrevKey              
   if 'TxnBag' and SrNo=0 then Valid TdYy+TdKey of Txnd else '' *******/              
              
  /* Current Partition */              
  Select @Row=Count('x') from inserted Ins where TdPrtKey=@wCurrPrtn and              
   (Not Exists (Select 'x' from Txnd  where Txnd.TdPrtKey=Ins.TdPrtKey and Txnd.TdBIdNo=Ins.TdBIdNo and Txnd.TdCoCd=Ins.TdCoCd and              
    Txnd.TdBYy=Ins.TdBYy and Txnd.TdBChr=Ins.TdBChr and Txnd.TdBNo=Ins.TdBNo              
    and Txnd.TdYy=Ins.TdPrevYy and Txnd.TdKey=Ins.TdPrevKey)              
   and TdSrno=0)              
   and              
   (TdPrevYy<>'' or TdPrevKey<>0)              
    If @Row > 0              
     Begin              
   Select @ErrMsg='Invalid Prev YY/Key'              
   GoTo ErrHndlr              
  end              
              
  /********  BQty >= 0 *************/              
  if @mode in ('A','C')              
  begin              
   /* Current Partition */              
   Select @Row=Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and              
    Exists (Select 'x' From Bag Where BPrtKey=Ins.TdPrtKey and BIdNo=Ins.TdBIdNo and BCoCd= Ins.TdCoCd and              
     BYy= Ins.TdByy and BChr= Ins.TdBChr and BNo= Ins.TdBNo and Cast(BQty as Decimal(8,2))< 0)              
     If @Row>0              
   begin              
    Select @ErrMsg='Cannot accept Txn, Bag Qty going -ve'              
    GoTo ErrHndlr              
   end              
  end              
              
  if @Mode='D'              
  Begin              
   /* Current Partition */              
   Select @Row=Count('x') From Deleted Del Where Del.TdPRtKey=@wCurrPrtn and               
    Exists (Select 'x' From Bag Where BPrtKey=Del.TdPrtKey and BIdNo=Del.TdBIdNo and BCoCd= Del.TdCoCd              
         and BYy= Del.TdByy and BChr= Del.TdBChr              
         and BNo = Del.TdBNo and Cast(BQty as Decimal(8,2))< 0)              
     If @Row>0              
     begin              
    Select @ErrMsg='Cannot accept Txn, Bag Qty going -ve'              
    GoTo ErrHndlr              
   end              
         End              
              
  /* temporary by rn for transfer to complete */              
  /********* Total of BQty for The Order Sr. <=OdPrdQty ********/              
  /* **** Zubin 211 **** */              
/*  Select @Row=Count('x') From Inserted Ins              
   Join Bag B1 on BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo              
   Join OrdDsg on OdCoCd= BCoCd and OdTc= BOdTc and OdYy= BOdYy              
    and OdChr= BOdChr and OdNo= BOdNo and OdSr= BOdSr              
   Where (Select sum(BQty) from Bag B2 where B2.BCoCd= B1.BCoCd              
    and B2.BOdTc= B1.BOdTc and B2.BOdYy= B1.BOdYy              
    and B2.BOdChr= B1.BOdChr and B2.BOdNo= B1.BOdNo              
    and B2.BOdSr= B1.BOdSr)              
   > OdPrdQty */              
  /****** (Jay 2.13 CT changed the 'BCHR' condition) ******/              
  /* Current Partition - CHECK */
/* CHECK BELOW IS COMMENTED DUE TO SPEED ISSUES - INSTRUCTION BY RN */              
