     Exists (Select 'x' from Txnd Td where Td.TdPrtKey=Del.TdPrtKey and              
      Td.TdTIdNo=Del.TdTIdNo and Td.TdCoCd= Del.TdCoCd and Td.TdTc= Del.TdTc and               
      Td.TdYy= Del.TdYy and Td.TdChr= Del.TdChr and               
