       and convert (decimal (16, 3), ins.InHPdFiness)= convert (decimal (16, 3), del.InHPdFiness)     
       and ins.InFobPer= del.InFobPer and ins.InRemakingCtgs= del.InRemakingCtgs     
       and ins.InInvGrsWtEqActual= del.InInvGrsWtEqActual     
       )     
     /*** (Jen 2.13) 28/11/06 ***/    
    
     /* (Bef 2.13)    
