ALTER TRIGGER [dbo].[PrdPts_INUPDL] ON [dbo].[PrdPts]
 FOR INSERT,UPDATE,DELETE
AS
BEGIN
 	DECLARE @ROW INT
 	DECLARE @mode char(1)
 	DECLARE @errmsg varchar(255)
	Declare @ReplAgt BIT

 	IF @@ROWCOUNT=0
  	RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'PrdPts' )
		RETURN

	select @mode=case (select count('x') from inserted) when 0 then 'D'
       		           else
   			  case (select count('x') from deleted) when 0 then 'A' else 'C' end
       		           end

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	If  (@ReplAgt<>1)
	Begin

		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

 	/******** Records Of Only One Typ Can Be Inserted At A Time ********/
	select @Row= Count(distinct(PpTyp)) from inserted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Prd Pts Records Of Only One Type Can Be Acted On At A Time'
		GoTo ErrHndlr
	End

	/******** Records Of Only One Typ Can Be Deleted At A Time ********/
	select @Row= Count(distinct(PpTyp)) from deleted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Prd Pts Records Of Only One Type Can Be Acted On At A Time'
		GoTo ErrHndlr
	End

	/******** Prd Typ Not Defined ********/
    --3.11.0
	select @row= count('x') from inserted where PpTyp<>'BL' And
		     not exists (select 'x' from Param where PTyp= 'PRDTYP' and PMCd =PpTyp)
 	if @row> 0
 	Begin
  		select @errmsg= 'Prd Type Not Defined'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpPrdCtg= valid PMCd('PRDCTG')  ******/
	select @row= count('x') from inserted where PpTyp<>'BL' And PpPrdCtg<> '' and 
  		not exists (select 'x' from Param where PTyp= 'PRDCTG' and PMCd= PpPrdCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Production Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpTyp='BL' And PpPrdCtg= valid PMCd('DMCTG')  ******/
	select @row= count('x') from inserted where PpTyp='BL' And PpPrdCtg<> '' and 
  		not exists (select 'x' from Param where PTyp= 'DMCTG' and PMCd= PpPrdCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpPrdCtg') = 'N' then PpPrdCtg = Not Blank ******/
	select @row= count('x') from inserted where PpPrdCtg= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		    and TsIdName= 'PpPrdCtg') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Production Category Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpSetTyp= valid PSCd('LABSCD', 'SET')  ******/
	select @row= count('x') from inserted where PpSetTyp<> '' and 
  		not exists (select 'x' from Param where PTyp= 'LABSCD' and PMCd= 'SET' and PSCd= PpSetTyp)
 	if @row> 0
 	Begin
  		select @errmsg= 'Setting Type Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpSetTyp') = 'N' then PpSetTyp = Not Blank ******/
	select @row= count('x') from inserted where PpSetTyp= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		and TsIdName= 'PpSetTyp') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Setting Type Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpDmCd= valid DmCd('DM')  ******/
	select @row= count('x') from inserted where PpDmCd<> '' and 
  		not exists (select 'x' from DsgMst where DmTcTyp= 'DM' and DmCd= PpDmCd and DmSz= ''
						 and ((Case When PpTyp='BL' Then DmCtg Else DmPrdCtg End)= PpPrdCtg or 
						 PpTyp='GS' or PpTyp = 'WS'))
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Code Not Defined/ Ctg Not Matching'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpDmCd') = 'N' then PpDmCd = Not Blank ******/
	select @row= count('x') from inserted where PpDmCd= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		and TsIdName= 'PpDmCd') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Code Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If not Blank then PpLoc= valid Loc(LocTyp= 'P')  ******/
	select @row= count('x') from inserted where PpLoc<> '' and 
	  		not exists (select 'x' from Loc where LocTyp= 'P' and LocCd= PpLoc)
 	if @row> 0
 	Begin
  		select @errmsg= 'Process Location Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpLoc') = 'N' then PpLoc = Not Blank ******/
	select @row= count('x') from inserted where PpLoc= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
		and TsIdName= 'PpLoc') = 'N'
 	if @row> 0
 	Begin
		select @errmsg= 'Process Location Cannot Be Blank'
		goto ErrHndlr
 	end

	/******  If not Blank then PpSubPrc= valid PSCd('SUBPRC', PpLoc)  ******/
	select @row= count('x') from inserted where PpSubPrc<> '' and 
  		not exists (select 'x' from Param where PTyp= 'SUBPRC' and PMCd= PpLoc and PSCd= PpSubPrc)
 	if @row> 0
 	Begin
  		select @errmsg= 'Sub Process Not Defined For The Process Location'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpSubPrc') = 'N' then PpSubPrc = Not Blank ******/
	select @row= count('x') from inserted where PpSubPrc= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		and TsIdName= 'PpSubPrc') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Sub Process Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpPts') = 'N' then PpPts = Not Blank ******/
	select @row= count('x') from inserted where PpPts= 0 and 
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= '' 
   		and TsIdName= 'PpPts') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Production Points Should Be Greater Than Zero'
  		goto ErrHndlr
 	end

/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
/*	Date: 03/12/2003																			 */
/*	Cnange:	Check Adeed For fields RmCtg & RmSCtg  (New Added in Table PrdPts)					 */

	/******  If not Blank then PpRmCtg= valid Rm Category (PTyp= 'RMCTG')  ******/
	select @row= count('x') from inserted where PpRmCtg<> '' and
	  		not exists (select 'x' from Param where PTyp= 'RMCTG' and PMCd= PpRmCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Rm Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpRmCtg') = 'N' then PpRmCtg = Not Blank ******/
	select @row= count('x') from inserted where PpRmCtg= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= ''
		and TsIdName= 'PpRmCtg') = 'N'
 	if @row> 0
 	Begin
		select @errmsg= 'Rm Category Cannot Be Blank'
		goto ErrHndlr
 	end

	/******  If not Blank then PpRmCtg= valid Rm Category (PTyp= 'RMCTG')  ******/
	select @row= count('x') from inserted where PpRmSCtg<> '' and
	  		not exists (select 'x' from Param where PTyp= 'RMSCTG' and PMCd= PpRmCtg And PSCD = PpRmSCtg )
 	if @row> 0
 	Begin
  		select @errmsg= 'Rm Sub Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'PrdPts', TsTyp= PpTyp, TsSTyp= '', TsIdName= 'PpRmCtg') = 'N' then PpRmCtg = Not Blank ******/
	select @row= count('x') from inserted where PpRmSCtg= '' and
  		(Select TsBlank from TcStr where TsTbl= 'PrdPts' and TsTyp= PpTyp and TsSTyp= ''
		and TsIdName= 'PpRmSCtg') = 'N'
 	if @row> 0
 	Begin
		select @errmsg= 'Rm Sub Category Cannot Be Blank'
		goto ErrHndlr
 	end

	Select @row = Count('x') From Inserted ins 
	Where  
	(Select count('x') From PrdPts Pp
		Where Pp.PpTyp=Ins.PpTyp And Pp.PpLoc=Ins.PpLoc And Pp.PpSubPrc=Ins.PpSubPrc And Pp.PpPrdCtg=Ins.PpPrdCtg
			And Pp.PpSetTyp=Ins.PpSetTyp And Pp.PpDmCd=Ins.PpDmCd And Pp.PpRmCtg=Ins.PpRmCtg And Pp.PpRmSCtg=Ins.PpRmSCtg 
   			and  (    (Pp.PpFrRmWt<= ins.PpFrRmWt and
      				 Pp.PpToRmWt>= ins.PpFrRmWt)
			    or  	(Pp.PpFrRmWt<= ins.PpToRmWt and
			      	 Pp.PpToRmWt>= ins.PpToRmWt)
    			    or  	(ins.PpFrRmWt<= Pp.PpFrRmWt and
				 ins.PpToRmWt>= Pp.PpToRmWt) 	 )) > 1
	if @row> 0
 	Begin
  		select @errmsg= 'Weight Range Already Defined'
  		goto ErrHndlr
 	End  

/*  #################################  Manoj #### Ver: 2.0.6  #################################  */

Return
ErrHndlr:
	Begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	end
end

GOGO

update TcStr set TsStyle = 'N', TsLbl = 'Design Cd ' where TsTbl='prdpts' and TsTyp='GS' and TsIdName='ppdmcd'
update TcStr set TsStyle = 'N', TsLbl = 'Design Cd ' where TsTbl='prdpts' and TsTyp='WS' and TsIdName='ppdmcd'


GOGO

ALTER TRIGGER [dbo].[vParam_INUPDL] ON [dbo].[vParam] 
   For INSERT,UPDATE,DELETE
As
BEGIN
 /* Trigger Version 2.14.0 [Original] */	
 DECLARE @ROW INT
 DECLARE @mode char(1)
 DECLARE @errmsg varchar(255)
 DECLARE @vPTyp varchar(8)
 DECLARE @wHCd VARCHAR(8)
 DECLARE @wSelfCoCd VARCHAR(3)
 DECLARE @ReplAgt BIT  
	
 IF @@ROWCOUNT=0   RETURN

 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'vParam' )
  RETURN

 select @mode=case (select count('x') from inserted) when 0 then 'D'
       else
   case (select count('x') from deleted) when 0 then 'A' else 'C' end
       end

	set @wHCd = 'ZSELF'	
	set @wSelfCoCd= 'ZZZ'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Records Of Only One vPTyp Can Be Inserted At A Time ********/ 
	select @Row= Count(distinct(vPTyp)) from inserted 
	If @Row > 1
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One vPTyp Can Be Deleted At A Time ********/ 
	select @Row= Count(distinct(vPTyp)) from deleted 
	If @Row > 1 
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/*** Storing PTyp In The Variable @PTyp ***/
	select @vPTyp= case  when @mode in ('C', 'A') then (Select max(vPTyp) from inserted)  else (Select max(vPTyp) from deleted) end  

	/******** If The Parameter Is A System Parameter Then No Add, Change Or Delete Allowed For The Param Entry *********/
	select @Row=Count('x') from vParam vPm where (@vPTyp= 'PTYP') or 
		(vPm.vPTyp= 'PTYP' and vPm.vPMCd= @vPTyp and vPm.vPValue= 'M')
	If @Row > 0
	begin 
		Select @ErrMsg='Cannot Add/Change/Delete Microway Parameter - '+ @vPTyp
		GoTo ErrHndlr
	end		

 	/******** Key Cannot Be Changed  (i.e.vPCoCd, vPTyp, vPMCd and vPSCd cannot be changed) ********/ 
 	If @mode = 'C'
 	Begin
  		select @Row=Count('x') from deleted del where
    		not exists (Select 'x' from inserted ins where ins.vPCoCd= del.vPCoCd and 
			ins.vPTyp= del.vPTyp and ins.vPMCd= del.vPmCd and ins.vPSCd= del.vPSCd)
  		If @Row > 0
	  	begin 
			Select @ErrMsg='Cannot Change Variable Param Key'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	BEGIN
		/*** Only a valid vPTyp can be entered (i.e. a valid vPMCd from Param where vPTyp= 'vPTYP') ***/
		select @row= count('x') from inserted ins where ins.vPTyp<> 'PTYP' and 
		not exists (select 'x' from vParam Prm where Prm.vPCoCd= @wSelfCoCd and 
					Prm.vPTyp= 'PTYP' and Prm.vPMCd= ins.vPTyp)
		if @row> 0 
		begin
			select @errmsg= 'Variable Parameter Type Not Defined'
			goto ErrHndlr
		end

		/****** vPCoCd= valid HCoCd ******/
		select @row= count('x') from inserted ins where not exists
			 (select 'x' from Head where HCoCd= vPCoCd and HCd= @wHCd)
		if @row>0 
		begin
			select @errmsg= 'Company Code Not Defined'
			goto ErrHndlr
		end

		/*** Only a valid vPTyp can be entered (i.e. a valid vPMCd from Param where vPTyp= 'vPTYP') ***/
		select @row= count('x') from inserted ins where ins.vPTyp= 'PTYP' and 
			ins.vPCoCd<> @wSelfCoCd 
		if @row> 0 
		begin
			select @errmsg= 'For PTyp= ''PTYP'', the Company Code should Be '+@wSelfCoCd
			goto ErrHndlr
		end

		/*** vPMCd cannot be Blank ***/
		select @row=count('x') from inserted where vPMCd= ''
		if @row>0 
		begin
	   		select @errmsg='Main Code Cannot Be Blank'
   			goto ErrHndlr
  		end
		/*** vPDesc cannot be blank ***/
		/* ******* Geeta CRM 2.12 ******** */
		select @row=count('x') from inserted where vPDesc= '' and vPTyp<>'CRMWIW'
		if @row>0 
		begin
			select @errmsg='Description Cannot Be Blank'
			goto ErrHndlr
  		end

		if @vPTyp= 'CHR' 
		Begin 
			/****** vPMCd= valid Tc ******/
			select @row= count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'TC' 
			      			and Prm.PMCd= ins.vPMCd)
			if @row> 0 
			begin
				select @errmsg= 'Tc Not Defined'
				goto ErrHndlr
			end
			/****** vPSCd= Not Blank ******/
			select @row= count('x') from inserted where vPSCd= ''
			if @row>0 
			begin
				select @errmsg= 'Character Code Cannot Be Blank'
				goto ErrHndlr
			end
			/****************Geeta**Crm*2.12************************************/
			select @row= count('x') from inserted ins where vPSCd='WEB' and 
				(Not Exists(Select 'x' From SysDb where SysId='CRM') Or 
				Not Exists (Select 'x' From Param 
					where PTyp='TC' and PMCd=vPMCd  and PValue in ('SO','QT','QS','MF')))
			if @row>0 
			begin
				select @errmsg= 'WEB Chr can be Used Only for ''SO'',''QS'',''QT'',''MF'' in CRM Database  '
				goto ErrHndlr
			end
			/****Geeta*****Crm**************/  
			select @row= count('x') from inserted ins where vPCoCd='WEB' and  vPSCd<>'WEB'	
			if @row>0   
			begin  
				select @errmsg= 'Character Other than ''WEB'' cannot be defined for CoCd=''WEB''  '  
				goto ErrHndlr  
			end  
			/****** vPValue= Valid Raw Material Loc ******/
			select @row= count('x') from inserted where vPValue<>'' and 
				not exists (select 'x' from Loc where LocCoCd = vPCoCd 
					and LocTyp<> 'P' and LocCd= vPValue)
			if @row>0 
			begin
				select @errmsg= 'Default From Raw Material Location Not Defined'
				goto ErrHndlr
			end
			/****** vPNum= 0 ******/
			select @row= count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** vPDesc225= Valid Raw Material Loc ******/
			select @row= count('x') from inserted where vPDesc225<> '' and 
				not exists (select 'x' from Loc where LocCoCd= vPCoCd 
						and LocTyp<> 'P' and LocCd= vPDesc225)
			if @row>0 
			begin
				select @errmsg= 'Default To Raw Material Location Not Defined'
				goto ErrHndlr
			end
			/****** vPValue1= Valid Bag Loc ****** Bhavna removed check for tc FB as multiple locns in FB*/
			select @row= count('x') from inserted where vPValue1<> '' and vPMCd <> 'FB' and  
				not exists (select 'x' from Loc where LocCoCd= vPCoCd 
						and LocTyp= 'P' and LocCd= vPValue1)
			if @row>0 
			begin
				select @errmsg= 'Default Bag Location Not Defined'
				goto ErrHndlr
			end
			/****** vPNum1= 0 ******/
			select @row= count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2= 'D' or 'C' (Raw Material Debit Or Credit) ******/
			select @row= count('x') from inserted ins where ins.vPValue2<> '' and 
					not exists (select 'x' from Param Prm where Prm.PTyp= 'DC' 
        						and Prm.PMCd= ins.vPValue2)
			if @row>0 
			begin
				select @errmsg= 'Default Raw Material Debit / Credit Not Defined'
				goto ErrHndlr
			end

			/****** vPValue3 = Y/N ******/
			select @row=count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'YN' 
					    and Prm.PMCd= ins.vPValue3)

			if @row>0 
			begin
				select @errmsg= 'TrialChr Should Be Y/N'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> 'Y' and vPValidYn <> 'N' and vPValidYn <> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Y/N'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
		End


		if @vPTyp= 'DEFCHR' 
		Begin 
			/****** vPMCd= valid Tc ******/
			select @row= count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'TC' 
			      			and Prm.PMCd= ins.vPMCd)
			if @row>0 
			begin
				select @errmsg= 'Tc Not Defined'
				goto ErrHndlr
			end
			/****** vPSCd = Blank ******/
			select @row=count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end

			/****** vPValue= Valid vPSCd ('CHR') ******/
			select @row= count('x') from inserted ins where vPValue<> '' and 
				not exists (select 'x' from vParam Prm where 
						Prm.vPCoCd= ins.vPCoCd and Prm.vPTyp= 'CHR' 
						and Prm.vPMCd= ins.vPMCd 
						and Prm.vPSCd= ins.vPValue and Prm.vPValidYn <> 'N')
			if @row> 0 
			begin
				select @errmsg= 'Default Character Not Defined'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
			/*********Geeta*******Emr207************/
			/****** vPValalue4 = Blank ******/
			select @row= count('x') from inserted where vPValue4<> ''
			if @row>0
			begin
				select @errmsg= 'vPValue4 Should Be Blank'
				goto ErrHndlr
			end
			/*********Geeta*******Emr207************/

		End

/****************** urmi FgSubLoc 10/8/03 *************************************************/
		if @vPTyp = 'FGSUBLOC' 
		Begin 
			/****** vPSCd = Blank ******/
			select @row= count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue = Blank ******/
			select @row= count('x') from inserted ins where vPValue<> '' 
			if @row> 0 
			begin
				select @errmsg= 'vPValue Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum = 0 ******/
			select @row=count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** vPDesc225 = Blank ******/
			select @row=count('x') from inserted where vPDesc225<> ''
			if @row>0 
			begin
				select @errmsg= 'vPDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue1 = Blank ******/
			select @row=count('x') from inserted where vPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum1 = 0 ******/
			select @row=count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2 = Blank ******/
			select @row=count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue3 = Blank ******/
			select @row=count('x') from inserted where vPValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue3 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
