 	end

	/* *** Jay 3.01 *** [NAS NOT Included]*/ 
	/******  RrCmCd  =  valid CmCd from CustMst (CmCtg= RrCmCtg)  ******/
	select @row= count('x') from inserted where RrTcTyp not in ('NAS') and 
  		not exists (select 'x' from CustMst where CmCtg= RrCmCtg and CmCd= RrCmCd)
