 	end

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrDmCtg') = 'N' 	then 	RrDmCtg  =  Not Blank  ******/
	select @row= count('x') from inserted where RrDmCtg= '' and
