	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrLsCtg') = 'N' 	then 	RrLsCtg  =  Not Blank  ******/
	select @row= count('x') from inserted where RrLsCtg= '' and
