    select @Row=Count('x') from Deleted Del where Del.TdPrtKey=@wCurrPrtn and              
     Exists (Select 'x' from Txnd  where Txnd.TdPRtKEy=Del.TdPrtKey and              
      Txnd.TdTIdNo=Del.TdTIdNo and Txnd.TdCoCd= Del.TdCoCd and Txnd.TdTc= Del.TdTc and              
      Txnd.TdYy= Del.TdYy and Txnd.TdChr= Del.TdChr and              
      Txnd.TdNo= Del.TdNo and Txnd.TdBDc= 'D' and TdSrNo= 0              
             )              
           and TdBDc= 'C' and TdSrNo= 0              
    If @Row > 0              
         begin              
       Select @ErrMsg='Cannot Delete Parent, Child Exists'              
       GoTo ErrHndlr              
         end              
              
   end              
              
  End              
              
              
/* **** Zubin 211 **** */ /* **** Zubin 211 **** */ /* **** Zubin 211 **** */ /* **** Zubin 211 **** */              
  If @wTcTyp= 'BM'              
  Begin              
   /*******  TdBDc = PMCd('DC') *********/              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and              
    Not Exists (Select 'x' From Param where PTyp= 'DC' and PMCd = Ins.TdBDc and PSCd= '')              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Invalid Bag DC'              
    GoTo ErrHndlr              
   end              
              
   /* 'Primary' bag will always be Receiving Bag */              
   /****** (Jay 2.13 CT) where clause changed for 'BCHR' ******/              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPrtkey=@wCurrPrtn and TdSrNo= 0 and              
    Exists (Select 'x' from Param where PTyp= 'BCHR' and PMCd= TdBChr and PSCd= '' and              
     PValue= 'P') and TdBDc= 'C'              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Primary Bag Will Always Be The Receiving Bag'              
    GoTo ErrHndlr              
   end              
              
   /****** (Jen 2.13 CT) where clause changed for 'BCHR' ******/              
   /* 'Sec' Bag will always be Issuing bag */              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPRtKey=@wCurrPrtn and TdSrNo= 0 and              
    Exists (Select 'x' from Param where PTyp= 'BCHR' and PMCd= TdBChr and PSCd= '' and              
     PValue in ('C', 'F')) and TdBDc= 'D'              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Flute/ Component Bag Will Always Be The Issuing Bag'              
    GoTo ErrHndlr            
   end              
              
   /* issuing Bag character will always be same */              
   /*** (Bef 2.13)               
   Select @Row= Count('x') From Inserted Ins Where ins.TdSrNo= 0 and ins.TdBDc= 'C' and              
