   /* if flute bag then BQty >= 0 */              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and TdBDc= 'C' and TdBQty< 0              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Flute Bag Quantity Should Be >= 0 '              
