    (select count('x') from Txnd Td where Td.TdCoCd= ins.TdCoCd and              
     Td.TdTc= ins.TdTc and Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and              
     Td.TdNo= ins.TdNo and Td.TdSrNo= 0 and Td.TdBDc= 'C')> 1 and              
    (select count('x') from Txnd Td where Td.TdCoCd= ins.TdCoCd and              
     Td.TdTc= ins.TdTc and Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and              
     Td.TdNo= ins.TdNo and Td.TdSrNo= 0 and Td.TdBDc= 'D')> 1              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Cannot Have Multiple Flute Bags When Multiple Primary Bags Exist'              
      GoTo ErrHndlr              
