    (select count('x') from Txnd Td where Td.TdCoCd= ins.TdCoCd and              
     Td.TdTc= ins.TdTc and Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and              
     Td.TdNo= ins.TdNo and Td.TdSrNo= 0 and Td.TdBDc= 'D')> 1 and              
    (select count('x') from Txnd Td where Td.TdCoCd= ins.TdCoCd and              
     Td.TdTc= ins.TdTc and Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and              
     Td.TdNo= ins.TdNo and Td.TdSrNo= 0 and Td.TdBDc= 'C')> 1              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Cannot Have Multiple Primary Bags When Multiple Flute Bags Exist'              
      GoTo ErrHndlr              
        end              
*/              
/* **** Not required **** */              
              
   /*** (Bef 2.13)              
   --*** Cannot have sec. bags after a primary bag ***              
        select @Row= Count('x') from inserted Ins where ins.TdSrNo= 0 and TdBDc= 'C' and              
    Exists (Select 'x' from Txnd Td where Td.TdCoCd= ins.TdCoCd and              
      Td.TdTc= ins.TdTc and Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and              
      Td.TdNo= ins.TdNo and Td.TdSrNo= 0 and Td.TdBDc= 'D' and              
      Td.TdSr< ins.TdSr)              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Cannot Have Another Issuing Bag After Having A Receiving Bag In This Transaction'              
      GoTo ErrHndlr              
        end              
              
   --*** Cannot have receiving bag before a flute bag ***              
        select @Row= Count('x') from inserted Ins where ins.TdSrNo= 0 and TdBDc= 'D' and              
    Exists (Select 'x' from Txnd Td where Td.TdCoCd= ins.TdCoCd and              
      Td.TdTc= ins.TdTc and Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and              
      Td.TdNo= ins.TdNo and Td.TdSrNo= 0 and Td.TdBDc= 'C' and              
      Td.TdSr> ins.TdSr)              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Cannot Have Another Receiving Bag Before Having An Issuing Bag In This Transaction'              
      GoTo ErrHndlr              
        end              
   (Bef 2.13) ***/              
              
              
   /* Qty of recv. bags cannot be changed while adding rec */              
    /* Current Partition */              
        select @errmsg= TdBQty from inserted where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and TdBDc= 'D' and              
    Not Exists (Select 'x' from Bag where BPrtKey=TdPrtKey and BIdNo=TdBIdNo and BCoCd= TdCoCd and BYy= TdBYy and              
     BChr= TdBChr and BNo= TdBNo and              
    convert(decimal(16, 1), TdBQty)= convert(decimal(16, 1), BQty))              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Cannot Change Quantity Of Receiving Bag'              
      GoTo ErrHndlr              
        end              
/* CHECK THIS LATER */              
   /* Part Qty cannot be changed while adding rec */              
