     Not Exists (Select 'x' from deleted del where ins.TdCoCd= del.TdCoCd and              
      ins.TdTc= del.TdTc and ins.TdYy= del.TdYy and ins.TdChr= del.TdChr and              
      ins.TdNo= del.TdNo and ins.TdSr= del.TdSr and ins.TdPtQty = del.TdPtQty)              
     If @Row> 0              
         Begin              
     Select @ErrMsg= 'Cannot Change Part Quantity'              
       GoTo ErrHndlr              
         end              
   End              
*/              
/* **** Not required **** */              
   /* Issuing Qty shld be <= receiving Qty of all receiving bags */              
/*        select @Row= Count('x') from inserted Ins              
    Join Txnd Td On Td.TdCoCd= ins.TdCoCd and Td.TdTc= ins.TdTc and              
     Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and Td.TdNo= ins.TdNo and              
     Td.TdSrNo= 0 and Td.TdBDc= (case when ins.TdBDc= 'D' then 'C'              
       when ins.TdBDc= 'C' then 'D' end)              
     and (case when ins.TdBDc= 'D' then ins.TdBQty              
       when ins.TdBDc= 'C' then Td.TdBQty end)<              
      (case when ins.TdBDc= 'D' then Td.TdBQty              
       when ins.TdBDc= 'C' then ins.TdBQty end)              
    where ins.TdSrNo= 0              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Receiving Bag Quantity Cannot Be < Issuing Bag Quantity'              
      GoTo ErrHndlr              
        end              
*/              
/* **** Not required **** */              
              
   if @mode in ('D')              
   begin              
    /*** (Bef 2.13)              
    --****** Cannot Delete 'BM', TdDc='C', Tdsrno= 0              
     If exists TdBDc='D', TdSrno=0 in same voucher ********              
    select @Row=Count('x') from Deleted Del where              
     Exists (Select 'x' from Txnd  where              
      Txnd.TdCoCd= Del.TdCoCd and Txnd.TdTc= Del.TdTc and              
      Txnd.TdYy= Del.TdYy and Txnd.TdChr= Del.TdChr and              
 Txnd.TdNo= Del.TdNo and Txnd.TdBDc= 'D' and TdSrNo= 0              
             )              
           and TdBDc= 'C' and TdSrNo= 0              
    If @Row > 0              
     begin              
       Select @ErrMsg='Cannot Delete Parent, Child Exists'              
       GoTo ErrHndlr              
         end              
    (Bef 2.13) ***/              
              
              
    /*** (Jen 2.13) ***/              
    /****** Cannot Delete 'BM', TdDc= 'C', TdSrNo= 0               
    If exists TdBDc= 'D', TdSrNo= 0, with same TdRefKey in same voucher ********/               
    /* Current Partition */              
    select @Row= Count('x') from Deleted Del where Del.TdPrtKey=@wCurrPrtn and               
     Exists (Select 'x' from Txnd Td where Td.TdPrtKey=Del.TdPrtKey and              
      Td.TdTIdNo=Del.TdTIdNo and Td.TdCoCd= Del.TdCoCd and Td.TdTc= Del.TdTc and               
      Td.TdYy= Del.TdYy and Td.TdChr= Del.TdChr and               
      Td.TdNo= Del.TdNo and Td.TdBDc= 'D' and Td.TdSrNo= 0 and               
      Td.TdRefKey= Del.TdRefKey               
      /* and Td.TdSr> Del.TdSr */              
             )               
           and TdBDc= 'C' and TdSrNo= 0               
    If @Row > 0              
