  and ((Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
    where Del.TdPrtKey=SPRtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd and Del.TdLotNo= SLotNo and              
     Del.TDRmSz = SRmSz and Del.TDRmSz2 = SRmSz2 and Del.TDRmSz3 = SRmSz3 and Del.TdRmStkRt = SRmStkRt and              
     (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
     when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
     else '' end )= SLoc              
       ) /*- Del.TdRmWt */              
      ) < 0              
  And Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
       HAvgSRtYN = 'N')              
  And Exists (Select 'X' from Param Join RmMst On PTyp = 'RMSCTG' AND RmPrtKey=Del.TdPrtKey and RmCd = Del.TdRmCd And              
       PMCD = RMCTG And PSCd = RMSCTG where PValue1 = 'Y')              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock For This Rm Ctg'              
     GoTo ErrHndlr              
  End              
      End  /*  #########################################  Manoj  #########################################  */              
 END              
 END              
 /**** urmi NegStk end ****/              
              
 If @wEntTyp = 'TxnBag' And @wTcTyp= 'BM'               
 Begin              
  If @Mode in ('A', 'C')              
  Begin              
   /****** (Jen 2.13 CT) changed the where clause for considering Component Bags ******/              
   /* ****** Sachin 2.13.0 - [28-06-2006] - Flute Bag Close On Merge  ****** */              
   /* This check has been put at end as there are certain checks which fail when bag is closed               
      and are placed above this update ***** */              
   /* Current Partition */              
   Update Bag               
    Set BCls = 'Y',              
                      BClsDt= (Select TDt From Txn Where TPrtKey=ins.TdPrtKey               
          and TIdNo=ins.TdTIdNo and TCoCd= ins.TdCoCd And TTc = ins.TdTc               
          And TYy = ins.TdYy And TChr= ins.TdChr And TNo= ins.TdNo)               
   From inserted ins              
   Where BPrtKey=ins.TdPrtKey and BIdNo=ins.TdBIdNo and BCoCd= ins.TdCoCd And BYy= ins.TdBYy And BChr= ins.TdBChr               
    And BNo= ins.TdBNo And ins.TdSrNo= 0               
    And Convert( Decimal (16, 1), BQty) = Convert( Decimal (16, 1), 0)               
    And Convert( Decimal (16, 3), BGrWt) = Convert( Decimal (16, 3), 0)               
    And BPtQty = 0               
    And (Select PValue From Param Where PTyp= 'BCHR' And PMCd= ins.TdBChr And PSCd= '') in ('C', 'F')               
    /*  (Bef 2.13 CT)              
      And (Select PValue From Param Where PTyp= 'BCHR' And PMCd= Del.TdBChr And PSCd= '' )= 'Y'              
         (Bef 2.13 CT) */              
   /* ****** Sachin 2.13.0 - [28-06-2006] - Flute Bag Close On Merge  ****** */               
  End              
 End                
Return              
ErrHndlr:              
 BEGIN              
  Select @ErrMsg='|'+@ErrMsg              
  RaisError(@ErrMsg,16,1)              
  Rollback Transaction              
 END 


GOGO

ALTER TRIGGER [dbo].[FgRm_INUPDL] ON [dbo].[FgRm] 
       FOR INSERT,UPDATE,DELETE  
AS  
BEGIN  
	/* Trigger Version 3.3.0 - Speed Optimization */
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wTcTyp Varchar(3) 
	Declare @wEntTyp Varchar(8)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1) 
	
	IF @@ROWCOUNT= 0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'FgRm' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   
	
	Select @wCurrPrtn='C'

	/*** Storing Tc Type In The Variable @wTcTyp ***/
	if @mode in ('A','C')
	Begin
		select @wTcTyp= max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= FrTc and PSCd=''
	end

	if @mode in ('D')
	Begin
		select @wTcTyp= max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= FrTc and PSCd=''
	end

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where FrPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where FrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.FrPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
			/* Current Partition */
			select @ROW =Count('x')  From inserted where  FrPrtKey=@wCurrPrtn and
			Exists (select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FrCoCd +',%')) 
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW=Count('x') From Deleted Where FrPrtKey=@wCurrPrtn and 
		Exists (select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FrCoCd +',%'))
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End
 
	/******** Only One TcTyp records can be Inserted at a time.********/
	/* Current Partition */	
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= FrTc and PSCd= '' Where FrPrtKey=@wCurrPrtn 
	If @Row > 1
	BEGIN
		Select @ErrMsg= 'Transactions of only One TcType can be Acted On'
	  	GoTo ErrHndlr
	END

	/******** Only One TcTyp records can be Deleted at a time. *********/
	/* Current Partition */		
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp='TC' and PMcd= FrTc and PSCd='' Where FrPrtKey=@wCurrPrtn 
	If @Row > 1
	BEGIN
		Select @ErrMsg='Transactions of only One TcType can be Acted On'
		GoTo ErrHndlr
	END

	/*** Storing Entry Type In The Variable @wEntTyp ***/
	/* Current Partition */			
	Select @wEntTyp= PValue1 From Param Where PTyp= 'TCTYP' and PMCd=@wTcTyp and PSCd=''
	If @Mode = 'C'
	Begin
		/******* If Mode = 'C' then Cannot change Key Values********/
		/* Current Partition */		
		select @Row=Count('x') from Deleted Del where Del.FrPrtKey=@wCurrPrtn and
			 Not Exists (Select 'x' from Inserted Ins where Ins.FrPrtKey=Del.FrPrtKey 
					and Ins.FrIdNo=Del.FrIdNo and Ins.FrCoCd=Del.FrCoCd 
					and Ins.FrTc=Del.FrTc and Ins.FrYy= Del.FrYy
					and Ins.FrChr= Del.FrChr and Ins.FrNo=Del.FrNo
					and Ins.FrSr=Del.FrSr and Ins.FrSrNo= Del.FrSrNo)
		If @Row > 0
		begin		  
			Select @ErrMsg='Cannot Change FgRm Key values'
			GoTo ErrHndlr
		end
	End

	/* Zubin 212 Lot No. Shld be blank when HLotNoYN= 'N' in head */ 
	/* Manali 3.03 - 16/07/08 - Lot No. open for Acc ('X') also */
	If @wTcTyp in ('FB', 'FWB') 
	Begin
		/* Current Partition */		
		Select @Row= Count('x') From Inserted Ins Where FrPrtKey=@wCurrPrtn and FrLotNo<> '' and 
			Not Exists (Select 'x' From Head where HCoCd= Ins.FrCoCd and HCd= 'ZSELF' and 
				HLotNoYN= 'Y') 
	  	If @Row> 0 
		begin
			Select @ErrMsg= 'Lot No. Should Be Blank As ''Implement Lot No. For D/C/X/G/P/S/L/M'' Option Is ''N'' In Head Master (Tab 5)' 
		  	GoTo ErrHndlr
		end 

		/* Zubin 212 Lot No. For 'D' and 'C' only */ 
		/* Current Partition */	
		/* Manali 3.03 - 16/07/08 - Lot No. open for Acc ('X') also */	
		select @Row= Count('x') from inserted ins where FrLotNo <> '' and FrPrtKey=@wCurrPrtn and
			Not Exists (select 'x' from RmMst where RmZ= 'N' and RmCd= FrRmCd and RmPrtKey=FrPrtKey and RmCtg IN ('D', 'C', 'X','G','P','S','L','M'))
	  	If @Row> 0
		begin
			Select @ErrMsg= 'Lot No. Should Be Entered For Diamonds, Color Stones and Accessories Only' 
			GoTo ErrHndlr
		end
	End

	If @Mode = 'C' and @wTcTyp in ('FB', 'FR')
	Begin
		/**** Cannot edit any field if FdDespQty <> 0 ****/
		/* Zubin 212 (FrLotNo added) */
		/* Current Partition */		
		select @Row= Count('x') from deleted Del
			join Fgd on FdPrtKey=Del.FrPrtKey and FdIdNo=Del.FrFdIdNo and FdCoCd=Del.FrCoCd And FdTc=Del.FrTc 
					And FdYy=Del.FrYy And  FdChr=Del.FrChr And FdNo=Del.FrNo And FdSr=Del.FrSr 
			where FdPrtKey=@wCurrPrtn and FdDespQty<>0 and 
				(not exists(Select 'x' from Inserted Ins where
				Del.FrPrtKey=Ins.FrPrtKey and Del.FrCoCd=Ins.FrCoCd and Del.FrSrno=Ins.FrSrNo and Del.FrFrRmLoc=Ins.FrFrRmLoc
				and Del.FrFrRmDc=Ins.FrFrRmDc and Del.FrRmCd=Ins.FrRmCd and Del.FrLotNo=Ins.FrLotNo 
				and Del.FrRmSz=Ins.FrRmSz and Del.FrRmSz2=Ins.FrRmSz2 and Del.FrRmSz3=Ins.FrRmSz3 and Del.FrRmStkRt=Ins.FrRmStkRt
				and Del.FrRmQty=Ins.FrRmQty and Del.FrRmWt=Ins.FrRmWt 
				and Del.FrToRmLoc=Ins.FrToRmLoc and Del.FrToRmDc=Ins.FrToRmDc))
		If @Row > 0
		begin	
			Select @ErrMsg= 'Cannot Edit as Desp Qty<>0'
			GoTo ErrHndlr
		end
	End

	If @Mode = 'C' and @wTcTyp in ('FWB', 'FWR')
	Begin
		/**** Cannot edit any field ****/
		/* Zubin 212 (FrLotNo added) */
		/* Current Partition */		
		select @Row= Count('x') from deleted Del
			join Fgd on FdPrtKey=Del.FrPrtKey and FdIdNo=Del.FrFdIdNo and FdCoCd= Del.FrCoCd And FdTc= Del.FrTc And 
				    FdYy= Del.FrYy And  FdChr= Del.FrChr And
				    FdNo= Del.FrNo And FdSr= Del.FrSr 
			where Del.FrPrtKEy=@wCurrPrtn and not exists(Select 'x' from Inserted Ins where Del.FrPrtKey=Ins.FrPrtKey and 
				Del.FrCoCd=Ins.FrCoCd and Del.FrSrNo= Ins.FrSrNo and Del.FrFrRmLoc= Ins.FrFrRmLoc
				and Del.FrFrRmDc= Ins.FrFrRmDc and Del.FrRmCd= Ins.FrRmCd and Del.FrLotNo= Ins.FrLotNo
				and Del.FrRmSz= Ins.FrRmSz and Del.FrRmSz2= Ins.FrRmSz2 and Del.FrRmSz3= Ins.FrRmSz3 and Del.FrRmStkRt= Ins.FrRmStkRt
				and Del.FrRmQty= Ins.FrRmQty and Del.FrRmWt= Ins.FrRmWt 
				and Del.FrToRmLoc= Ins.FrToRmLoc and Del.FrToRmDc= Ins.FrToRmDc) 
		If @Row > 0
		begin	
			Select @ErrMsg= 'Cannot Edit Any Value'
			GoTo ErrHndlr
		end
	End


	If @Mode in ('A','C')
	Begin
		/******* Valid FrTc,FrYy,FrChr, FrNo, FrSr ********/
		/* Current Partition */		
		Select @Row=Count('x') From Inserted Ins Where FrPrtKey=@wCurrPrtn and
  			Not Exists (Select 'x' From Fgd Where FdPrtKey=Ins.FrPrtKey and FdIdNo=FrFdIdNo and FdCoCd= Ins.FrCoCd And 
				    FdTc= Ins.FrTc And FdYy= Ins.FrYy And  FdChr= Ins.FrChr And FdNo= Ins.FrNo And FdSr= Ins.FrSr)
  		If @Row>0
	 	begin
			Select @ErrMsg='FgRm Voucher No. Does Not Exist'
			GoTo ErrHndlr
	  	end

		/***** FrSrNo <> 0 *****/
		/* Current Partition */		
		Select @Row= Count('x') From Inserted Ins Where FrPrtKey=@wCurrPrtn and FrSrNo= 0
		If @Row>0
		begin
	  		Select @ErrMsg='Rm. SrNo Cannot be 0'
		  	GoTo ErrHndlr
		end

		/*********** FrRmCd  Valid RmCd, RmZ='N' *********/
		/* Current Partition */		
		Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From RmMst where 
				RmCd= FrRmCd and RmPrtKey=FrPrtKey and RmZ= 'N')
  	  	If @Row>0
		begin
			Select @ErrMsg='Invalid Rm Code'
		  	GoTo ErrHndlr
		end

		/********** FrFrRmDc  Valid 'Dc' *************/
		/* Current Partition */		
		Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and  (Not Exists (Select 'x' From Param where PTyp= 'DC'
				and PMCd = Ins.FrFrRmDc and PScd= '')
				or Not Exists (Select 'x' From Param where PTyp= 'DC'
				and PMCd = Ins.FrToRmDc and PScd= ''))
	  	If @Row>0
		begin
			Select @ErrMsg='Invalid From/ To Rm DC'
		  	GoTo ErrHndlr
		end

		/******* FrToRmDc should be Opp of  FrFrRmDc *******/
		/* Current Partition */
	  	Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and ((FrToRmDc= FrFrRmDc And FrFrRmDc<> '')  Or
				(FrFrRmDc<> '' and FrToRmDc= ''))
	  	If @Row>0
		begin
			Select @ErrMsg='Invalid To Rm Dc'
			GoTo ErrHndlr
		end
	End


	If @Mode in ('A','C') and @wTcTyp in ('FB')
	Begin

		/****** If TcTyp= 'FB' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'F' ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd 
				and LocTyp= 'F' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
	  	If @Row> 0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FB' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'W' ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins 
			Where Ins.FrPrtKEy=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd 
				and LocTyp= 'W' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
  	  	If @Row>0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''W'' '
		  	GoTo ErrHndlr
		end

		/* urmi 2.05 zero wt and qty Not Allowed in FG */
		/****** If TcTyp= 'FB' Then FrRmWT or FrRmQty Should be NonZero ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where FrPrtKey=@wCurrPrtn and (FrRmWt=0 AND FrRmQty = 0)
  	  	If @Row>0
		begin
			Select @ErrMsg='Either Wt and Qty should be non zero for the RM'
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FB' Then RM Wt/ Qty Can Be Issued From Locations Of Type 'W' Only ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins 
			Where FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd and 
				LocTyp= 'W' and ((LocCd= FrFrRmLoc and FrFrRmDc= 'C') 	or
	   					 (LocCd= FrToRmLoc and FrToRmDc= 'C')	
				       		)
   					  )
  	  	If @Row>0
		begin
			Select @ErrMsg= 'RM Wt/ Qty Can Be Issued From Locations Of Type ''W'' Only'
		  	GoTo ErrHndlr
		end

		/***** If FdBagNo<>0 
			FrRmCd to exist in FdPrdOrder****/
		/* Current Partition */
		select @Row= Count('x') from inserted Ins
			join Fgd on FdPrtKey=Ins.FrPRtKey and FdIdNo=Ins.FrFdIdNo and FdCoCd=Ins.FrCoCd And FdTc=Ins.FrTc And
				    FdYy=Ins.FrYy And  FdChr=Ins.FrChr And FdNo=Ins.FrNo And FdSr=Ins.FrSr
			Where Ins.FrPrtKEy=@wCurrPrtn and (FdBYy<> '' or FdBChr<> '' or FdBNo<> 0) and 
				(Not Exists (select 'x' from OrdRm where OrPrtKey=FdPrtKey and
				    OrCoCd= FdCoCd And OrTc= FdPrdOdTc And
				    OrYy= FdPrdOdYy And OrChr= FdPrdOdChr And
				    OrNo= FdPrdOdNo And OrSr= FdPrdOdSr And 
				    OrRmCd= FrRmCd))
		If @Row> 0
		begin	
			Select @ErrMsg= 'Rm Code Does Not Exist in Prd. Order'
			GoTo ErrHndlr
		end

		/***** FrRmCd to exist in FdExpOrder ******/
		/* Current Partition */
		select @Row= Count('x') from inserted Ins
			join Fgd on FdPrtKey=Ins.FrPrtKey and FdIdNo=Ins.FrFdIdNo and FdCoCd=Ins.FrCoCd And FdTc=Ins.FrTc And 
				    FdYy=Ins.FrYy And  FdChr=Ins.FrChr And
				    FdNo=Ins.FrNo And FdSr=Ins.FrSr
			where not exists(select 'x' from OrdRm where OrPrtKey=FdPrtKey and
				    OrCoCd= FdCoCd And OrTc= FdExpOdTc And
				    OrYy= FdExpOdYy And  OrChr= FdExpOdChr And
				    OrNo= FdExpOdNo And OrSr= FdExpOdSr And 
				    OrRmCd= FrRmCd)
		If @Row> 0
		begin	
			Select @ErrMsg= 'Rm Code Does Not Exist in Exp Order'
			GoTo ErrHndlr
		end

/* ### Correct This Part Of The Trigger ***/ 
		/***** If FdBagNo <> 0
			RmQty >= 0, RmWt >= 0 for the given RmCd, Sz, StkRt 
			BGrWt >= 0    *****/
/*
		select @Row= Count('x') from inserted Ins 
			join Fgd on FdTc= Ins.FrTc And 
				    FdYy= Ins.FrYy And FdChr= Ins.FrChr And 
				    FdNo= Ins.FrNo And FdSr= Ins.FrSr 
			where (FdBYy<> '' or FdBChr<> '' or FdBNo<> 0) and 
				(   (not exists(select 'x' from Bag where 
				    BYy= FdBYy and BChr= FdBChr and BNo= FdBNo
				    and BGrWt>= 0))
				or
				    (not exists(select 'x' from BagRm where
				    BrBYy= FdBYy and BrBChr= FdBChr and BrBNo= FdBNo
				    and BrRmCd= FrRmCd and BrRmSz= FrRmSz

				    and BrRmStkrt= FrRmStkRt and BrRmQty>= 0
				    and BrRmWt>= 0))
				)
		If @Row > 0
		begin	
			Select @ErrMsg= 'Rm Qty<0 / Rm Wt<0 / Bag Gr. Wt<0'
			GoTo ErrHndlr
		end
*/
/* ### Correct This Part Of The Trigger ***/ 

	End


	If @Mode in ('A','C') and @wTcTyp in ('FR')
	Begin

		/********** If TcTyp= 'FR' Then FrFrRmLoc Valid Loc, LocTyp<>'P', 'W' ************/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = Ins.FrCoCd and 
				LocTyp not in ('P', 'W') and LocCd = Ins.FrFrRmLoc)
  	  	If @Row>0
		BEGIN
			Select @ErrMsg='Invalid From Rm Loc'
		  	GoTo ErrHndlr
		END

		/****** If TcTyp= 'FR' then FrToRmLoc  Valid Loc, LocTyp<>'P', 'W'  ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = Ins.FrCoCd and 
				LocTyp not in ('P', 'W') and LocCd = Ins.FrToRmLoc)
  	  	If @Row>0
		BEGIN
			Select @ErrMsg='Invalid To Rm Loc'
		  	GoTo ErrHndlr
		END

		/****** If TcTyp= 'FR' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'F' ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd and 
				LocTyp= 'F' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
  	  	If @Row>0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end

		/***** FrRmCd to exist in FdExpOrder ******/
		/* Current Partition */
		select @Row= Count('x') from inserted Ins
			join Fgd on FdPrtKey=Ins.FrPrtKey and FdIdNo=Ins.FrFdIdNo and FdCoCd=Ins.FrCoCd And FdTc=Ins.FrTc And
				    FdYy=Ins.FrYy And  FdChr=Ins.FrChr And
				    FdNo=Ins.FrNo And FdSr=Ins.FrSr
			where Ins.FrPrtKEy=@wCurrPrtn and not exists(select 'x' from OrdRm where 
				    OrPrtKey=FdPrtKey and OrCoCd= FdCoCd And OrTc= FdExpOdTc And
				    OrYy= FdExpOdYy And  OrChr= FdExpOdChr And
				    OrNo= FdExpOdNo And OrSr= FdExpOdSr And 
				    OrRmCd= FrRmCd)
		If @Row> 0
		begin	
			Select @ErrMsg= 'Rm Code Does Not Exist in Exp Order'
			GoTo ErrHndlr
		end
	End

	
	/*** (Jen 2.13) ***/
	If @Mode in ('A','C') and @wTcTyp in ('FWB')
	Begin
		/****** If TcTyp= 'FWB' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'F' ******/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd 
				and LocTyp= 'F' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
	  	If @Row> 0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FWB' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'W' ******/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd 
				and LocTyp= 'W' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
  	  	If @Row>0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''W'' '
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FWB' Then FrRmWT or FrRmQty Should be NonZero ******/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where Ins.FrPrtKey=@wCurrPrtn and (FrRmWt=0 AND FrRmQty = 0)
  	  	If @Row>0
		begin
			Select @ErrMsg='Either Wt and Qty should be non zero for the RM'
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FWB' Then RM Wt/ Qty Can Be Issued From Locations Of Type 'F' Only ******/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd and 
				LocTyp= 'F' and ((LocCd= FrFrRmLoc and FrFrRmDc= 'C') 	or
	   					 (LocCd= FrToRmLoc and FrToRmDc= 'C'))))
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'RM Wt/ Qty Can Be Issued From Locations Of Type ''F'' Only'
		  	GoTo ErrHndlr
		end

		/****** If FdBagNo<> 0 FrRmCd to exist in FdPrdOrder ******/
		/* Current Partition */
		select @Row= Count('x') from inserted Ins
			join Fgd on FdPrtKey=Ins.FrPrtkey and FdIdNo=Ins.FrFdIdNo and FdCoCd=Ins.FrCoCd And FdTc=Ins.FrTc And
				    FdYy=Ins.FrYy And  FdChr=Ins.FrChr And FdNo=Ins.FrNo And FdSr=Ins.FrSr
			where FrPrtKey=@wCurrPrtn and (FdBYy<> '' or FdBChr<> '' or FdBNo<> 0) and 
				(not exists(select 'x' from OrdRm where 
				    OrPrtKey=FdPrtKey And OrCoCd= FdCoCd And OrTc= FdPrdOdTc And
				    OrYy= FdPrdOdYy And OrChr= FdPrdOdChr And
				    OrNo= FdPrdOdNo And OrSr= FdPrdOdSr And 
				    OrRmCd= FrRmCd))
		If @Row> 0
		begin	
			Select @ErrMsg= 'Rm Code Does Not Exist in Prd. Order'
			GoTo ErrHndlr
		end
	End
	/*** (Jen 2.13) ***/


	If @Mode = 'D'
	Begin
		/**** Cannot delete if FdDespQty <> 0****/
		/* Current Partition */
		Select @Row= Count('x') From deleted Del
			Where Del.FrPrtKey=@wCurrPrtn 
				and (exists(select 'x' from Fgd where FdPrtKey=FrPrtKey and FdIdNo=FrFdIdNo and FdCoCd=FrCoCd And 
								FdTc=FrTc And FdYy=FrYy And  FdChr=FrChr And FdNo=FrNo And FdSr=FrSr and FdDespQty<>0))
		If @Row > 0

		begin	
			Select @ErrMsg= 'Cannot Delete as Desp Qty <> 0'
			GoTo ErrHndlr
		end

/* ###
		**** Cannot delete if Transaction Has Taken Place For The Bag After The Backward Movement ****
		select @Row= Count('x') from deleted Del 
			where @wTcTyp= 'FWB' and not exists(select 'x' from Fgd join Bag on BYy= FdBYy and BChr= FdBChr and 
								BNo= FdBNo where FdTc=FrTc And FdYy=FrYy And  FdChr=FrChr And 
								FdNo=FrNo And FdSr=FrSr and FdBYyKey= BLstYyKey) 
		If @Row > 0

		begin	
			Select @ErrMsg= 'Cannot Delete as Transaction Has Taken Place For The Bag After The Backward Movement'
			GoTo ErrHndlr
		end
### */
	End

	/*** UPDATES ***/

	/*** Update SYyMm from FrFrRmLoc ***/
	/* Zubin 212 (FrLotNo added in SYyMm inserts/updates) */ 
	if @mode in ('C','D')
	Begin
		/* Current Partition */
		update SYyMm set
		SRmCrQty= SRmCrQty- (select isnull(sum(Del.FrRmQty), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrFrRmDc= 'C' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmCrWt= SRmCrWt-(select isnull(sum(Del.FrRmWt), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrFrRmDc= 'C' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrQty= SRmDrQty-(select isnull(sum(Del.FrRmQty), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrFrRmDc= 'D' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrWt= SRmDrWt-(select isnull(sum(Del.FrRmWt), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrFrRmDc= 'D' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd= SRmCd 
			and Del.FrLotNo= SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm) 
		from Deleted Join Fg on FgPrtKey=Deleted.FrPrtKey and FgCoCd= Deleted.FrCoCd and FgTc= Deleted.FrTc and FgYy= Deleted.FrYy 
			and FgChr= Deleted.FrChr and FgNo= Deleted.FrNo 
			where Deleted.FrPrtKey=SPrtKey and Deleted.FrCoCd= SCoCd and Deleted.FrRmCd= SRmCd and Deleted.FrLotNo= SLotNo 
			and Deleted.FrRmSz= SRmSz and Deleted.FrRmSz2= SRmSz2 and Deleted.FrRmSz3= SRmSz3 and Deleted.FrRmStkRt= SRmStkRt 
			and Deleted.FrFrRmLoc= SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))=SYyMm
			and (Deleted.FrFrRmDc='D'  or Deleted.FrFrRmDc='C')
	End


	if @mode in ('A','C')
	Begin
		/* Current Partition */
		insert into SYyMm(SPrtKey,SCoCd,SRmCd,SLotNo,SRmSz,SRmSz2,SRmSz3,SRmStkRt,SLoc,SYyMm,SRmDrqty,SRmDrWt,SRmCrQty,SRmCrWt) 
			select distinct FrPrtKey,FrCoCd,FrRmCd,FrLotNo,FrRmSz,FrRmSz2,FrRmSz3,FrRmStkRt,FrFrRmLoc,convert(int,convert(varchar(6),Fgdt,112)),0,0,0,0
			from inserted join Fg on FgPRtKey=FrPrtKey and FgCoCd=FrCoCd and FgTc=FrTc and FgYy=FrYy and FgChr=FrChr and FgNo=FrNo
			where not exists(select 'x' from  SYyMm where SPrtKey=FrPrtKey and SCoCd= FrCoCd and SRmCd=FrRmCd and SLotNo=FrLotNo 
			and SRmSZ=FrRmSz and SRmSZ2=FrRmSz2 and SRmSZ3=FrRmSz3 and SRmStkRt=FrRmStkRt and SLoc=FrFrRmLoc and
			SYyMm= convert(int,convert(varchar(6),Fgdt,112)))

		/* Current Partition */
		update SYyMm set
		SRmCrQty= SRmCrQty+(select isnull(sum(Ins.FrRmQty), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrFrRmDc= 'C' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd= SRmCd 
			and Ins.FrLotNo= SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmStkRt=SRmStkRt and Ins.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmCrWt=SRmCrWt+(select isnull(sum(Ins.FrRmWt), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrFrRmDc= 'C' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrQty=SRmDrQty+(select isnull(sum(Ins.FrRmQty), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrFrRmDc= 'D' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrWt=SRmDrWt+(select isnull(sum(Ins.FrRmWt), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrFrRmDc= 'D' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm)
		from Inserted Join Fg on FgPrtKey=Inserted.FrPrtKey and FgCoCd= Inserted.FrCoCd and FgTc= Inserted.FrTc and FgYy= Inserted.FrYy 
			and FgChr= Inserted.FrChr and FgNo= Inserted.FrNo 
			where Inserted.FrPrtKey=SPrtKey and Inserted.FrCoCd= SCoCd and Inserted.FrRmCd= SRmCd and Inserted.FrLotNo= SLotNo 
			and Inserted.FrRmSz= SRmSz and Inserted.FrRmSz2= SRmSz2 and Inserted.FrRmSz3= SRmSz3 and Inserted.FrRmStkRt= SRmStkRt and Inserted.FrFrRmLoc= SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))=SYyMm
			and (Inserted.FrFrRmDc='D'  or Inserted.FrFrRmDc='C')
	End

	/*** Update SYyMm from FrToRmLoc ***/
	if @mode in ('C','D')
	Begin
		/* Current Partition */
		update SYyMm set
		SRmCrQty= SRmCrQty- (select isnull(sum(Del.FrRmQty), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrToRmDc= 'C' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmCrWt= SRmCrWt-(select isnull(sum(Del.FrRmWt), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrToRmDc= 'C' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrQty= SRmDrQty-(select isnull(sum(Del.FrRmQty), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrToRmDc= 'D' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrWt= SRmDrWt-(select isnull(sum(Del.FrRmWt), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrToRmDc='D' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm) 
		from Deleted Join Fg on FgPrtKey=Deleted.FrPrtKey and FgCoCd= Deleted.FrCoCd and FgTc= Deleted.FrTc and 
			FgYy= Deleted.FrYy and FgChr= Deleted.FrChr and FgNo= Deleted.FrNo 
			Where Deleted.FrPrtKey=SPrtKey and Deleted.FrCoCd= SCoCd and Deleted.FrRmCd= SRmCd and Deleted.FrLotNo= SLotNo 
			and Deleted.FrRmSz= SRmSz and Deleted.FrRmSz2= SRmSz2 and Deleted.FrRmSz3= SRmSz3 and Deleted.FrRmStkRt= SRmStkRt and Deleted.FrToRmLoc= SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))=SYyMm
			and (Deleted.FrToRmDc='D'  or Deleted.FrToRmDc='C')
	End

	if @mode in ('A','C')
	Begin
		/* Current Partition */
		insert into SYyMm(SPrtKey,SCoCd,SRmCd,SLotNo,SRmSz,SRmSz2,SRmSz3,SRmStkRt,SLoc,SYyMm,SRmDrqty,SRmDrWt,SRmCrQty,SRmCrWt) 
			select distinct FrPrtKey,FrCoCd,FrRmCd,FrLotNo,FrRmSz,FrRmSz2,FrRmSz3,FrRmStkRt,FrToRmLoc,convert(int,convert(varchar(6),Fgdt,112)),0,0,0,0
			from inserted join Fg on FgPrtKey=FrPrtKey and FgCoCd= FrCoCd and FgTc=FrTc and FgYy=FrYy and FgChr=FrChr and FgNo=FrNo
			where not exists(select 'x' from  SYyMm where SPrtKey=FrPrtKey and SCoCd= FrCoCd and SRmCd=FrRmCd and 
			SLotNo=FrLotNo and SRmSZ= FrRmSz and SRmSZ2= FrRmSz2 and SRmSZ3= FrRmSz3 and SRmStkRt=FrRmStkRt and SLoc=FrToRmLoc and
			SYyMm= convert(int,convert(varchar(6),Fgdt,112)))

		/* Current Partition */
		update SYyMm set
		SRmCrQty= SRmCrQty+(select isnull(sum(Ins.FrRmQty), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrToRmDc= 'C' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmCrWt=SRmCrWt+(select isnull(sum(Ins.FrRmWt), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrToRmDc= 'C' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrQty=SRmDrQty+(select isnull(sum(Ins.FrRmQty), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrToRmDc= 'D' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrWt=SRmDrWt+(select isnull(sum(Ins.FrRmWt), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrToRmDc= 'D' and Ins.FrPRtKey=SPrtKEy and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm)
		from Inserted Join Fg on FgPrtKey=Inserted.FrPrtKey and FgCoCd= Inserted.FrCoCd and FgTc= Inserted.FrTc and FgYy= Inserted.FrYy 
			and FgChr= Inserted.FrChr and FgNo= Inserted.FrNo 
			where Inserted.FrPrtKey=SPrtKey and Inserted.FrCoCd= SCoCd and Inserted.FrRmCd= SRmCd and Inserted.FrLotNo= SLotNo 
			and Inserted.FrRmSz= SRmSz and Inserted.FrRmSz2= SRmSz2 and Inserted.FrRmSz3= SRmSz3 and Inserted.FrRmStkRt= SRmStkRt and Inserted.FrToRmLoc= SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))=SYyMm
			and  (Inserted.FrToRmDc='D'  or Inserted.FrToRmDc='C')
	End
Return
ErrHndlr:
	BEGIN
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	END
END

GOGO

	


IF NOT EXISTS(SELECT *
          FROM   INFORMATION_SCHEMA.COLUMNS
          WHERE  upper(TABLE_NAME) = 'MULTIPRCQTRM'
                 AND upper(COLUMN_NAME) = upper('MQRLN3')) 
	ALTER TABLE MultiPrcQtRm
			ADD MqrLn3 int not null default 0

GOGO


ALTER TRIGGER [dbo].[OrdMst_INUPDL] ON [dbo].[OrdMst]   
   FOR INSERT,UPDATE,DELETE  NOT FOR REPLICATION
AS  
BEGIN  
 /* *** Trigger Version Emr 3.9.0 *** */  
 DECLARE @ROW INT  
 DECLARE @mode char(1)  
 DECLARE @errmsg varchar(255)  
 Declare @wHCd Varchar(8)   
 Declare @wSelfCoCd Varchar(3)   
 DECLARE @ReplAgt BIT    
 DECLARE @wSysDb varchar(3)  
 DECLARE @wCurrPrtn varChar(1)  
  
 Select @wCurrPrtn = 'C'  
  
 IF @@ROWCOUNT= 0   
  RETURN   
  
 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'OrdMst' )  
  RETURN  
  
 select @mode= case (select count('x') from inserted) when 0 then 'D'  
        else  
    case (select count('x') from deleted) when 0 then 'A' else 'C' end  
        end   
  
 Select @wHCd= 'ZSELF', @wSelfCoCd= 'ZZZ'  
   
  /* **** Checking Whether a Normal Transaction or Replicated One **** */  
  Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))  
  Select @wSysDb= SysDb From SysDb where SysId='CRM'  
  Set @wSysDb= IsNull(@wSysDb,'')  
  
 /******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */  
 if @mode='C' And @ReplAgt<>1  
 begin  
  Select @row=count('x') From Inserted Where OmPrtKey<>@wCurrPrtn  
  if @row> 0   
  begin  
   select @errmsg= 'Cannot Edit Records of Previous Partition'  
   goto ErrHndlr  
  end  
 End  
  
 if @mode='A' And @ReplAgt<>1  
 Begin  
  Select @row=count('x') From Inserted Where OmPrtKey <> @wCurrPrtn   
  if @row> 0   
  begin  
   select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''  
   goto ErrHndlr  
  end  
 end   
  
 If @Mode='D' And @ReplAgt<>1  
 Begin   
  select @row= count('x') from deleted del where del.OmPrtKey<>@wCurrPrtn  
  if @row> 0   
  begin  
   select @errmsg= 'Cannot Delete Records From Previous Partition'  
   goto ErrHndlr  
  end  
 End  
 /******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */  
  
  
  If  (@ReplAgt<>1)  
  Begin  
  /*db='WEB' then cannot  Insert /Update/Delete  where OmChr<> 'WEB'   
  Cannot edit/Delete where OmSubmitYN=’Y’ i.e Check deleted.OmSubmitYN=’Y’    
  Cannot edit OmAckYN    
  */  
    
  /*******No Need to Check  Sysdb='' beceuse Chr='WEB' insert is not allowed in vParam where not exists SysId='CRM'*************************/  
  If @Mode = 'A'   
  Begin  
   /*****If  db= '-' then Insert  Not allowed in OrdMst  for OmChr='WEB' ******/  
   /* Partition Key Not required */  
   Select @Row=Count('x') From Inserted where OmChr='WEB' and @wSysDb<>'WEB'  
   If @Row> 0  
   begin    
    select @errmsg= 'Cannot Insert  Web Order in Emr Database '    
    goto ErrHndlr    
   end    
  End  
   
  If @Mode= 'C'   
  Begin  
   /******Sysdb='-' then  cannot  Update  where OmChr='WEB' and OmAckYN='N' **********************/  
   /* Partition Key Not required */  
   Select @Row=Count('x') From inserted where OmChr='WEB' and (OmAckYN='N' and @wSysDb ='-')   
   If @Row> 0  
   begin    
    select @errmsg= 'Cannot Update Unacknowledged Web Order in Emr Database'    
    goto ErrHndlr    
   end    
    
   /******Sysdb='WEB' then  cannot  Update  where OmChr='WEB' and OmSubmitYN='Y'**********************/  
   /* Partition Key Not required */  
   Select @Row=Count('x') From Deleted where  OmChr='WEB' and   
    (OmSubmitYN='Y' and @wSysDb ='WEB')    
   If @Row> 0  
   begin    
    select @errmsg= 'Cannot Update Submitted Web Order in Crm Database '    
    goto ErrHndlr    
   end    
     
   /******Sysdb='-'  then  Cannot edit OmSubmittedYN   **********************/  
   /* Partition Key Not required */  
   Select @Row=Count('x') From Inserted ins where  OmChr='WEB' and @wSysDb ='-' and  
    Not Exists(Select 'x' from Deleted Del where ins.OmTc=del.OmTc and ins.OmCrmYy=Del.OmCrmYy and  
      ins.OmCrmChr=del.OmCrmChr and ins.OmCrmNo=del.OmCrmNo and ins.OmSubmitYN=del.OmSubmitYN)  
   If @Row> 0  
   begin    
    select @errmsg= 'Cannot Edit Order SubmitYN '    
    goto ErrHndlr    
   end    
   
   /******Sysdb='WEB'  then  Cannot edit OmAckYN   **********************/  
   /* Partition Key Not required */  
   Select @Row=Count('x') From Inserted ins where  OmChr='WEB' and @wSysDb ='WEB' and  
    Not Exists(Select 'x' from Deleted Del where ins.OmTc=del.OmTc and ins.OmCrmYy=Del.OmCrmYy and  
      ins.OmCrmChr=del.OmCrmChr and ins.OmCrmNo=del.OmCrmNo and ins.OmAckYN=del.OmAckYN)  
   If @Row> 0  
   begin    
    select @errmsg= 'Cannot Edit Order AcknowledgeYN '    
    goto ErrHndlr    
   end    
  End  
    
  If @Mode in ('A','C' )  
  Begin  
   /******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/  
   /***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/  
   /* Partition Key Not required */  
   Select @ROW =Count('x')  From inserted where    
   Exists (Select 'x' From SysDb where (SysId='EMR' and ',' + SdCoCd + ',' Not  like '%,'+ OmCoCd +',%'))  
   If @Row > 0    
   Begin   
    select @errmsg= 'Cannot Insert /Update '   
    goto ErrHndlr   
   end   
  
   /*****If  db= 'WEB' then Insert/Update  Not allowed in OrdMst  for OmChr<>'WEB' ******/  
   /* Partition Key Not required */  
   Select @Row=Count('x') From Inserted where OmChr<>'WEB' and @wSysDb='WEB'  
   If @Row> 0  
   begin    
    select @errmsg= 'Cannot Insert/Update Orders Other than OmChr=''WEB'' in CRM Database '    
    goto ErrHndlr    
   end      
      
   /*****4.1.2********/   
   Select @Row=Count('x') From Inserted ins where   
    (Select hHolChkYN From Head where HCd='ZSELF' and HCoCd=OmCoCd)='Y' and  
    (@Mode='A' or (@Mode='C' and  ins.OmDt<>IsNull((Select OmDt From Deleted del where   
          ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
          and ins.OmCoCd= del.OmCoCd and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy   
           and ins.OmChr= del.OmChr and ins.OmNo= del.OmNo),ins.OmDt))) and    
         exists(Select 'x' From DtTbl Where DtTag='HOL' and OmDt=DtDt and DtHolYN='Y')  
   If @Row> 0  
   begin    
    select @errmsg= 'Cannot Add Voucher on Holidays.'    
    goto ErrHndlr    
   end    
  End  
   
  If @Mode ='D'   
  Begin  
   /* Partition Key Not required */  
   select @ROW =Count('x')  From Deleted where    
    Exists (select 'x' From SysDb where (SysId='EMR' and ',' + SdCoCd + ',' Not  like '%,'+ OmCoCd +',%'))  
   if @Row > 0    
   Begin   
    select @errmsg= 'Cannot Delete '   
    goto ErrHndlr   
   end   
  
   /*****If  db= '-' then Delete Not allowed in OrdMst  for OmChr='WEB' ******/  
   /* Check Removed By Sangeeta in Emr 2.13.0 */  
   /*  
   Select @Row=Count('x') From Inserted where OmChr='WEB' and @wSysDb ='-'  
   If @Row> 0  
   begin    
    select @errmsg= 'Cannot Delete Web Order in Emr Database '    
    goto ErrHndlr    
   end    
   */     
   
    End    
  End  
   
 /******** Key Cannot Be Changed ********/   
  if @mode = 'C'  
  Begin    
  /******** Key Cannot Be Changed ********/   
  /* Partition Check Not Required */  
  select @Row= Count('x') from deleted del where   
    not exists (Select 'x' from inserted ins where ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
     and ins.OmCoCd= del.OmCoCd and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy   
     and ins.OmChr= del.OmChr and ins.OmNo= del.OmNo )  
  If @Row > 0  
  begin   
   Select @ErrMsg= 'Cannot Change Company Code/ Order Tc/Yy/Chr/No'  
   GoTo ErrHndlr  
  end  
  
  select @Row= Count('x') from deleted del where   
   exists(Select 'x' from Param Where PTyp='TC' and PMCd=del.OmTc and PValue='JT') and   
    not exists (Select 'x' from inserted ins where ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
     and ins.OmCoCd= del.OmCoCd and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy   
     and ins.OmChr= del.OmChr and ins.OmNo= del.OmNo and ins.OmCmCtg=del.OmCmCtg and ins.OmCmCd=del.OmCmCd   
     and ins.OmFrDmLoc=del.OmFrDmLoc and ins.OmToDmLoc=del.OmToDmLoc and ins.OmFrDmDc=del.OmFrDmDc and ins.OmToDmDc=del.OmToDmDc )  
   and exists(Select 'x' from InvHd Where InCoCd=OmCoCd and InTc=OmTc and InChr=OmChr and InNo=OmNo and InPrtKey=OmPrtKey)  
  If @Row > 0  
  begin   
   Select @ErrMsg= 'Cannot Change Customer Code, From, To Design Location as Invoice Record exists'  
   GoTo ErrHndlr  
  end  
  
  
  /*  
    select @row= count('x') from inserted ins where   
     not exists (select 'x' from deleted del where ins.OmTc= del.OmTc   
       and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr   
       and ins.OmNo= del.OmNo and ins.OmDt= del.OmDt  
       and ins.OmHCtCd= del.OmHCtCd)  
     and exists(Select 'x' from OrdDsg where OdCoCd= OmCoCd and OdTc= OmTc   
       and OdYy= OmYy and OdChr= OmChr and OdNo= OmNo)   
    if @row> 0   
    begin  
     select @errmsg= 'Ord Date, Contractor Code Cannot Be Changed When Dsg Rec exists'  
     goto ErrHndlr  
    end  
  */   
   
  /* Partition Check On Current Orddsg Table as if OrdMst is in 'C' then one of the OrdDsg records has to be in 'C'  */   
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and  
   not exists (select 'x' from deleted del where ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
    and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr and ins.OmNo= del.OmNo   
    and ins.OmDt= del.OmDt)  
   and exists(Select 'x' from OrdDsg where OdPrtKey=OmPrtKey and OdOmIdNo=OmIdNo and OdCoCd= OmCoCd   
    and OdTc= OmTc and OdYy= OmYy and OdChr= OmChr and OdNo= OmNo)    
  if @row> 0   
  begin  
   select @errmsg= 'Ord Date Cannot Be Changed When Dsg Rec exists'  
   goto ErrHndlr  
  end  
  
  /****** Zubin 3.02.01 (270308) OmChgPtrOnStwYN cannot be changed when OrdDsg exists ******/  
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and  
   not exists (select 'x' from deleted del where ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
    and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr and ins.OmNo= del.OmNo   
    and ins.OmChgPtrOnStwYN= del.OmChgPtrOnStwYN)  
   and exists(Select 'x' from OrdDsg where OdPrtKey=OmPrtKey and OdOmIdNo=OmIdNo and OdCoCd= OmCoCd   
    and OdTc= OmTc and OdYy= OmYy and OdChr= OmChr and OdNo= OmNo)    
  if @row> 0   
  begin  
   Select @ErrMsg= 'Cannot Change ''Change Pointer On STW (Y/N)'' When Designs Exist'  
   goto ErrHndlr  
  end  
  
  /* **** Zubin 211 **** */  
  /* urmi 2.04-3 OmDt Clause put later to allow change fro the first time */  
  /* Partition Check On Current Db */   
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and  
   not exists (select 'x' from deleted del where ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
    and ins.OmCoCd= del.OmCoCd and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr   
    and ins.OmNo= del.OmNo and Ins.OmOrgDelDt= del.OmOrgDelDt)   
   and exists (select 'x' from deleted del where ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
    and ins.OmCoCd= del.OmCoCd and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr   
    and ins.OmNo= del.OmNo and del.OmOrgDelDt <> '01/01/80' )  
  /* **** Zubin 211 **** */  
  if @row> 0   
  begin  
   select @errmsg= 'Original Production Delivery Date Cannot Be Changed'  
   goto ErrHndlr  
  end  
  
  /* **** Zubin 211 **** */  
  /* Partition Check On Current Db */   
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and  
   not exists (select 'x' from deleted del where ins.OmIdNo=del.OmIdNo and ins.OmCoCd= del.OmCoCd   
     and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr   
     and ins.OmNo= del.OmNo and ins.OmPrtKey=del.OmPrtKey  
     and Ins.OmOrgExpDelDt= del.OmOrgExpDelDt )  
   and exists (select 'x' from deleted del where ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
    and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr   
     and ins.OmNo= del.OmNo and del.OmOrgExpDelDt<> '01/01/80')   
  /* **** Zubin 211 **** */  
  if @row> 0   
  begin  
   select @errmsg= 'Original Export Delivery Date Cannot Be Changed'  
   goto ErrHndlr  
  end  
/* urmi 2.04-3 OmDt Clause put later to allow change fro the first time */  
  
  /* Zubin 213 (OmCnvFct cannot be changed when rec exists in OrdDsg) */   
  /* Partition Check On Current Db */   
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and  
   Not Exists (select 'x' from deleted del where ins.OmIdNo=del.OmIdNo and ins.OmTc= del.OmTc   
     and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr and ins.OmNo= del.OmNo   
     and ins.OmPrtKey=del.OmPrtKey and ins.OmCnvFct= del.OmCnvFct)  
   And Exists(Select 'x' from OrdDsg where OdOmIdNo=OmIdNo and OdCoCd= OmCoCd and OdTc= OmTc   
     and OdYy= OmYy and OdChr= OmChr and OdNo= OmNo and OdPrtKey=OmPrtKey)   
  if @row> 0   
  begin  
   select @errmsg= 'Order Conversion Factor Cannot Be Changed When Design Record(s) Exist'  
   goto ErrHndlr  
  end  
  
  /* Zubin 213 (OmMulDiv cannot be changed when rec exists in OrdDsg) */   
  /* Check on Current Partition only */  
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and  
   Not Exists (select 'x' from deleted del where ins.OmIdNo=del.OmIdNo and ins.OmTc= del.OmTc   
     and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr   
     and ins.OmNo= del.OmNo and ins.OmPrtKey=del.OmPrtKey and ins.OmMulDiv= del.OmMulDiv)  
   And Exists(Select 'x' from OrdDsg where OdOmIdNo=OmIdNo and OdCoCd= OmCoCd and OdTc= OmTc   
     and OdYy= OmYy and OdChr= OmChr and OdNo= OmNo and OdPrtKey=OmPrtKey)   
  if @row> 0   
  begin  
   select @errmsg= 'Order Multiplication / Division Cannot Be Changed When Design Record(s) Exist'  
   goto ErrHndlr  
  end  
 End  
  
 if @mode in ('A','C')  
 Begin  
  /******  OmCoCd = HCoCd   *******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and  
    not exists (select 'x' from Head where HCoCd= OmCoCd and HCd= @wHCd)  
  if @row> 0   
  begin   
   select @errMsg= 'Company Code Not Valid'  
   goto ErrHndlr  
  end  
  
  Select @Row=Count('x') from Inserted  where OmTc='JIN'   
  and Not Exists(Select 'x' From Head where HCoCd=OmBaseCoCd and HCd= @wHCd)     
     If @Row > 0    
     Begin    
   Select @ErrMsg= 'Base Company Code Cannot be Blank/Invalid.'    
   GoTo ErrHndlr    
  end    		

  /****** The Entry Type should Be 'OM' ******/  
  /* Current Partition */  
  /*** JAY 3.3(FG) [FG ADD]***/   
  /* Manali Trading Module - 'JT' */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and  
   not exists (select 'x' from Param where PTyp='TC' and PMCd=OmTc and   
        PValue in (Select PMCd from Param where PTyp='TCTYP' and PValue1 IN ('JT','FG','OM')))  
  if @row> 0   
  begin  
   select @errmsg='Voucher Tc Not Defined'  
   goto ErrHndlr  
  end  
  
  /******  OmYy  =  PMCd ('YY')  ******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and  
   not exists (select 'x' from Param where PTyp= 'YY' and PMCd= OmYy)  
  if @row> 0   
  begin  
   select @errmsg= 'Voucher Year Not Defined'  
   goto ErrHndlr  
  end  
  
  /******  OmChr  =  PMCd ('CHR')  ******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and  
   not exists (select 'x' from vParam where vPCoCd= OmCoCd and   
     vPTyp= 'CHR' and vPMCd= OmTc and vPSCd= OmChr)  
  if @row> 0   
  begin  
   select @errmsg= 'Voucher Character Not Defined'  
   goto ErrHndlr  
  end  
  
  /******  OmNo  >  0  ******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmNo<= 0 and OmPrtKey=@wCurrPrtn   
  if @row> 0   
  begin  
   select @errmsg= 'Voucher Number Cannot Be <= Zero'  
   goto ErrHndlr  
  end  
  
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */  
  /******  OmCmCd  <> Blank ******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmCmCd= '' and OmPrtKey=@wCurrPrtn   
  if @row> 0  
  begin  
   select @errmsg= 'Customer Code Can Not Blank'  
   goto ErrHndlr  
  end  
  
  /******  OmCmCd  =  CmCd from CustMst (CmCtg = 'C')  ******/  
  /******  if OmCmCd Changed Then OmCmCd = Valid CmCd from CustMst (CmCtg = 'C')  ******/  
  /* Current Partition */  
  /* ***** Manali Trading Module - CmCtg='C' changed to CmCtg=OmCmCtg */  
  select @row= count('x') from Inserted Ins Where ins.OmPrtKey=@wCurrPrtn and  
   Ins.OmCmCd <> IsNull((Select Del.OmCmCd From Deleted Del Where   
    Ins.OmIdNo=Del.OmIdNo and Ins.OmCoCd = Del.OmCoCd And Ins.OmTc = Del.OmTc And Ins.OmYy = Del.OmYy And   
    Ins.OmChr = Del.OmChr And Ins.OmNo = Del.OmNo And Ins.OmPrtKey=Del.OmPrtKey), '')  And   
   Not Exists (select 'x' from CustMst where CmCtg=Ins.OmCmCtg /*'C'*/ And CmCd= Ins.OmCmCd And CmValidYN = 'Y')  
  if @row> 0  
  begin  
   select @errmsg= 'Customer Code Not Defined / Invalid'  
   goto ErrHndlr  
  end  
  
  /* Zubin 213 (Cur Cd shld be valid) */   
  /* **** Manali Trading Module check Changed for 'JT' */  
/*  select @row= count('x') from Inserted Ins Where   
   ( (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)= 'JT' and  
    Not exists (select 'x' from CustMst where CmCtg= OmCmCtg and CmCd= OmCmCd and CmCurCd= OmCmCurCd)   
   ) */ 
  select @row= count('x') from Inserted Ins Where   
   ( (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)= 'JT' and ins.OmTc <> 'JMT' and   
    Not exists (select 'x' from CustMst where CmCtg= OmCmCtg and CmCd= OmCmCd and CmCurCd= OmCmCurCd)   
   )  
   Or  
   ( (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)<> 'JT' and  
   ((    (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)= 'PL' and   
    (  
     (   
      ( ins.OmCmCd= 'ZSELF' and Exists (Select 'x' from Head where HCd= @wHCd and   
      HCoCd= 'ZZZ' and HMultiCurYn= 'Y' ) and   
        Not Exists(select 'x' from Param where PTyp= 'CURNCY' and   
      PMCd= OmCmCurCd and PSCd= '')   
       )  
      OR   
       ( ins.OmCmCd= 'ZSELF' and Exists (Select 'x' from Head where HCd= @wHCd and   
      HCoCd= 'ZZZ' and HMultiCurYn= 'N' ) and   
        Not Exists(select 'x' from CustMst where CmCtg= OmCmCtg and   
      CmCd= OmCmCd and CmCurCd= OmCmCurCd)   
        )   
      )   
     Or   
     ( ins.OmCmCd<> 'ZSELF' and Not exists (select 'x' from CustMst where CmCtg= OmCmCtg and   
      CmCd= OmCmCd and CmCurCd= OmCmCurCd)  
      )  
            )  
          )  
          Or   
          (    (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)<> 'PL' and   
    Not exists (select 'x' from CustMst where CmCtg= 'C' and CmCd= OmCmCd and   
      CmCurCd= OmCmCurCd)   
     ))  
   )  
  if @row> 0   
  begin  
   select @errmsg= 'Invalid Currency Code'   
   goto ErrHndlr  
  end  
  
/*  
  select @row= count('x') from Inserted Ins Where   
   ( (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)= 'JT' and  
    Not exists (select 'x' from CustMst where CmCtg= OmCmCtg and CmCd= OmCmCd and CmCurCd= OmCmCurCd)   
   )  
   Or  
   ( (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)<> 'JT' and  
   ((    (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)= 'PL' and   
    (  
     (   
      ( ins.OmCmCd= 'ZSELF' and Exists (Select 'x' from Head where HCd= @wHCd and   
      HCoCd= 'ZZZ' and HMultiCurYn= 'Y' ) and   
        Not Exists(select 'x' from Param where PTyp= 'CURNCY' and   
      PMCd= OmCmCurCd and PSCd= '')   
       )  
      OR   
       ( ins.OmCmCd= 'ZSELF' and Exists (Select 'x' from Head where HCd= @wHCd and   
      HCoCd= 'ZZZ' and HMultiCurYn= 'N' ) and   
        Not Exists(select 'x' from CustMst where CmCtg= 'C' and   
      CmCd= OmCmCd and CmCurCd= OmCmCurCd)   
        )   
      )   
     Or   
