/*  #########################################  Manoj  #########################################  */  
  
  /****** In Party-Design Combination Master The CoCd should be 'ZZZ' ******/  
  /* Current Partition */  
  select @row= count('x') from inserted ins where ins.OmCoCd<> @wSelfCoCd and ins.OmPrtKey=@wCurrPrtn and  
        (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)= 'PL'   
  if @row> 0  
  begin  
   select @errmsg= 'The Company Code Should be ''' + @wSelfCoCd + ''' In Party-Design Combination Master'  
   goto ErrHndlr  
  end  
  
  /* Zubin 213 (Before 213) */   
  /****** There Can Be Only One Entry Per Customer In Party-Design Combination Master ******/  
/*  select @row= count('x') from inserted ins where   
        (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)= 'PL'  and   
        (Select count('x') from OrdMst OM where ins.OmCoCd= Om.OmCoCd   
        and ins.OmCmCd= Om.OmCmCd and   
        (Select PValue from Param where  PTyp= 'TC' and PMCd= OM.OmTc)= 'PL') > 1   
*/   
  /* Zubin 213 (PDC combination shld be only one for a cust and only one for 'ZSELF' per currency) */   
  /* 3.02 Check below will be on complete partition as pdc might exist in the previous partition */  
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and  
        (Select PValue from Param where PTyp= 'TC' and PMCd= ins.OmTc)= 'PL'  and   
        (Select count('x') from OrdMst OM where ins.OmCoCd= Om.OmCoCd   
         and ins.OmCmCd= Om.OmCmCd and ins.OmCmCurCd= OM.OmCmCurCd and   
         (Select PValue from Param where  PTyp= 'TC' and PMCd= OM.OmTc)= 'PL' and   
      Om.OmPrtKey=@wCurrPrtn) > 1   
  if @row> 0  
  begin  
   select @errmsg= 'Record Already Exists For This Customer In Party-Design Combination Master'  
   goto ErrHndlr  
  end  
  
  /******  OmDt  <>  '01/01/1980'  or  '01/01/1900'  (The dates '01/01/1980'  and  '01/01/1900'  are considered as blank) ******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and OmDt in('01/01/1980', '01/01/1900')  
  if @row> 0   
  begin  
   select @errmsg= 'Date Cannot Be Blank'  
   goto ErrHndlr  
  end  
  
  /******  OmLmgCst, OmLmpCst, OmLmsCst  >  0  ******/    
  /* Current Partition */  
  /* ****** Manali 3.03 - 19/08/06 - Pd Mod - OmLmlCst included */  
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and (OmLmgCst<= 0 or OmLmpCst<= 0 or (exists   
  (select 'x' from Head where HCoCd=ins.OmCoCd And HSlvModYN='Y') And (OmLmsCst<=0))  
  or (exists (select 'x' from Head where HCoCd=ins.OmCoCd And HPdModYN='Y') And (OmLmlCst<=0)))  
  if @row> 0   
  begin  
   select @errmsg= 'LMG, LMP, LMS, LML Cost Cannot Be <= Zero'  
   goto ErrHndlr  
  end  
  
  /******  OmLmgDt, OmLmpDt, OmLmsDt  <>  Blank  ******/  
  /* Current Partition */  
  /* ****** Manali 3.03 - 19/08/06 - Pd Mod - OmLmlDt included */  
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and (OmLmgDt= '' or OmLmpDt= '' or (exists   
  (select 'x' from Head where HCoCd=ins.OmCoCd And HSlvModYN='Y') And (OmLmsDt=''))  
  or (exists (select 'x' from Head where HCoCd=ins.OmCoCd And HPdModYN='Y') And (OmLmlDt='')))  
  if @row> 0   
  begin  
   select @errmsg= 'LMG, LMP, LMS, LML Date Cannot Be Blank'  
   goto ErrHndlr   end  
  
  /******  OmLmgSal, OmLmpSal, OmLmsSal  >  0  ******/    
  /* Current Partition */  
  /* ****** Manali 3.03 - 19/08/06 - Pd Mod - OmLmlSal included */  
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and (OmLmgSal<= 0 or OmLmpSal<= 0 or (exists   
  (select 'x' from Head where HCoCd=ins.OmCoCd And HSlvModYN='Y') And (OmLmsSal<=0))   
  or (exists (select 'x' from Head where HCoCd=ins.OmCoCd And HPdModYN='Y') And (OmLmlSal<=0)))   
  if @row> 0   
  begin  
   select @errmsg= 'LMG, LMP, LMS, LML Sales Value Cannot Be <= Zero'  
   goto ErrHndlr  
  end  
  
 /* **** Zubin 211 **** */   
   /******  OmDelDt  >=  OmDt  ******/    
