Insert into TrgDisa values ('InvHd')
GOGO

Update OrdMst set OmCmCtg = 'Z', OmCmCd = rtrim(SUBSTRING (OmCmCd,3,6)) 
where (OmTc='JIN' or OmTc='JOT') and OmCmCtg='C' and SUBSTRING(omCmCd,1,2)='Z-'
GOGO
Update InvHd set InCmCd = rtrim(SUBSTRING (InCmCd,3,6)) 
where (InTc='JIN' or InTc='JOT') and SUBSTRING(InCmCd,1,2)='Z-'
GOGO

Delete from TrgDisa
GOGO

Update TcMst set TmCmCtg = 'Z', TmSrcCmCtg = 'Z' where TmTc in ('JIN','JOT')

Insert into trgdisa values ('Param')

Update Param set PNum1 = 1 where PDesc225 = 'Y' and PTyp = 'RMSCTG'  

delete from trgdisa  


GOGO


SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED


GOGO

